INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听人讲述或播放朗读的书籍内容。", "primary_collocate": null, "pronunciation": "tīng shū", "ipa": "tʰiŋ˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "我每天坐地铁的时候听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班路上用耳机听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听书，你能帮我找一本好听的吗？", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做饭的时候总是听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事很有意思，我昨天晚上听书听到很晚。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友推荐我听书，说比看书轻松。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步的时候听书，时间过得特别快。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听书的时候，主播的声音很好听，我一听就喜欢。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车上打开手机，开始听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人喜欢睡前听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听过书", "label": "体标"}, {"form": "听着书", "label": "体标"}, {"form": "聽書", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用手机或耳机播放朗读的书籍内容来听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b5a7c1a-21c0-4822-b161-907b245b99f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听书", "is_correct": true, "explanation": "正确。听书指用手机或耳机播放朗读的内容来听，与“坐地铁”的语境相符。"}, {"text": "开车", "is_correct": false, "explanation": "语义：坐地铁的时候不能开车，与句中的情境矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐地铁的时候不能游泳，与句中的情境矛盾。"}, {"text": "踢足球", "is_correct": false, "explanation": "语义：坐地铁的时候不能踢足球，与句中的情境矛盾。"}], "explanations": {"听书": "正确。听书指用手机或耳机播放朗读的内容来听，与“坐地铁”的语境相符。", "开车": "语义：坐地铁的时候不能开车，与句中的情境矛盾。", "游泳": "语义：坐地铁的时候不能游泳，与句中的情境矛盾。", "踢足球": "语义：坐地铁的时候不能踢足球，与句中的情境矛盾。"}, "sentence_index": 0, "correct_answer": "听书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他低头在电脑前把书的内容一句句打进去，这就是听书。", "explanation": "这里应该用〈录入〉。听书是听人念或播放的朗读，把文字一句句打进电脑是录入，不是听书。"}, {"text": "我用打印机听书，纸上的字很清楚。", "explanation": "这里应该用〈印书〉。听书是播放声音，不会在纸上印出字。"}, {"text": "我不用耳机，自己对着手机大声朗读，这也算听书。", "explanation": "这里的〈听书〉被用成了“自己出声念书”的意思。听书是听别人或录好的朗读，自己出声念不是听书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听书", "is_correct": true, "explanation": "正确。听书指用耳机听播放的朗读，与“跑步”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：跑步的时候不能睡觉，与句中的动作矛盾。"}, {"text": "骑车", "is_correct": false, "explanation": "语义：跑步和骑车不能同时进行，句中的情境不合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：跑步的时候不能同时游泳，与句中的情境矛盾。"}], "explanations": {"听书": "正确。听书指用耳机听播放的朗读，与“跑步”的语境相符。", "睡觉": "语义：跑步的时候不能睡觉，与句中的动作矛盾。", "骑车": "语义：跑步和骑车不能同时进行，句中的情境不合。", "游泳": "语义：跑步的时候不能同时游泳，与句中的情境矛盾。"}, "sentence_index": 6, "correct_answer": "听书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把自己的声音录下来，这就是听书。", "explanation": "这里应该用〈录音〉。听书是听已经录好的朗读，录下自己的声音不叫听书。"}, {"text": "他闭着眼睛把课文背出来，这就叫听书。", "explanation": "这里应该用〈背诵〉。背诵是靠记忆说出内容，不是用耳朵听别人念。"}, {"text": "他把书一页页抄下来，这就叫听书。", "explanation": "这里应该用〈抄书〉。抄书要照着书上的字写，不是听书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上周用手机听书听很开心。", "corrected_sentence": "我上周用手机听书听得很开心。", "error_description": "错误：“听书听很开心”。正确：“听书听得很开心”。动词“听”和后面的补语“很开心”之间要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨晚用手机听书了一个小时。", "corrected_sentence": "我昨晚用手机听书听了一个小时。", "error_description": "错误：“听书了一个小时”。正确：“听书听了一个小时”。动词“听”带时段补语时要重复动词，“了”放在第二个“听”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
