INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "股价是买一家公司的一小份要花的钱。", "primary_collocate": null, "pronunciation": "gǔ jià", "ipa": "ku˨˩˦ tɕjɑ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的股价很高，我买不起。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想买这家公司的股票，先要看股价。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股价便宜，所以很多年轻人想买。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股价只要五块钱。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸问我：“这家公司的股价是多少？”", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股价太贵了，我不打算买。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一份要花多少钱，就看股价。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司的股价常常比较低。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一些股价不高的股票。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先查了股价，再决定买不买。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股價", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买公司一小份要花的钱；买股票的成本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "股价", "is_correct": true, "explanation": "正确。股价是买一小份股票要花的钱，“很高，我买不起”说的正是这个钱。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”形容人的体形，不能用来形容一家公司的钱。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人或动物的体温，与公司无关。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”能说“长”，但不能说“很高”来形容买一份股票的钱。"}], "explanations": {"股价": "正确。股价是买一小份股票要花的钱，“很高，我买不起”说的正是这个钱。", "身材": "体貌：“身材”形容人的体形，不能用来形容一家公司的钱。", "体温": "语义：“体温”指人或动物的体温，与公司无关。", "寿命": "搭配：“寿命”能说“长”，但不能说“很高”来形容买一份股票的钱。"}, "sentence_index": 0, "correct_answer": "股价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的股价达到一百亿。", "explanation": "这里应该用〈市值〉。股价是买一小份股票的钱，整家公司的总价值要用市值。"}, {"text": "进这个乐园的股价是五十元。", "explanation": "这里应该用〈入场费〉。股价只指买股票的钱，进园要交的费用要用入场费。"}, {"text": "这笔存款的股价很高。", "explanation": "这里应该用〈利息〉。股价只指买股票的钱，存款的收益要用利息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股价", "is_correct": true, "explanation": "正确。“买一份要花多少钱，就看股价”，看的正是买一份股票要花的钱，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”说的是外观，与花多少钱无关，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“看”后面的“身高”与“花多少钱”无法搭配，句意说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，与买一份股票要花的钱无关。"}], "explanations": {"股价": "正确。“买一份要花多少钱，就看股价”，看的正是买一份股票要花的钱，符合句意。", "颜色": "语义：“颜色”说的是外观，与花多少钱无关，句子不通。", "身高": "搭配：“看”后面的“身高”与“花多少钱”无法搭配，句意说不通。", "体重": "语义：“体重”指人或动物的重量，与买一份股票要花的钱无关。"}, "sentence_index": 6, "correct_answer": "股价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿饭的股价是五十块。", "explanation": "这里应该用〈餐费〉。股价只指买股票的钱，吃饭要付的钱叫餐费。"}, {"text": "这场电影的股价是五十块。", "explanation": "这里应该用〈票价〉。股价只指股票的价格，买电影票的钱要用票价。"}, {"text": "这个学期的股价是五千。", "explanation": "这里应该用〈学费〉。股价只指股票的价格，上学要交的钱要用学费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的股价昨天了涨两块钱。", "corrected_sentence": "这家公司的股价昨天涨了两块钱。", "error_description": "“了”位置错误：“涨了”的“了”要放在动词“涨”后面，应说“涨了”，不能说“了涨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "买股票前，我先买股价。", "corrected_sentence": "买股票前，我先看股价。", "error_description": "搭配错误：“买”的对象是股票，不能说“买股价”；应说“先看股价”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
