INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "股票的价格。", "primary_collocate": null, "pronunciation": "gǔ jià", "ipa": "ku˨˩˦ tɕjɑ˥˩", "syllable_count": 2, "sentences": [{"text": "今天这家公司的股价涨了。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都看股价。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股价一下子从十块降到了八块。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息出来以后，公司的股价上涨了。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的股价最近很稳。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担心股价会继续下跌。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机很受欢迎，所以股价涨得很快。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只股票的股价是五十元。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两天公司的股价跌得很厉害。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年股价低，今年股价高。", "target_word": "股价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股價", "label": "繁体"}], "register": "中性", "sense_fingerprint": "股票的价格；股价涨跌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "股价", "is_correct": true, "explanation": "正确。股价指股票的价格，“涨了”说的是股票价格上涨，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或动物的身体高度，不能用来说一家公司。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“涨”，“今天这家公司的天气涨了”搭配不当。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“涨”用于价格、数量等，不能说“年龄涨了”，搭配不当。"}], "explanations": {"股价": "正确。股价指股票的价格，“涨了”说的是股票价格上涨，符合句意。", "身高": "语义：“身高”指人或动物的身体高度，不能用来说一家公司。", "天气": "搭配：“天气”不能说“涨”，“今天这家公司的天气涨了”搭配不当。", "年龄": "搭配：“涨”用于价格、数量等，不能说“年龄涨了”，搭配不当。"}, "sentence_index": 0, "correct_answer": "股价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的股价是三千块。", "explanation": "这里应该用〈旅费〉。股价只指股票的价格，旅行要花的钱叫旅费。"}, {"text": "这家店的股价很便宜。", "explanation": "这里应该用〈价格〉。股价只指股票的价格，店里商品的价钱要用价格。"}, {"text": "这种苹果的股价是五块钱。", "explanation": "这里应该用〈单价〉。股价只指股票的价格，苹果的价钱要用单价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股价", "is_correct": true, "explanation": "正确。股价指股票的价格，“涨得很快”说的是股票价格上涨，符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人或动物的体温，不能用来说手机之类的东西。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”形容人的体形，不能用来说一个价格或数量在上涨。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”不能说“涨得很快”，与“涨”搭配不当。"}], "explanations": {"股价": "正确。股价指股票的价格，“涨得很快”说的是股票价格上涨，符合句意。", "体温": "语义：“体温”指人或动物的体温，不能用来说手机之类的东西。", "身材": "语义：“身材”形容人的体形，不能用来说一个价格或数量在上涨。", "寿命": "搭配：“寿命”不能说“涨得很快”，与“涨”搭配不当。"}, "sentence_index": 6, "correct_answer": "股价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次搬家的股价是两千块。", "explanation": "这里应该用〈搬家费〉。股价只指股票的价格，搬家要花的钱叫搬家费。"}, {"text": "寄这封信的股价是三块钱。", "explanation": "这里应该用〈邮费〉。股价只指股票的价格，寄信的费用要用邮费。"}, {"text": "这个房子的股价很高。", "explanation": "这里应该用〈房价〉。股价只指股票的价格，房子的价格要用房价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的新产品很受欢迎，股价涨地很快。", "corrected_sentence": "这家公司的新产品很受欢迎，股价涨得很快。", "error_description": "补语标记错误：“涨得很快”中的补语要用“得”，不能用“地”。“地”用于状语，“涨地很快”错误，应说“涨得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他打开手机，先买股价。", "corrected_sentence": "他打开手机，先查看股价。", "error_description": "搭配错误：“买”的对象是股票，不能说“买股价”；对股价应说“查看”或“关注”，应说“先查看股价”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "瘦", "is_correct": true, "explanation": "正确答案：瘦与胖是一对反义词，指身上的肉少。"}, {"text": "高", "is_correct": false, "explanation": "高说身高，与胖没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢说速度，与胖没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快说速度，与胖没有反义关系。"}], "correct_answer": "瘦", "explanations": {"瘦": "正确答案：瘦与胖是一对反义词，指身上的肉少。", "高": "高说身高，与胖没有反义关系。", "慢": "慢说速度，与胖没有反义关系。", "快": "快说速度，与胖没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "瘦", "is_correct": true, "explanation": "正确答案：瘦与胖是一对反义词，指身上的肉少。"}, {"text": "矮", "is_correct": false, "explanation": "矮说身高，与胖没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻是重的反义词，说分量，不是胖的反义词。"}, {"text": "软", "is_correct": false, "explanation": "软说质地，与胖没有反义关系。"}], "correct_answer": "瘦", "explanations": {"瘦": "正确答案：瘦与胖是一对反义词，指身上的肉少。", "矮": "矮说身高，与胖没有反义关系。", "轻": "轻是重的反义词，说分量，不是胖的反义词。", "软": "软说质地，与胖没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "胖是身上的肉多，看起来圆圆的。", "primary_collocate": null, "pronunciation": "pàng", "ipa": "pʰɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他的脸圆圆的，看起来很胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟小时候很胖，现在很瘦。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小了，我穿着显得很胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吃得太多，最近胖了不少。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我太胖，要多运动。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又高又胖，走路很慢。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个胖老师笑着走进教室。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一点儿都不胖，不用减肥。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕太胖，晚上不吃米饭。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆圆的脸，圆圆的肚子，他真胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "胖胖的", "label": "重叠"}, {"form": "胖子", "label": "复合"}, {"form": "发胖", "label": "复合"}], "register": "中性", "sense_fingerprint": "胖：人身上肉多、外形圆圆的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76794e94-6924-4452-985d-713c29f920c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖（pàng），身上肉多。"}, {"text": "旁", "is_correct": false, "explanation": "páng（第二声）与 pàng（第四声）声调不同，意思是旁边。"}, {"text": "放", "is_correct": false, "explanation": "fàng 与 pàng 声母不同（f 与 p），意思是放置。"}, {"text": "盼", "is_correct": false, "explanation": "pàn 与 pàng 韵尾不同（n 与 ng），意思是期盼。"}, {"text": "棒", "is_correct": false, "explanation": "bàng 与 pàng 声母不同（b 与 p，不送气与送气），意思是棒子。"}], "explanations": {"胖": "正确答案：胖（pàng），身上肉多。", "旁": "páng（第二声）与 pàng（第四声）声调不同，意思是旁边。", "放": "fàng 与 pàng 声母不同（f 与 p），意思是放置。", "盼": "pàn 与 pàng 韵尾不同（n 与 ng），意思是期盼。", "棒": "bàng 与 pàng 声母不同（b 与 p，不送气与送气），意思是棒子。"}, "sentence_index": null, "correct_answer": "胖"}, "level_3": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖指身上肉多，与“圆圆的脸”的描写相合。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，不能用来描写脸的样子。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度或节奏，与描写外貌的“圆圆的脸”不搭。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“看起来很远”不能用来描写外貌，“远”说的是距离。"}], "explanations": {"胖": "正确答案：胖指身上肉多，与“圆圆的脸”的描写相合。", "快": "语义：“快”说速度，不能用来描写脸的样子。", "慢": "语义：“慢”说速度或节奏，与描写外貌的“圆圆的脸”不搭。", "远": "搭配：“看起来很远”不能用来描写外貌，“远”说的是距离。"}, "sentence_index": 0, "correct_answer": "胖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地很胖，能种很多菜。", "explanation": "这里应该用〈肥〉。胖用于人或动物的身体，说土地肥沃要用肥。"}, {"text": "这块木头很胖，用锯子锯不开。", "explanation": "这里应该用〈硬〉。胖用于人或动物的身体，木头的软硬要用硬。"}, {"text": "这个房间很胖，可以放下两张床。", "explanation": "这里应该用〈宽〉。胖不用于空间，房间的宽窄要用宽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖（pàng），身上肉多。"}, {"text": "庞", "is_correct": false, "explanation": "páng（第二声）与 pàng（第四声）声调不同，意思是庞大。"}, {"text": "判", "is_correct": false, "explanation": "pàn 与 pàng 韵尾不同（n 与 ng），意思是判断。"}, {"text": "碰", "is_correct": false, "explanation": "pèng 与 pàng 主要元音不同（e 与 a），意思是碰撞。"}], "explanations": {"胖": "正确答案：胖（pàng），身上肉多。", "庞": "páng（第二声）与 pàng（第四声）声调不同，意思是庞大。", "判": "pàn 与 pàng 韵尾不同（n 与 ng），意思是判断。", "碰": "pèng 与 pàng 主要元音不同（e 与 a），意思是碰撞。"}, "sentence_index": null, "correct_answer": "胖"}, "level_3": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖描写老师的体形，与“笑着走进教室”相容。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：“圆”描写形状，不能直接修饰“老师”这类人的特征。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”说的是含水的状态，不能形容老师。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”形容温度，不能用来修饰“老师”。"}], "explanations": {"胖": "正确答案：胖描写老师的体形，与“笑着走进教室”相容。", "圆": "搭配：“圆”描写形状，不能直接修饰“老师”这类人的特征。", "湿": "语义：“湿”说的是含水的状态，不能形容老师。", "烫": "搭配：“烫”形容温度，不能用来修饰“老师”。"}, "sentence_index": 6, "correct_answer": "胖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种颜色很胖，看起来很暗。", "explanation": "这里应该用〈深〉。胖只用于人或动物的身体，颜色的深浅要用深。"}, {"text": "这碗粥很胖，喝着没味道。", "explanation": "这里应该用〈稀〉。胖用于人或动物的身体，粥的稀稠要用稀。"}, {"text": "这条路很胖，要走一个小时。", "explanation": "这里应该用〈长〉。胖不用于道路，路的长短要用长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id 