INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最近胖发了。", "corrected_sentence": "我最近发胖了。", "error_description": "“发胖”是固定的词，“发”在前、“胖”在后。“胖发了”语序错误，应说“发胖了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很胖得厉害，走路都慢了。", "corrected_sentence": "他胖得厉害，走路都慢了。", "error_description": "“胖得厉害”是程度补语结构，“很”不能放在“胖”前面。“很胖得厉害”错误，应说“胖得厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93312, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "瘦", "is_correct": true, "explanation": "正确答案：瘦与胖相对，指人或动物脂肪少。"}, {"text": "矮", "is_correct": false, "explanation": "矮说身高，与胖没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快说速度，与胖没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻说分量，是重的反义词，不是胖的反义词。"}], "correct_answer": "瘦", "explanations": {"瘦": "正确答案：瘦与胖相对，指人或动物脂肪少。", "矮": "矮说身高，与胖没有反义关系。", "快": "快说速度，与胖没有反义关系。", "轻": "轻说分量，是重的反义词，不是胖的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93312, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "瘦", "is_correct": true, "explanation": "正确答案：瘦与胖相对，指人或动物脂肪少。"}, {"text": "高", "is_correct": false, "explanation": "高说身高，与胖没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢说速度，与胖没有反义关系。"}, {"text": "软", "is_correct": false, "explanation": "软说质地，与胖没有反义关系。"}], "correct_answer": "瘦", "explanations": {"瘦": "正确答案：瘦与胖相对，指人或动物脂肪少。", "高": "高说身高，与胖没有反义关系。", "慢": "慢说速度，与胖没有反义关系。", "软": "软说质地，与胖没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93312, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（人或动物）脂肪多，肉多，与瘦相对。", "primary_collocate": null, "pronunciation": "pàng", "ipa": "pʰɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这只猫太胖了，跑不快。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比去年胖了五公斤。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里的猪又大又胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥很瘦，我弟弟很胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你太胖了，别再吃蛋糕了。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗吃得太多，越来越胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不胖也不瘦，身材正好。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胖的人容易累，要多走路。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟胖得飞不起来。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想吃甜的，可是我怕胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "胖胖的", "label": "重叠"}, {"form": "胖子", "label": "复合"}, {"form": "发胖", "label": "复合"}], "register": "中性", "sense_fingerprint": "胖：人或动物脂肪多，与瘦相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76794e94-6924-4452-985d-713c29f920c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖（pàng），人或动物脂肪多。"}, {"text": "旁", "is_correct": false, "explanation": "páng（第二声）与 pàng（第四声）声调不同，意思是旁边。"}, {"text": "放", "is_correct": false, "explanation": "fàng 与 pàng 声母不同（f 与 p），意思是放置。"}, {"text": "盼", "is_correct": false, "explanation": "pàn 与 pàng 韵尾不同（n 与 ng），意思是期盼。"}, {"text": "棒", "is_correct": false, "explanation": "bàng 与 pàng 声母不同（b 与 p，不送气与送气），意思是棒子。"}], "explanations": {"胖": "正确答案：胖（pàng），人或动物脂肪多。", "旁": "páng（第二声）与 pàng（第四声）声调不同，意思是旁边。", "放": "fàng 与 pàng 声母不同（f 与 p），意思是放置。", "盼": "pàn 与 pàng 韵尾不同（n 与 ng），意思是期盼。", "棒": "bàng 与 pàng 声母不同（b 与 p，不送气与送气），意思是棒子。"}, "sentence_index": null, "correct_answer": "胖"}, "level_3": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖指脂肪多，与“跑不快”的因果关系相合。"}, {"text": "快", "is_correct": false, "explanation": "语义：“太快了”与后句“跑不快”矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能形容猫的体态。"}, {"text": "黑", "is_correct": false, "explanation": "体貌：“黑”说毛色，与“跑不快”的体态描述不搭。"}], "explanations": {"胖": "正确答案：胖指脂肪多，与“跑不快”的因果关系相合。", "快": "语义：“太快了”与后句“跑不快”矛盾。", "甜": "搭配：“甜”说味道，不能形容猫的体态。", "黑": "体貌：“黑”说毛色，与“跑不快”的体态描述不搭。"}, "sentence_index": 0, "correct_answer": "胖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山很胖，我爬不上去。", "explanation": "这里应该用〈高〉。胖用于人或动物的身体，山的高低要用高。"}, {"text": "他跑得很胖。", "explanation": "这里应该用〈快〉。胖只用于身体，说速度要用快。"}, {"text": "学校很胖，我每天走路去。", "explanation": "这里应该用〈远〉。胖不用于距离，学校的远近要用远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93312, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖（pàng），人或动物脂肪多。"}, {"text": "庞", "is_correct": false, "explanation": "páng（第二声）与 pàng（第四声）声调不同，意思是庞大。"}, {"text": "判", "is_correct": false, "explanation": "pàn 与 pàng 韵尾不同（n 与 ng），意思是判断。"}, {"text": "碰", "is_correct": false, "explanation": "pèng 与 pàng 主要元音不同（e 与 a），意思是碰撞。"}, {"text": "荡", "is_correct": false, "explanation": "dàng 与 pàng 声母不同（d 与 p），意思是荡漾。"}], "explanations": {"胖": "正确答案：胖（pàng），人或动物脂肪多。", "庞": "páng（第二声）与 pàng（第四声）声调不同，意思是庞大。", "判": "pàn 与 pàng 韵尾不同（n 与 ng），意思是判断。", "碰": "pèng 与 pàng 主要元音不同（e 与 a），意思是碰撞。", "荡": "dàng 与 pàng 声母不同（d 与 p），意思是荡漾。"}, "sentence_index": null, "correct_answer": "胖"}, "level_3": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖与“不瘦”相对，与“不……也不瘦”的结构相合。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，不能与体形的比较相接。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”说光线或神采，不说身体的肥瘦。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，与身体状况无关。"}], "explanations": {"胖": "正确答案：胖与“不瘦”相对，与“不……也不瘦”的结构相合。", "慢": "语义：“慢”说速度，不能与体形的比较相接。", "亮": "搭配：“亮”说光线或神采，不说身体的肥瘦。", "远": "语义：“远”说距离，与身体状况无关。"}, "sentence_index": 6, "correct_answer": "胖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯很胖，屋子里一下子就照得很清楚。", "explanation": "这里应该用〈亮〉。胖用于人或动物的身体，灯光的明暗要用亮。"}, {"text": "这条河很胖，人可以游过去。", "explanation": "这里应该用〈窄〉。胖不用于河流，河面窄才能游过去，要用窄。"}, {"text": "这件事很胖，很难办。", "explanation": "这里应该用〈复杂〉。胖只用于身体，事情的繁难要用复杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只猫胖的走不动了。", "corrected_sentence": "这只猫胖得走不动了。", "error_description": "“胖得走不动”中“得”引出补语。“胖的”错用了“的”，应说“胖得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人胖很，但是很友好，大家都喜欢他。", "corrected_sentence": "那个人很胖，但是很友好，大家都喜欢他。", "error_description": "“很”是程度副词，要放在形容词“胖”前面。“胖很”语序错误，应说“很胖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
