INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "货物是车和船运来运去的东西。比如大箱子里装的东西。", "primary_collocate": null, "pronunciation": "huò wù", "ipa": "xuɔ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "大船上装着很多货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车把货物运到了港口。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在往车上搬货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些货物都放在大箱子里。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车上的货物要三天才能到。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物太重，一个人搬不动。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船靠岸后，人们开始卸货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆大车里全是货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里堆满了货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物到了，请你在这里签字。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批货物", "label": "量词"}, {"form": "货物清单", "label": "复合"}, {"form": "貨物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "车船运送的东西，如箱子里装的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“大船上装着很多货物”，货物是船上装运的东西。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能装在船上。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是能装上船的东西。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“装着”的宾语应是可以装进船里的实物，时间装不上。"}], "explanations": {"货物": "正确：“大船上装着很多货物”，货物是船上装运的东西。", "天空": "语义：天空不能装在船上。", "河流": "语义：河流不是能装上船的东西。", "时间": "搭配：“装着”的宾语应是可以装进船里的实物，时间装不上。"}, "sentence_index": 0, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都用货物洗脸。", "explanation": "这里应该用〈肥皂〉。货物是车船运送的东西，洗脸用的东西要说肥皂。"}, {"text": "下雨了，我打开货物遮雨。", "explanation": "这里应该用〈伞〉。货物是车船运送的东西，遮雨用的东西要说伞。"}, {"text": "妈妈把新买的货物穿上了。", "explanation": "这里应该用〈衣服〉。货物不能穿在身上，穿的东西要说衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“卸货物”指把船上运来的东西卸下来，与“船靠岸后”相符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“卸”要搭配可以装卸的货物，空气不能卸。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是可以卸下来的东西。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以卸下来的东西。"}], "explanations": {"货物": "正确：“卸货物”指把船上运来的东西卸下来，与“船靠岸后”相符。", "空气": "搭配：“卸”要搭配可以装卸的货物，空气不能卸。", "声音": "语义：声音不是可以卸下来的东西。", "颜色": "语义：颜色不是可以卸下来的东西。"}, "sentence_index": 6, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都在读货物。", "explanation": "这里应该用〈报纸〉。货物不是可以阅读的东西，读的东西要说报纸。"}, {"text": "我们晚上吃了很多货物。", "explanation": "这里应该用〈食物〉。货物不能用来吃，吃的东西要说食物。"}, {"text": "孩子们在玩货物。", "explanation": "这里应该用〈玩具〉。货物是车船运送的东西，孩子玩的东西要说玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车上装了一辆货物。", "corrected_sentence": "卡车上装了一车货物。", "error_description": "错误：“一辆货物”，量词“辆”只用于车辆，不能用来数货物；正确：“一车货物”。装满货物的车可以用“车”作量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们货物搬上了卡车。", "corrected_sentence": "工人们把货物搬上了卡车。", "error_description": "错误：漏掉了介词“把”。“搬”字句中，处置对象“货物”前要加“把”，正确形式是“把货物搬上了卡车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
