INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供运输、买卖的物品。", "primary_collocate": null, "pronunciation": "huò wù", "ipa": "xuɔ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "这批货物明天要卖到国外。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的货物又多又便宜。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在检查新到的货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些货物卖得很快，已经不多了。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做生意，每天都要买卖货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把货物的价格写在纸上。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门卖进口货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物的质量好，客人才会再来。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用车运货物到城里去卖。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物卖完了，商店今天关门。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批货物", "label": "量词"}, {"form": "货物清单", "label": "复合"}, {"form": "貨物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来运输、买卖的物品，商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“这批货物”指供买卖的物品，可以卖到国外。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是人，不能当作商品卖到国外。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“这批”用于可以成批计量的物品，天气不能这样计量或买卖。"}, {"text": "岁月", "is_correct": false, "explanation": "语义：岁月是时间，不是可以买卖的东西。"}], "explanations": {"货物": "正确：“这批货物”指供买卖的物品，可以卖到国外。", "乘客": "语义：乘客是人，不能当作商品卖到国外。", "天气": "搭配：“这批”用于可以成批计量的物品，天气不能这样计量或买卖。", "岁月": "语义：岁月是时间，不是可以买卖的东西。"}, "sentence_index": 0, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上用货物刷牙。", "explanation": "这里应该用〈牙刷〉。货物是供运输、买卖的物品，刷牙用的东西要说牙刷。"}, {"text": "天黑了，我打开货物照亮房间。", "explanation": "这里应该用〈灯〉。货物是供运输、买卖的物品，照亮房间的东西要说灯。"}, {"text": "我每天用货物写日记。", "explanation": "这里应该用〈钢笔〉。货物是供运输、买卖的东西，写字的工具要说钢笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“进口货物”指从国外买来再卖的物品，与“专门卖”相符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是人，不能进口，也不能当商品卖。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“进口”搭配可以买卖的物品，时间不能进口。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是商品，不能进口买卖。"}], "explanations": {"货物": "正确：“进口货物”指从国外买来再卖的物品，与“专门卖”相符。", "病人": "语义：病人是人，不能进口，也不能当商品卖。", "时间": "搭配：“进口”搭配可以买卖的物品，时间不能进口。", "名字": "语义：名字不是商品，不能进口买卖。"}, "sentence_index": 6, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们晚上吃了很多货物。", "explanation": "这里应该用〈食物〉。货物指供运输、买卖的东西，吃的东西要说食物。"}, {"text": "孩子们每天都在玩货物。", "explanation": "这里应该用〈玩具〉。货物是供买卖的物品，孩子玩的东西要说玩具。"}, {"text": "我每天都在读货物。", "explanation": "这里应该用〈书〉。货物不是可以阅读的东西，读的东西要说书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天公司收到了一个货物。", "corrected_sentence": "今天公司收到了一批货物。", "error_description": "错误：“一个货物”，量词用错；正确：“一批货物”。货物常用量词“批”或“件”，一般不说“一个货物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把货物的卖完了。", "corrected_sentence": "我把货物卖完了。", "error_description": "错误：“货物的卖完了”，“的”不能加在处置对象“货物”后面，“把货物”后应直接接动词；正确：“把货物卖完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
