INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93317, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "隐藏是把东西放在别人看不到的地方。", "primary_collocate": null, "pronunciation": "yǐn cáng", "ipa": "in˨˩˦ tsʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他把钥匙隐藏在花盆下面。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把骨头隐藏在院子的角落里。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把礼物隐藏起来，给妈妈一个惊喜。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把日记隐藏在书架的最后面。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把糖隐藏在枕头下面。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子里隐藏着一些旧照片。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把零花钱隐藏在一本旧书里。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想隐藏手机，不让妈妈看到。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把答案隐藏在盒子里，让我们找。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的东西隐藏得太好了，我找不到。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐藏了", "label": "体标：了"}, {"form": "隐藏着", "label": "体标：着"}, {"form": "隐藏过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "把东西放在别人看不到的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4240d01-219b-4bd2-9ad0-703dd789f62b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐藏", "is_correct": true, "explanation": "正确。“隐藏”指把东西放在别人看不到的地方，与“在花盆下面”相符。"}, {"text": "展示", "is_correct": false, "explanation": "语义：“展示”是让人看见，与“在花盆下面”的隐蔽位置相反。"}, {"text": "排列", "is_correct": false, "explanation": "搭配：“排列”要求多个事物按顺序摆放，不能用于一把钥匙。"}, {"text": "展览", "is_correct": false, "explanation": "语义：“展览”是公开陈列，与“花盆下面”的隐蔽位置相矛盾。"}], "explanations": {"隐藏": "正确。“隐藏”指把东西放在别人看不到的地方，与“在花盆下面”相符。", "展示": "语义：“展示”是让人看见，与“在花盆下面”的隐蔽位置相反。", "排列": "搭配：“排列”要求多个事物按顺序摆放，不能用于一把钥匙。", "展览": "语义：“展览”是公开陈列，与“花盆下面”的隐蔽位置相矛盾。"}, "sentence_index": 0, "correct_answer": "隐藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把新做的蛋糕隐藏在橱窗里。", "explanation": "这里应该用〈展示〉。“隐藏”是放在别人看不到的地方，橱窗里的东西要让人看见，应说“展示”。"}, {"text": "学校把成绩单隐藏在公告栏里。", "explanation": "这里应该用〈张贴〉。“隐藏”指放在看不到的地方，公告栏是给人看的，成绩单要说“张贴”。"}, {"text": "商店把新品隐藏在最显眼的位置。", "explanation": "这里应该用〈摆放〉。“隐藏”与“最显眼”矛盾，把商品放在显眼的地方要说“摆放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐藏", "is_correct": true, "explanation": "正确。“隐藏”指把东西放在别人看不到的地方，与“在一本旧书里”相符。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”是放在阳光下使干燥，与把零花钱藏在书里的意思不合。"}, {"text": "复制", "is_correct": false, "explanation": "搭配：“复制”的对象不能是零花钱，且不能用“在”引出地点，句子不通。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”是使结冰，与零花钱放在书里的情况不合，句子不通。"}], "explanations": {"隐藏": "正确。“隐藏”指把东西放在别人看不到的地方，与“在一本旧书里”相符。", "晒": "语义：“晒”是放在阳光下使干燥，与把零花钱藏在书里的意思不合。", "复制": "搭配：“复制”的对象不能是零花钱，且不能用“在”引出地点，句子不通。", "冻": "语义：“冻”是使结冰，与零花钱放在书里的情况不合，句子不通。"}, "sentence_index": 6, "correct_answer": "隐藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆把文物隐藏在玻璃柜里。", "explanation": "这里应该用〈陈列〉。“隐藏”指放在别人看不到的地方，放在玻璃柜里供人参观要说“陈列”。"}, {"text": "国旗在广场上空缓缓隐藏。", "explanation": "这里应该用〈升起〉。“隐藏”指放在别人看不到的地方，国旗要升起让人看见，两者意思相反。"}, {"text": "老板把新品隐藏在柜台最前面。", "explanation": "这里应该用〈放〉。“隐藏”指放在别人看不到的地方，放在柜台最前面要让顾客看见，应说“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把照片隐藏抽屉的最里面。", "corrected_sentence": "他把照片隐藏在抽屉的最里面。", "error_description": "“隐藏”后面引出地点时要加介词“在”，应说“隐藏在抽屉的最里面”。“放”“摆”可以省略“在”，但“隐藏”不行。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个盒子他隐藏很好，没有人找到。", "corrected_sentence": "这个盒子他隐藏得很好，没有人找到。", "error_description": "“隐藏”后面表示程度要用“得”连接，应说“隐藏得很好”。去掉“得”后，“隐藏很好”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
