INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船的总称。", "primary_collocate": null, "pronunciation": "chuán zhī", "ipa": "ʈʂʰwan˧˥ ʈʂɨ˥", "syllable_count": 2, "sentences": [{"text": "这座城市的港口每天有很多船只进出。", "target_word": "船只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边看过往的船只。", "target_word": "船只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船只的数量一年比一年多。", "target_word": "船只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风让船只不得不停下来。", "target_word": "船只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在修理破旧的船只。", "target_word": "船只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个码头可以停大小船只。", "target_word": "船只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海警检查了所有出海的船只。", "target_word": "船只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各种船只在海面上慢慢前进。", "target_word": "船只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运河里的船只都要排队过闸。", "target_word": "船只", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上标出了附近的船只。", "target_word": "船只", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "船隻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "各类船的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5820b4e1-82a5-40c0-ae4a-682d87027408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "船只", "is_correct": true, "explanation": "正确。船只是各类船的统称，可以进出港口。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵在天空中，不会进出港口。"}, {"text": "石碑", "is_correct": false, "explanation": "体貌：石碑是固定的立体石刻，不能进出港口。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木生长在陆地上，不会进出港口。"}], "explanations": {"船只": "正确。船只是各类船的统称，可以进出港口。", "云朵": "语义：云朵在天空中，不会进出港口。", "石碑": "体貌：石碑是固定的立体石刻，不能进出港口。", "树木": "语义：树木生长在陆地上，不会进出港口。"}, "sentence_index": 0, "correct_answer": "船只"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人划着船只过河。", "explanation": "搭配：“划”要搭配单独的“船”，说“划船”；船只是统称，不能作“划”的对象。"}, {"text": "他买了一个船只。", "explanation": "船只是统称，不能用量词“个”计数，应说“他买了一艘船”。"}, {"text": "我家的船只叫‘海鸥号’。", "explanation": "船只是各类船的统称，不能指一条有名字的船；应说“我家的船叫‘海鸥号’”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "船只", "is_correct": true, "explanation": "正确。船只指出海的各类船，可以被检查。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵生长在陆地上，不会出海。"}, {"text": "大山", "is_correct": false, "explanation": "体貌：大山体积巨大且固定在地上，不能出海。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：房屋固定在陆地上，不会出海，与“出海的”矛盾。"}], "explanations": {"船只": "正确。船只指出海的各类船，可以被检查。", "花朵": "语义：花朵生长在陆地上，不会出海。", "大山": "体貌：大山体积巨大且固定在地上，不能出海。", "房屋": "语义：房屋固定在陆地上，不会出海，与“出海的”矛盾。"}, "sentence_index": 6, "correct_answer": "船只"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐船只去上班。", "explanation": "搭配：“坐”后接单独的船，不能接统称“船只”，应说“坐船去上班”。"}, {"text": "爸爸周末去公园划船只。", "explanation": "搭配：固定说法是“划船”，统称“船只”不能用在这里。"}, {"text": "他骑着船只去上班。", "explanation": "用法：船只被当成了骑乘的对象，好像自行车、马一样；船要坐或划，这里不能用“骑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港口里有很多只船只。", "corrected_sentence": "港口里有很多船只。", "error_description": "错误：船只前加了个体量词“只”。船只是各类船的统称，不能与个体量词连用；应去掉“只”，说“港口里有很多船只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海面上的船只们都慢慢前进了。", "corrected_sentence": "海面上的船只都慢慢前进了。", "error_description": "错误：在“船只”后加了复数词尾“们”。船只已表示多条船，不能再加“们”；应说“海面上的船只都慢慢前进了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93321, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少", "is_correct": true, "explanation": "“多”的反义词是“少”，指数量小，与“非常多”相对。"}, {"text": "大", "is_correct": false, "explanation": "“大”说体积或程度，与数量的多少没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”说高度，不指数量，与“非常多”不构成反义。"}, {"text": "远", "is_correct": false, "explanation": "“远”说距离，与数量无关，不是“非常多”的反义词。"}], "correct_answer": "少", "explanations": {"少": "“多”的反义词是“少”，指数量小，与“非常多”相对。", "大": "“大”说体积或程度，与数量的多少没有反义关系。", "高": "“高”说高度，不指数量，与“非常多”不构成反义。", "远": "“远”说距离，与数量无关，不是“非常多”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93321, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少", "is_correct": true, "explanation": "“多”的反义词是“少”，指数量小，与“非常多”相对。"}, {"text": "快", "is_correct": false, "explanation": "“快”说速度，与数量无关，不是“非常多”的反义词。"}, {"text": "矮", "is_correct": false, "explanation": "“矮”说高度，不指数量，与“非常多”不构成反义。"}, {"text": "浅", "is_correct": false, "explanation": "“浅”说深度，与数量无关，不是“非常多”的反义词。"}], "correct_answer": "少", "explanations": {"少": "“多”的反义词是“少”，指数量小，与“非常多”相对。", "快": "“快”说速度，与数量无关，不是“非常多”的反义词。", "矮": "“矮”说高度，不指数量，与“非常多”不构成反义。", "浅": "“浅”说深度，与数量无关，不是“非常多”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93321, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常多是特别特别多，多得数不过来。", "primary_collocate": null, "pronunciation": "fēi cháng duō", "ipa": "feɪ˥ ʈʂʰɑŋ˧˥ tuɔ˥", "syllable_count": 3, "sentences": [{"text": "节日的时候，公园里的人非常多。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的车非常多。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天海边的游客非常多。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书非常多，我数不过来。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的作业非常多。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上天上的星星非常多。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友非常多，每天都有人找他。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的饭馆非常多。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，我要做的题非常多。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里春天的花非常多，真漂亮。", "target_word": "非常多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量特别大，多得数不过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非常多", "is_correct": true, "explanation": "正确。“节日的时候”说明人很多，此处需要表示数量极大的“非常多”。"}, {"text": "很少", "is_correct": false, "explanation": "语义：与“节日的时候”的语境相反，节日时公园里人多，不会说人很少。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容地方或场面，不用来形容人的数量。"}, {"text": "稀疏", "is_correct": false, "explanation": "语义：“稀疏”表示人或东西少而分散，与“节日的时候”人多的语境相反。"}], "explanations": {"非常多": "正确。“节日的时候”说明人很多，此处需要表示数量极大的“非常多”。", "很少": "语义：与“节日的时候”的语境相反，节日时公园里人多，不会说人很少。", "冷清": "搭配：“冷清”形容地方或场面，不用来形容人的数量。", "稀疏": "语义：“稀疏”表示人或东西少而分散，与“节日的时候”人多的语境相反。"}, "sentence_index": 0, "correct_answer": "非常多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子非常多，站在人群里很显眼。", "explanation": "这里应该用〈非常高〉。“非常多”只说数量，个子的高矮要用“高”。"}, {"text": "这件衣服的质量非常多，穿起来很舒服。", "explanation": "这里应该用〈非常好〉。“非常多”只说数量，质量的好坏要用“好”。"}, {"text": "这朵花非常多，我很喜欢。", "explanation": "这里应该用〈非常漂亮〉。“非常多”说的是数量，句中只是一朵花，评价花的美丑要用“漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非常多", "is_correct": true, "explanation": "正确。后句“每天都有人找他”说明朋友很多，此处需要“非常多”。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：与后句“每天都有人找他”矛盾，有人常来找他的人不会说朋友寂寞。"}, {"text": "单调", "is_correct": false, "explanation": "搭配：“单调”形容内容或生活，不用来形容朋友的数量。"}, {"text": "单薄", "is_correct": false, "explanation": "搭配：“单薄”形容身材或衣物，不能修饰“朋友”的多少。"}], "explanations": {"非常多": "正确。后句“每天都有人找他”说明朋友很多，此处需要“非常多”。", "寂寞": "语义：与后句“每天都有人找他”矛盾，有人常来找他的人不会说朋友寂寞。", "单调": "搭配：“单调”形容内容或生活，不用来形容朋友的数量。", "单薄": "搭配：“单薄”形容身材或衣物，不能修饰“朋友”的多少。"}, "sentence_index": 6, "correct_answer": "非常多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气非常多，我们去公园玩吧。", "explanation": "这里应该用〈非常热〉。“非常多”只说数量，天气的冷热要用“热”或“冷”。"}, {"text": "我家离学校非常多，我每天都骑车去。", "explanation": "这里应该用〈非常远〉。“非常多”只说数量，距离要用“远”。"}, {"text": "我家门口这棵树非常多，我很喜欢它。", "explanation": "这里应该用〈非常高〉。“非常多”说的是数量，句中只是一棵树，描述树的高矮要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末的商场里，买东西的人很非常多。", "corrected_sentence": "周末的商场里，买东西的人非常多。", "error_description": "错误：“非常”和“很”都表示程度，不能叠用。“非常多”前面不能再加“很”，应去掉“很”，说“买东西的人非常多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区里养狗的人非常多得很。", "corrected_sentence": "这个小区里养狗的人非常多。", "error_description": "错误：“非常”和“得很”都表示程度，不能同时使用。应去掉“得很”，说“这个小区里养狗的人非常多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
