INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93323, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "处分是学校或公司对做错事的人的惩罚。", "primary_collocate": null, "pronunciation": "chǔ fèn", "ipa": "ʈʂʰu˨˩˦ fən˥˩", "syllable_count": 2, "sentences": [{"text": "他因为打架受到了处分。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校给了他一个处分。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次处分让他记住了教训。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的处分很重，大家都很吃惊。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作弊的学生都得到了处分。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这个处分不会写进档案。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司对迟到的人有处分。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕受处分，所以不敢说真话。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个处分是校长决定的。", "target_word": "处分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一次小处分不会影响你的未来。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "记过处分", "label": "复合"}, {"form": "纪律处分", "label": "复合"}], "register": "正式", "sense_fingerprint": "学校或公司给做错事的人的惩罚（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荣誉", "is_correct": false, "explanation": "语义：“荣誉”是褒扬，与“因为打架”的过错相矛盾。"}, {"text": "勋章", "is_correct": false, "explanation": "搭配：“勋章”要说“获得”或“授予”，打架不能让人受到勋章。"}, {"text": "处分", "is_correct": true, "explanation": "正确。“受到处分”指因犯错而受到的惩罚，符合句意。"}, {"text": "尊严", "is_correct": false, "explanation": "搭配：“受到”后一般接“伤害”“表扬”“处分”等，不说“受到尊严”。"}], "explanations": {"荣誉": "语义：“荣誉”是褒扬，与“因为打架”的过错相矛盾。", "勋章": "搭配：“勋章”要说“获得”或“授予”，打架不能让人受到勋章。", "处分": "正确。“受到处分”指因犯错而受到的惩罚，符合句意。", "尊严": "搭配：“受到”后一般接“伤害”“表扬”“处分”等，不说“受到尊严”。"}, "sentence_index": 0, "correct_answer": "处分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的作文拿到了一个高处分，老师很满意。", "explanation": "这里应该用〈分数〉。“处分”指对犯错者的惩罚，作文的得分要用分数。"}, {"text": "他把这个处分分给了大家。", "explanation": "这里应该用〈礼物〉。“处分”指对犯错的人作出的惩罚，不能像礼物一样分给别人。"}, {"text": "他这次考试的处分很高，老师很满意。", "explanation": "这里应该用〈成绩〉。分数的高低要用成绩，处分指惩罚，不能用来表示高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电话", "is_correct": false, "explanation": "搭配：“电话”是物件，不能说“对迟到的人有电话”。"}, {"text": "处分", "is_correct": true, "explanation": "正确。“对……有处分”表示存在针对迟到者的惩罚，符合句意。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：“奖金”是奖励，与“迟到”的过错相矛盾。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体特征，不能用在“对……有”的结构中。"}], "explanations": {"电话": "搭配：“电话”是物件，不能说“对迟到的人有电话”。", "处分": "正确。“对……有处分”表示存在针对迟到者的惩罚，符合句意。", "奖金": "语义：“奖金”是奖励，与“迟到”的过错相矛盾。", "身高": "体貌：“身高”指人的身体特征，不能用在“对……有”的结构中。"}, "sentence_index": 6, "correct_answer": "处分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校为这次比赛的优胜者准备了一个处分。", "explanation": "这里应该用〈奖品〉。处分是惩罚，不能作为奖品发给获胜者。"}, {"text": "班主任用处分来鼓励我们的进步。", "explanation": "这里应该用〈奖励〉。“处分”是惩罚，不能用来鼓励。"}, {"text": "他把这份处分送给了我的朋友。", "explanation": "这里应该用〈纪念品〉。“处分”是惩罚，不能当作纪念品送给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她因为迟到受到了一只处分。", "corrected_sentence": "她因为迟到受到了一次处分。", "error_description": "“一只处分”误用量词“只”。“只”用于动物或成对物品之一，不能修饰“处分”，应改为“一次处分”（用“个”也可）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校对逃课的学生有很处分。", "corrected_sentence": "学校对逃课的学生有处分。", "error_description": "“很”不能修饰名词“处分”，应去掉“很”：“有处分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
