INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对犯错误或违反纪律的人作出处罚决定。", "primary_collocate": null, "pronunciation": "chǔ fèn", "ipa": "ʈʂʰu˨˩˦ fən˥˩", "syllable_count": 2, "sentences": [{"text": "学校决定处分那个打架的学生。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要处分迟到三次的员工。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说要处分作弊的同学。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长处分了偷东西的学生。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司处分过他一次，他以后很小心。", "target_word": "处分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定处分那个说谎的人。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校不想处分他，只想让他认错。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "再犯错，学校就会处分你。", "target_word": "处分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板把迟到的人都处分了。", "target_word": "处分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为什么处分他，大家都不知道。", "target_word": "处分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "处分了", "label": "体标"}, {"form": "处分过", "label": "体标"}], "register": "正式", "sense_fingerprint": "对犯错或违纪的人作出处罚决定（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是褒奖，与“打架”的过错相矛盾。"}, {"text": "拘留", "is_correct": false, "explanation": "搭配：“拘留”是公安机关的强制措施，学校不能决定拘留学生。"}, {"text": "处分", "is_correct": true, "explanation": "正确。“决定处分”指对犯错的学生作出处罚决定，符合句意。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是奖赏，与“打架”的过错相矛盾。"}], "explanations": {"表扬": "语义：“表扬”是褒奖，与“打架”的过错相矛盾。", "拘留": "搭配：“拘留”是公安机关的强制措施，学校不能决定拘留学生。", "处分": "正确。“决定处分”指对犯错的学生作出处罚决定，符合句意。", "奖励": "语义：“奖励”是奖赏，与“打架”的过错相矛盾。"}, "sentence_index": 0, "correct_answer": "处分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花开得很好，校长处分了它。", "explanation": "这里应该用〈欣赏〉。“处分”的惩罚义针对犯错的人，花不能作惩罚对象。"}, {"text": "老师处分了这道数学题。", "explanation": "这里应该用〈批改〉。“处分”只用于对犯错的人作出处罚，数学题要用批改。"}, {"text": "我们在操场上处分了一场雨。", "explanation": "这里应该用〈遇到〉。“处分”的惩罚义针对犯错的人，雨不能作惩罚对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雇佣", "is_correct": false, "explanation": "语义：“雇佣”指用人做事，与学校和学生的关系不合。"}, {"text": "处分", "is_correct": true, "explanation": "正确。“不想处分他，只想让他认错”符合句意。"}, {"text": "捐赠", "is_correct": false, "explanation": "配价：“捐赠”需要有捐赠的物品，“他”不能作受赠对象。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”与惩处无关，“不想拍摄他，只想让他认错”句意不通。"}], "explanations": {"雇佣": "语义：“雇佣”指用人做事，与学校和学生的关系不合。", "处分": "正确。“不想处分他，只想让他认错”符合句意。", "捐赠": "配价：“捐赠”需要有捐赠的物品，“他”不能作受赠对象。", "拍摄": "语义：“拍摄”与惩处无关，“不想拍摄他，只想让他认错”句意不通。"}, "sentence_index": 6, "correct_answer": "处分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校处分了那堂有趣的体育课。", "explanation": "这里应该用〈组织〉。“处分”的惩罚义针对犯错的人，体育课不能作惩罚对象。"}, {"text": "学校处分了那次比赛的加油声。", "explanation": "这里应该用〈听到〉。“处分”的惩罚义针对犯错的人，加油声不能作惩罚对象。"}, {"text": "学校处分了那次热心的募捐。", "explanation": "这里应该用〈表彰〉。“处分”针对犯错的人，热心的募捐活动要用表彰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师处分着那个顶撞老师的学生。", "corrected_sentence": "老师处分了那个顶撞老师的学生。", "error_description": "“处分”是一次性完成的处罚动作，不能用“着”表示持续。应把“着”改为“了”，说“处分了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长决定很处分那个逃课的学生。", "corrected_sentence": "校长决定处分那个逃课的学生。", "error_description": "“很”不能修饰动词“处分”，应去掉“很”：“决定处分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
