INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或笔指出具体位置，让大家看到那个地方。", "primary_collocate": null, "pronunciation": "diǎn chū", "ipa": "tjɛn˨˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "老师用手点出地图上的北京。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用笔点出了我们的学校。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在图上点出我家的位置。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游用手点出远处的那座山。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟用手指点出了桌上的小猫。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上点出了这个字。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在地图上点出我们现在的地方。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用笔点出书里的新词。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用笔点出了照片上的小河。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王点出了河边那座白房子。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点出了", "label": "完成体"}, {"form": "点出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用手或笔指出具体位置，让人看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点出", "is_correct": true, "explanation": "「点出」指用手或笔指明具体位置，让人看见，与句意相符。"}, {"text": "拿出", "is_correct": false, "explanation": "搭配：「拿出」的对象应是能被拿走的东西，「地图上的北京」是地点，不能说拿出。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：「打开」多用于门、盒子、书等，不能用来说打开地图上的北京。"}, {"text": "收起", "is_correct": false, "explanation": "语义：「收起」是收拢、归置的意思，与「让人看到某个地方」正好相反。"}], "explanations": {"点出": "「点出」指用手或笔指明具体位置，让人看见，与句意相符。", "拿出": "搭配：「拿出」的对象应是能被拿走的东西，「地图上的北京」是地点，不能说拿出。", "打开": "搭配：「打开」多用于门、盒子、书等，不能用来说打开地图上的北京。", "收起": "语义：「收起」是收拢、归置的意思，与「让人看到某个地方」正好相反。"}, "sentence_index": 0, "correct_answer": "点出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从口袋里点出了一张地图。", "explanation": "这里应该用〈拿出〉。点出表示用手或笔指明位置，让人看见，不能表示把东西从口袋里取出。"}, {"text": "这些小花点出了草地。", "explanation": "这里应该用〈点缀〉。「点出」表示用手或笔指明位置，让人看见，不能表示装饰、点缀。"}, {"text": "我在菜单上点出了一份汤。", "explanation": "这里应该用〈点〉。「点」可用于点菜，点出只表示指明位置，不能表示点餐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点出", "is_correct": true, "explanation": "「点出」指用手或笔指明具体位置，让人看见，与句意相符。"}, {"text": "掏出", "is_correct": false, "explanation": "搭配：「掏出」的对象应是能拿在手里的东西，不能说掏出地图上的地方。"}, {"text": "放下", "is_correct": false, "explanation": "语义：「放下」是搁置、放置的意思，与「让人看到某个地方」无关。"}, {"text": "挂起", "is_correct": false, "explanation": "搭配：「挂起」针对可以挂的东西，地点不能被挂起。"}], "explanations": {"点出": "「点出」指用手或笔指明具体位置，让人看见，与句意相符。", "掏出": "搭配：「掏出」的对象应是能拿在手里的东西，不能说掏出地图上的地方。", "放下": "语义：「放下」是搁置、放置的意思，与「让人看到某个地方」无关。", "挂起": "搭配：「挂起」针对可以挂的东西，地点不能被挂起。"}, "sentence_index": 6, "correct_answer": "点出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士点出了他的体温。", "explanation": "这里应该用〈测出〉。「点出」表示指明位置，不能用于测量并报出数值。"}, {"text": "他从管子里点出了一点牙膏。", "explanation": "这里应该用〈挤出〉。「点出」不能表示从管子里挤出东西。"}, {"text": "他点出了一声叹息。", "explanation": "这里应该用〈发出〉。「点出」表示指明位置，不能表示发出声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师用手点出着地图上的湖。", "corrected_sentence": "老师用手点出了地图上的湖。", "error_description": "错误：「点出着」；正确：「点出了」。「着」表示动作的持续状态，这里说的是已经完成的指点，应使用完成体「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在地图上没点出了这个小村庄。", "corrected_sentence": "他在地图上没点出这个小村庄。", "error_description": "错误：「没点出了」；正确：「没点出」。「没」本身就否定动作的完成，不能再和表示完成的「了」一起用，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
