INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "明确指出；把关键之处说明白。", "primary_collocate": null, "pronunciation": "diǎn chū", "ipa": "tjɛn˨˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他一句话就点出了问题的关键。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师点出了我作文里的错误。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章点出了大家的想法。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生点出了我睡不好的原因。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友点出了我的小毛病。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她点出了这个办法的好处。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里点出了学习的重要方法。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理点出了我们工作中的问题。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一句话点出了生活的道理。", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能点出这件事的原因吗？", "target_word": "点出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点出了", "label": "完成体"}, {"form": "点出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用话明确指出问题、原因等关键之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点出", "is_correct": true, "explanation": "「点出」指明确说出关键之处，与句意相符。"}, {"text": "摆放", "is_correct": false, "explanation": "搭配：「摆放」用于具体物品，不能用于「问题的关键」。"}, {"text": "摆脱", "is_correct": false, "explanation": "语义：「摆脱」是离开、甩掉的意思，「摆脱问题的关键」说不通，与「说明白」无关。"}, {"text": "收起", "is_correct": false, "explanation": "搭配：「收起」指收拢物品，不能用来搭配「问题的关键」。"}], "explanations": {"点出": "「点出」指明确说出关键之处，与句意相符。", "摆放": "搭配：「摆放」用于具体物品，不能用于「问题的关键」。", "摆脱": "语义：「摆脱」是离开、甩掉的意思，「摆脱问题的关键」说不通，与「说明白」无关。", "收起": "搭配：「收起」指收拢物品，不能用来搭配「问题的关键」。"}, "sentence_index": 0, "correct_answer": "点出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想点出一份炒饭。", "explanation": "这里应该用〈点〉。「点」可用于点菜，点出只表示说明关键之处，不能表示点餐。"}, {"text": "医生点出了我的血压。", "explanation": "这里应该用〈测出〉。「点出」是明确说明关键之处，不能用于测量并报出数值。"}, {"text": "他用尺子点出了桌子的长度。", "explanation": "这里应该用〈量出〉。「点出」是明确说明关键之处，不能表示用工具测量长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点出", "is_correct": true, "explanation": "「点出」指明确说出重要之处，与句意相符。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：「扔掉」是丢弃的意思，书不会把方法丢弃，与「讲明」的意思相反。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：「收拾」针对物品或房间，不能用于「方法」。"}, {"text": "擦掉", "is_correct": false, "explanation": "搭配：「擦掉」针对可见的痕迹，不能用于学习方法。"}], "explanations": {"点出": "「点出」指明确说出重要之处，与句意相符。", "扔掉": "语义：「扔掉」是丢弃的意思，书不会把方法丢弃，与「讲明」的意思相反。", "收拾": "搭配：「收拾」针对物品或房间，不能用于「方法」。", "擦掉": "搭配：「擦掉」针对可见的痕迹，不能用于学习方法。"}, "sentence_index": 6, "correct_answer": "点出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她点出了一声惊叫。", "explanation": "这里应该用〈发出〉。「点出」表示把关键之处说明白，不能表示发出声音。"}, {"text": "她从抽屉里点出了钥匙。", "explanation": "这里应该用〈取出〉。「点出」不表示把东西从抽屉里拿出来。"}, {"text": "他点出了一支蜡烛。", "explanation": "这里应该用〈点燃〉。「点出」不表示让东西燃烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一句话就点出着这个计划的风险。", "corrected_sentence": "她一句话就点出了这个计划的风险。", "error_description": "错误：「点出着」；正确：「点出了」。「着」表示动作的持续状态，这里说的是已经完成的说明，应使用完成体「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章没点出了这件事的漏洞。", "corrected_sentence": "这篇文章没点出这件事的漏洞。", "error_description": "错误：「没点出了」；正确：「没点出」。「没」本身就否定动作的完成，不能再和表示完成的「了」一起用，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
