INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93327, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "制品是人用材料做出来的东西。", "primary_collocate": null, "pronunciation": "zhì pǐn", "ipa": "tʂɻ̩⁵¹ pʰin²¹⁴", "syllable_count": 2, "sentences": [{"text": "这家工厂专门生产塑料制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的乳制品都放在冷柜里。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些木制品是工人用手做的。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖各种纸制品，比如本子和纸袋。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个皮制品很结实，用了五年也没坏。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料制品用完以后不要乱扔。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司出口的主要是竹制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶、酸奶和奶酪都是乳制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玻璃制品很容易碎，请小心拿。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把木头做成了各种木制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "塑料制品", "label": "复合"}, {"form": "木制品", "label": "复合"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "制品：人用材料做成的东西，常见于塑料制品、木制品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6f10e89-3216-45ca-a1f0-6c5d9749bac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：人用材料做出来的东西，是本题的正确答案。"}, {"text": "纸品", "is_correct": false, "explanation": "zhǐ pǐn（第三声）与 zhì pǐn（第四声）声调不同，“纸品”指纸类产品。"}, {"text": "织品", "is_correct": false, "explanation": "zhī pǐn（第一声）与 zhì pǐn（第四声）声调不同，“织品”指纺织品。"}, {"text": "试品", "is_correct": false, "explanation": "shì 与 zhì 声母不同，“试品”指用于检验的样品。"}, {"text": "饰品", "is_correct": false, "explanation": "shì 与 zhì 声母不同，“饰品”指装饰用的物品。"}], "explanations": {"制品": "制品：人用材料做出来的东西，是本题的正确答案。", "纸品": "zhǐ pǐn（第三声）与 zhì pǐn（第四声）声调不同，“纸品”指纸类产品。", "织品": "zhī pǐn（第一声）与 zhì pǐn（第四声）声调不同，“织品”指纺织品。", "试品": "shì 与 zhì 声母不同，“试品”指用于检验的样品。", "饰品": "shì 与 zhì 声母不同，“饰品”指装饰用的物品。"}, "sentence_index": null, "correct_answer": "制品"}, "level_3": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：用材料加工做成的东西，与“塑料”“生产”搭配自然。"}, {"text": "原理", "is_correct": false, "explanation": "语义：“原理”是道理，不是可以生产出来的东西，与句子语境不符。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“生产”说的是造出物品，不能与“气味”搭配。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是可以生产出来的东西，与句子语境不符。"}], "explanations": {"制品": "制品：用材料加工做成的东西，与“塑料”“生产”搭配自然。", "原理": "语义：“原理”是道理，不是可以生产出来的东西，与句子语境不符。", "气味": "搭配：“生产”说的是造出物品，不能与“气味”搭配。", "名字": "语义：“名字”不是可以生产出来的东西，与句子语境不符。"}, "sentence_index": 0, "correct_answer": "制品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木头是做家具的制品。", "explanation": "这里应该用〈材料〉。木头是还没加工的原料，“制品”指加工后做成的东西。"}, {"text": "这条河里游着很多制品。", "explanation": "这里应该用〈鱼〉。“制品”是人用材料做出来的东西，河里游的鱼是活的动物。"}, {"text": "这位画家的制品很有名。", "explanation": "这里应该用〈作品〉。绘画、文章等艺术成果称作品，“制品”指工业或手工制造的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：加工做成的产品，竹子经加工后出口，与“出口”搭配。"}, {"text": "林", "is_correct": false, "explanation": "搭配：“出口”的对象是货物，“竹林”是一片地，不能出口。"}, {"text": "影", "is_correct": false, "explanation": "语义：“竹影”指竹子的影子，不是可以出口的货物。"}, {"text": "海", "is_correct": false, "explanation": "搭配：“竹海”是大片竹林的景观，不能作为出口的东西。"}], "explanations": {"制品": "制品：加工做成的产品，竹子经加工后出口，与“出口”搭配。", "林": "搭配：“出口”的对象是货物，“竹林”是一片地，不能出口。", "影": "语义：“竹影”指竹子的影子，不是可以出口的货物。", "海": "搭配：“竹海”是大片竹林的景观，不能作为出口的东西。"}, "sentence_index": 6, "correct_answer": "制品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小麦是做面包的主要制品。", "explanation": "这里应该用〈原料〉。小麦是未经加工的农作物，属于原料；“制品”指加工后做成的东西。"}, {"text": "这片森林里有很多制品。", "explanation": "这里应该用〈树木〉。“制品”指人用材料做出来的东西，森林里的树木是天然形成的，不能说制品。"}, {"text": "他每月的制品是五千元。", "explanation": "这里应该用〈工资〉。“制品”指人用材料做出来的东西，不能用来表示一个人每月的收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂生产了一匹塑料制品。", "corrected_sentence": "这家工厂生产了一批塑料制品。", "error_description": "量词错误：“匹”用于马、布等，不能修饰“制品”；成批生产的制品应该用量词“批”，说“一批塑料制品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些很制品大多数都很结实。", "corrected_sentence": "这些制品大多数都很结实。", "error_description": "“很”不能修饰名词，“制品”前面不能加“很”。应说“这些制品大多数都很结实”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
