INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用某种原料加工制成的产品。", "primary_collocate": null, "pronunciation": "zhì pǐn", "ipa": "tʂɻ̩⁵¹ pʰin²¹⁴", "syllable_count": 2, "sentences": [{"text": "豆腐和豆浆都是大豆制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的肉制品很新鲜。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属制品放在潮湿的地方会生锈。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橡胶制品用久了会变硬。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂用棉花加工各种棉制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢吃面制品，比如面条和饺子。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些银制品是用银子加工做成的。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买肉制品的时候要看生产日期。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批陶瓷制品要运到国外去。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在食品厂检查乳制品的质量。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "豆制品", "label": "复合"}, {"form": "肉制品", "label": "复合"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "制品：以某种原料加工而成的产品，如豆制品、肉制品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6f10e89-3216-45ca-a1f0-6c5d9749bac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：用某种原料加工制成的产品，是本题的正确答案。"}, {"text": "纸品", "is_correct": false, "explanation": "zhǐ pǐn（第三声）与 zhì pǐn（第四声）声调不同，“纸品”指纸类产品。"}, {"text": "织品", "is_correct": false, "explanation": "zhī pǐn（第一声）与 zhì pǐn（第四声）声调不同，“织品”指纺织品。"}, {"text": "试品", "is_correct": false, "explanation": "shì 与 zhì 声母不同，“试品”指用于检验的样品。"}, {"text": "饰品", "is_correct": false, "explanation": "shì 与 zhì 声母不同，“饰品”指装饰用的物品。"}], "explanations": {"制品": "制品：用某种原料加工制成的产品，是本题的正确答案。", "纸品": "zhǐ pǐn（第三声）与 zhì pǐn（第四声）声调不同，“纸品”指纸类产品。", "织品": "zhī pǐn（第一声）与 zhì pǐn（第四声）声调不同，“织品”指纺织品。", "试品": "shì 与 zhì 声母不同，“试品”指用于检验的样品。", "饰品": "shì 与 zhì 声母不同，“饰品”指装饰用的物品。"}, "sentence_index": null, "correct_answer": "制品"}, "level_3": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：用原料加工而成的产品，豆腐和豆浆正是由大豆加工成的。"}, {"text": "植株", "is_correct": false, "explanation": "语义：“植株”是植物本身，豆腐和豆浆不是植株。"}, {"text": "荚", "is_correct": false, "explanation": "语义：“大豆荚”是豆子的外壳，豆腐和豆浆不是豆荚。"}, {"text": "田", "is_correct": false, "explanation": "语义：“大豆田”是种大豆的地，豆腐和豆浆不是田地。"}], "explanations": {"制品": "制品：用原料加工而成的产品，豆腐和豆浆正是由大豆加工成的。", "植株": "语义：“植株”是植物本身，豆腐和豆浆不是植株。", "荚": "语义：“大豆荚”是豆子的外壳，豆腐和豆浆不是豆荚。", "田": "语义：“大豆田”是种大豆的地，豆腐和豆浆不是田地。"}, "sentence_index": 0, "correct_answer": "制品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大豆是做豆腐的制品。", "explanation": "这里应该用〈原料〉。大豆是加工前的东西，“制品”指加工后做成的成品。"}, {"text": "天上飞着很多制品。", "explanation": "这里应该用〈鸟〉。“制品”是加工做成的产品，天上飞的鸟是动物。"}, {"text": "这本小说是他的代表制品。", "explanation": "这里应该用〈作品〉。小说等文艺创作称作品，“制品”指用材料加工的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：经加工做成的东西，与“加工做成”搭配。"}, {"text": "河", "is_correct": false, "explanation": "语义：“银河”是天上的星河，不能用银子加工做成。"}, {"text": "行", "is_correct": false, "explanation": "语义：“银行”是机构，不能用银子加工做成。"}, {"text": "发", "is_correct": false, "explanation": "语义：“银发”是白头发，不是用银子加工做成的。"}], "explanations": {"制品": "制品：经加工做成的东西，与“加工做成”搭配。", "河": "语义：“银河”是天上的星河，不能用银子加工做成。", "行": "语义：“银行”是机构，不能用银子加工做成。", "发": "语义：“银发”是白头发，不是用银子加工做成的。"}, "sentence_index": 6, "correct_answer": "制品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在田里种满了制品。", "explanation": "这里应该用〈庄稼〉。“制品”是加工做成的东西，不能种在田里，应说“庄稼”。"}, {"text": "这家工厂用制品加工汽油。", "explanation": "这里应该用〈原油〉。原油是加工前的原料，“制品”是加工后的产品，不能再拿来加工汽油。"}, {"text": "这条路的制品长十公里。", "explanation": "这里应该用〈长度〉。“制品”指用某种原料加工制成的产品，不能用来说明道路的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家厂生产了很多大豆制品们。", "corrected_sentence": "这家厂生产了很多大豆制品。", "error_description": "“们”一般只用在指人的名词后面，“制品”是物品，不能加“们”，应说“很多大豆制品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这匹银制品已经包装好了。", "corrected_sentence": "这批银制品已经包装好了。", "error_description": "量词错误：“匹”用于马、布等，不能修饰“银制品”；成批的产品应该用量词“批”，说“这批银制品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
