INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93329, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一般人是很多普通的人，不是特别厉害的人。", "primary_collocate": null, "pronunciation": "yì bān rén", "ipa": "i˥˩ pan˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "我只是一般人，没有什么特别的本事。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人每天要工作八个小时。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，一般人很难回答。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人的生活很简单，也很安静。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是明星，只是一般人。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对一般人来说，学汉字不太容易。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西，一般人都买得起。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人坐地铁上班，不开车。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法和一般人不一样。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人过生日，都会和家人吃蛋糕。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一般人：很多普通、不特别厉害的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一般人", "is_correct": true, "explanation": "“一般人”指普通、不特别厉害的人，与“没有什么特别的本事”一致。"}, {"text": "天才", "is_correct": false, "explanation": "语义：天才本身就有过人的本事，与“没有什么特别的本事”自相矛盾。"}, {"text": "英雄", "is_correct": false, "explanation": "语义：英雄以过人的事迹著称，与“没有什么特别的本事”自相矛盾。"}, {"text": "贤人", "is_correct": false, "explanation": "语域：“贤人”是文言词，在这句口语里很别扭，且带有道德赞美的色彩。"}], "explanations": {"一般人": "“一般人”指普通、不特别厉害的人，与“没有什么特别的本事”一致。", "天才": "语义：天才本身就有过人的本事，与“没有什么特别的本事”自相矛盾。", "英雄": "语义：英雄以过人的事迹著称，与“没有什么特别的本事”自相矛盾。", "贤人": "语域：“贤人”是文言词，在这句口语里很别扭，且带有道德赞美的色彩。"}, "sentence_index": 0, "correct_answer": "一般人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位一般人是我的老师。", "explanation": "这里不该用“这位”。〈一般人〉泛指普通大众，不指某个具体的人，不能用“这位”来指称。"}, {"text": "那位一般人刚搬进隔壁的房子。", "explanation": "这里不该用“那位”。〈一般人〉是泛指的说法，指称具体的某个人时不能用它。"}, {"text": "我的一般人在操场上跑步。", "explanation": "这里不该用“我的”修饰。〈一般人〉指一类人，不能作为“我的”所属的某个具体的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一般人", "is_correct": true, "explanation": "“一般人”指普通人，句中“买得起”的是普通大众，与“这家店的东西”的价位相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会买东西，“小狗都买得起”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有购买能力，不能作“买得起”的主语。"}, {"text": "先贤", "is_correct": false, "explanation": "语域：“先贤”是文言词，指已故的圣贤，与这句口语化的陈述不协调。"}], "explanations": {"一般人": "“一般人”指普通人，句中“买得起”的是普通大众，与“这家店的东西”的价位相符。", "小狗": "语义：小狗不会买东西，“小狗都买得起”说不通。", "石头": "语义：石头没有购买能力，不能作“买得起”的主语。", "先贤": "语域：“先贤”是文言词，指已故的圣贤，与这句口语化的陈述不协调。"}, "sentence_index": 6, "correct_answer": "一般人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车站里坐着一条一般人。", "explanation": "这里应该用〈个〉。〈条〉用于长形的东西或某些动物，不能用来计量“一般人”。"}, {"text": "墙角蹲着一头一般人。", "explanation": "这里应该用〈个〉。〈头〉用于牲畜，指人不能用〈头〉计量。"}, {"text": "屋里有一台一般人。", "explanation": "这里应该用〈个〉。〈台〉用于机器、设备，指人不能用〈台〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只是一只一般人，没有什么特别的地方。", "corrected_sentence": "他只是一个一般人，没有什么特别的地方。", "error_description": "错误形式：“一只一般人”；正确形式：“一个一般人”。“一只”用于动物，指人应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一般人了都不太关心这件事。", "corrected_sentence": "一般人都不太关心这件事。", "error_description": "错误：「一般人了」；正确：「一般人」。「了」不能接在主语名词「一般人」后面，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
