INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "普通人；大多数人，不属于特殊或杰出的一类。", "primary_collocate": null, "pronunciation": "yì bān rén", "ipa": "i˥˩ pan˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "一般人都不喜欢早上六点起床。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种工作一般人做不了。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人听到这个消息会很吃惊。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来和一般人没有什么不同。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人一个月只看一两本书。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个价钱，一般人买不起。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人遇到困难，都会先找朋友帮忙。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记忆力比一般人好很多。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般人不会在晚上十二点还给别人打电话。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅很贵，一般人不常来。", "target_word": "一般人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一般人：与特殊、杰出的人相对，指大多数普通人的常态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一般人", "is_correct": true, "explanation": "“一般人”指普通人、大多数人，正是“都不喜欢早上六点起床”的群体。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟没有喜好，不能说“闹钟都不喜欢早上六点起床”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有喜好，也不会起床。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口是统计意义上的总数，不是能有喜好的个体，不能作“不喜欢”的主语。"}], "explanations": {"一般人": "“一般人”指普通人、大多数人，正是“都不喜欢早上六点起床”的群体。", "闹钟": "语义：闹钟没有喜好，不能说“闹钟都不喜欢早上六点起床”。", "桌子": "语义：桌子没有喜好，也不会起床。", "人口": "语义：人口是统计意义上的总数，不是能有喜好的个体，不能作“不喜欢”的主语。"}, "sentence_index": 0, "correct_answer": "一般人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路上走过来一只一般人。", "explanation": "这里应该用〈个〉。〈只〉用于动物，指人不能用〈只〉计量，“一般人”前要用〈个〉。"}, {"text": "院子里站着一棵一般人。", "explanation": "这里应该用〈个〉。〈棵〉用于树木，“一般人”指人，不能用〈棵〉计量。"}, {"text": "门口停着一辆一般人。", "explanation": "这里应该用〈个〉。〈辆〉用于车辆，“一般人”指人，不能用〈辆〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一般人", "is_correct": true, "explanation": "“一般人”指普通人，句中“遇到困难，先找朋友帮忙”是普通人的常见做法。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会遇到困难，也不会主动去找朋友帮忙。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有求助的行为，与“先找朋友帮忙”说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会遇到困难，也不会找朋友帮忙。"}], "explanations": {"一般人": "“一般人”指普通人，句中“遇到困难，先找朋友帮忙”是普通人的常见做法。", "石头": "语义：石头不会遇到困难，也不会主动去找朋友帮忙。", "电脑": "语义：电脑没有求助的行为，与“先找朋友帮忙”说不通。", "汽车": "语义：汽车不会遇到困难，也不会找朋友帮忙。"}, "sentence_index": 6, "correct_answer": "一般人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位一般人是我们公司的经理。", "explanation": "这里不该用“这位”。〈一般人〉泛指普通大众，不指某个具体的人，不能用“这位”来指称一个人。"}, {"text": "那位一般人刚刚打过电话。", "explanation": "这里不该用“那位”。〈一般人〉是泛指的说法，指称具体某人时不能用它。"}, {"text": "我的一般人正在办公室等你。", "explanation": "这里不该用“我的”修饰。〈一般人〉指一类人，不能作为“我的”所属的某个具体的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对一般人来说了，这件事很难理解。", "corrected_sentence": "对一般人来说，这件事很难理解。", "error_description": "错误：「来说」后多加了「了」；「对……来说」是固定框架，其后不能带动态助词「了」。正确：「对一般人来说，这件事很难理解。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不是名人，只是一只一般人。", "corrected_sentence": "他不是名人，只是一个一般人。", "error_description": "错误形式：“一只一般人”；正确形式：“一个一般人”。“一只”用于动物，指人应用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把好朋友当外人）相反。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：“高兴”只说心情，与“见外”无关。"}, {"text": "严肃", "is_correct": false, "explanation": "无反义关系：“严肃”描述态度庄重，与“见外”的客气程度不对应。"}, {"text": "懒惰", "is_correct": false, "explanation": "无反义关系：“懒惰”指不愿劳动，与“见外”的人际含义无关。"}], "correct_answer": "亲近", "explanations": {"亲近": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把好朋友当外人）相反。", "高兴": "无反义关系：“高兴”只说心情，与“见外”无关。", "严肃": "无反义关系：“严肃”描述态度庄重，与“见外”的客气程度不对应。", "懒惰": "无反义关系：“懒惰”指不愿劳动，与“见外”的人际含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。"}, {"text": "冷静", "is_correct": false, "explanation": "无反义关系：“冷静”指情绪平稳，与“见外”无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容排列有序，与“见外”无关。"}, {"text": "便宜", "is_correct": false, "explanation": "无反义关系：“便宜”指价格低，与“见外”无关。"}], "correct_answer": "亲近", "explanations": {"亲近": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。", "冷静": "无反义关系：“冷静”指情绪平稳，与“见外”无关。", "整齐": "无反义关系：“整齐”形容排列有序，与“见外”无关。", "便宜": "无反义关系：“便宜”指价格低，与“见外”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "见外是把好朋友当成外人，太客气。", "primary_collocate": null, "pronunciation": "jiàn wài", "ipa": "tɕjɛn˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "好朋友之间还说谢谢，太见外了。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把你当家人，你怎么还这么见外？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃顿饭而已，不用跟我见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对老朋友一点也不见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不肯让我帮忙，是不是跟我见外？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别见外，有事就给我打电话。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们这么熟了，你还见外什么？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是好姐妹，说话从不见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样分得清清楚楚，也太见外了吧。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有什么需要尽管说，千万别跟我见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見外", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把好朋友当外人，太客气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59bfadb7-bca0-4e03-be83-d192fc022fe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“太见外了”指把好朋友当外人、过分客气，与句中“好朋友之间还说谢谢”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与“好朋友之间还说谢谢”的语境不符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”描述环境或状态，无法评价朋友之间的客气程度。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，与朋友间说谢谢的行为无关。"}], "explanations": {"见外": "正确：“太见外了”指把好朋友当外人、过分客气，与句中“好朋友之间还说谢谢”相符。", "热闹": "语义：“热闹”形容场面喧闹，与“好朋友之间还说谢谢”的语境不符。", "安静": "语义：“安静”描述环境或状态，无法评价朋友之间的客气程度。", "漂亮": "体貌：“漂亮”形容外貌，与朋友间说谢谢的行为无关。"}, "sentence_index": 0, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放假那天我出门见外，跟几个朋友聚聚。", "explanation": "这里应该用〈见面〉。见外指过分客气，不表示出门会面；与朋友相聚要用见面。"}, {"text": "他一进门就大大咧咧地翻我的冰箱，见外得很。", "explanation": "这里应该用〈放肆〉。见外是过分客气，与翻人家冰箱的放肆正相反。"}, {"text": "我们俩亲亲热热地抱在一起，真见外。", "explanation": "这里应该用〈亲热〉。见外表示把人当外人、过分客气，与拥抱时的亲热正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“你还见外什么”指对方不必再把我当外人，与“咱们这么熟了”相符。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”说身体状况，与“咱们这么熟了”的人际语境无关。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”描述才智，无法放在“你还……什么”中表达人际态度。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多形容声音，不能用于“你还……什么”这一反问结构。"}], "explanations": {"见外": "正确：“你还见外什么”指对方不必再把我当外人，与“咱们这么熟了”相符。", "健康": "语义：“健康”说身体状况，与“咱们这么熟了”的人际语境无关。", "聪明": "语义：“聪明”描述才智，无法放在“你还……什么”中表达人际态度。", "清脆": "搭配：“清脆”多形容声音，不能用于“你还……什么”这一反问结构。"}, "sentence_index": 6, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩是老搭档，他见外地拍拍我的肩膀。", "explanation": "这里应该用〈亲近〉。见外表示把人当外人、过分客气，与拍肩的亲近正相反。"}, {"text": "孩子们见外地抢着玩具，谁也不肯让。", "explanation": "这里应该用〈不客气〉。见外是过分客气，与抢玩具的不客气正相反。"}, {"text": "一家人吃饭，他却见外地抢着盛汤。", "explanation": "这里应该用〈随便〉。见外是过分客气，与一家人吃饭时的随便正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个很见外人。", "corrected_sentence": "他是一个很见外的人。", "error_description": "错误：漏掉“的”。“见外”作定语修饰“人”时要加“的”，应说“很见外的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩这么熟，别很见外了。", "corrected_sentence": "我们俩这么熟，别太见外了。", "error_description": "错误：“很”。劝阻句中应用“太”（“别太见外了”），“很”不能用于“别”之后表示这一意思。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：“高兴”只说心情，与“见外”的人际含义无关。"}, {"text": "严肃", "is_correct": false, "explanation": "无反义关系：“严肃”描述态度庄重，与“见外”的客气程度不对应。"}, {"text": "热闹", "is_correct": false, "explanation": "无反义关系：“热闹”形容场面，与“见外”的人际含义无关。"}], "correct_answer": "亲近", "explanations": {"亲近": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。", "高兴": "无反义关系：“高兴”只说心情，与“见外”的人际含义无关。", "严肃": "无反义关系：“严肃”描述态度庄重，与“见外”的客气程度不对应。", "热闹": "无反义关系：“热闹”形容场面，与“见外”的人际含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。"}, {"text": "冷静", "is_correct": false, "explanation": "无反义关系：“冷静”指情绪平稳，与“见外”的人际含义无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容排列有序，与“见外”无关。"}, {"text": "便宜", "is_correct": false, "explanation": "无反义关系：“便宜”指价格低，与“见外”无关。"}], "correct_answer": "亲近", "explanations": {"亲近": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。", "冷静": "无反义关系：“冷静”指情绪平稳，与“见外”的人际含义无关。", "整齐": "无反义关系：“整齐”形容排列有序，与“见外”无关。", "便宜": "无反义关系：“便宜”指价格低，与“见外”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "把对方当作外人看待，过分客气。", "primary_collocate": null, "pronunciation": "jiàn wài", "ipa": "tɕjɛn˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "你帮过我很多次，我怎么会见外呢？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都是自己人，你别见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要给我钱，我说这样太见外了。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来家里吃饭，还带那么多东西，真见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再客气，我就觉得你见外了。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是老同学，不用跟我见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话很直，从来不跟朋友见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你收下这点心意，别见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在我家吧，千万别见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很见外，借支笔都说谢谢。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見外", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把对方当外人，过分客气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59bfadb7-bca0-4e03-be83-d192fc022fe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“见外”指把对方当外人、过分客气，此句表示“我不会把你当外人”。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与受人帮助后的反问语境无关。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容身材，与受人帮助后是否客气的语境无关。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”描述才智，与“你帮过我很多次”这一感激语境不相干。"}], "explanations": {"见外": "正确：“见外”指把对方当外人、过分客气，此句表示“我不会把你当外人”。", "热闹": "语义：“热闹”形容场面喧闹，与受人帮助后的反问语境无关。", "高大": "语义：“高大”形容身材，与受人帮助后是否客气的语境无关。", "聪明": "语义：“聪明”描述才智，与“你帮过我很多次”这一感激语境不相干。"}, "sentence_index": 0, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我出门见外，和朋友去郊游。", "explanation": "这里应该用〈见面〉。见外指把对方当外人而过分客气，不表示出门会面；与朋友相聚要用见面。"}, {"text": "我们俩在一起从不分彼此，见外得很。", "explanation": "这里应该用〈亲密〉。见外是把对方当外人、过分客气，与“从不分彼此”的亲密正相反。"}, {"text": "他一进门就大摇大摆地翻我的冰箱，真见外。", "explanation": "这里应该用〈放肆〉。见外指过分客气，与未经允许就乱翻东西的放肆正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“从来不跟朋友见外”指从不把朋友当外人，与“很直”的说话风格相符。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指彼此不熟悉，与“朋友”的关系矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述与朋友的相处方式。"}, {"text": "疯狂", "is_correct": false, "explanation": "语义：“疯狂”指失控的状态，与“从来不跟朋友……”的语境不搭。"}], "explanations": {"见外": "正确：“从来不跟朋友见外”指从不把朋友当外人，与“很直”的说话风格相符。", "陌生": "语义：“陌生”指彼此不熟悉，与“朋友”的关系矛盾。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述与朋友的相处方式。", "疯狂": "语义：“疯狂”指失控的状态，与“从来不跟朋友……”的语境不搭。"}, "sentence_index": 6, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一见我就热情地拥抱我，真见外。", "explanation": "这里应该用〈热情〉。见外表示把人当外人、过分客气，与一见面就拥抱的热情正相反。"}, {"text": "周末在家，他见外地躺在沙发上看电视。", "explanation": "这里应该用〈随便〉。见外是过分客气，与躺在沙发上看电视的随便正相反。"}, {"text": "孩子们一见到糖果就抢，见外得很。", "explanation": "这里应该用〈不客气〉。见外指过分客气，与抢糖果时的不客气正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别把我见外。", "corrected_sentence": "别跟我见外。", "error_description": "错误：“把我”。“见外”不能用“把”引出宾语，这一搭配的固定格式是“跟+人+见外”，应改为“别跟我见外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别很见外，有事就说。", "corrected_sentence": "别太见外，有事就说。", "error_description": "错误：“很”。劝阻句中应用“太”（“别太见外”），“很”不能用于“别”之后表示这一意思。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
