INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93333, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调教是一步一步教，让小动物或人学会规矩。", "primary_collocate": null, "pronunciation": "tiáo jiào", "ipa": "tʰiɑʊ˧˥ tɕiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我一步一步调教这只小狗。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈正在调教刚买的小猫。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗不听话，要慢慢调教。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他耐心调教了两个月，小猫才学会用厕所。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小猫还小，不懂规矩，需要调教。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过调教，这只小狗不再乱叫了。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷调教孙子很有耐心。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把小狗调教得很听话。", "target_word": "调教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的小马还没调教好。", "target_word": "调教", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天耐心调教小狗，让它不在家里乱叫。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "调教了", "label": "体标"}, {"form": "调教过", "label": "体标"}], "register": "中性", "sense_fingerprint": "一步一步教小动物或人学规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93333, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调教", "is_correct": true, "explanation": "正确答案：调教（tiáo jiào），一步步教导小动物或人，使其守规矩。"}, {"text": "调料", "is_correct": false, "explanation": "liào 与 jiào 声母不同（l / j），意思是调味用的材料。"}, {"text": "调笑", "is_correct": false, "explanation": "xiào 与 jiào 声母不同（x / j），意思是开玩笑、戏弄。"}, {"text": "调焦", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）声调不同，意思是调整焦距。"}], "explanations": {"调教": "正确答案：调教（tiáo jiào），一步步教导小动物或人，使其守规矩。", "调料": "liào 与 jiào 声母不同（l / j），意思是调味用的材料。", "调笑": "xiào 与 jiào 声母不同（x / j），意思是开玩笑、戏弄。", "调焦": "jiāo（第一声）与 jiào（第四声）声调不同，意思是调整焦距。"}, "sentence_index": null, "correct_answer": "调教"}, "level_3": {"options": [{"text": "调教", "is_correct": true, "explanation": "正确：调教指一步步教导小动物守规矩，与“一步一步”相符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋或场所，不能用于小狗。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能用于小狗。"}, {"text": "组装", "is_correct": false, "explanation": "语义：“组装”指把零件拼装成器械，与活的小狗不符。"}], "explanations": {"调教": "正确：调教指一步步教导小动物守规矩，与“一步一步”相符。", "装修": "搭配：“装修”用于房屋或场所，不能用于小狗。", "驾驶": "搭配：“驾驶”的对象是车辆，不能用于小狗。", "组装": "语义：“组装”指把零件拼装成器械，与活的小狗不符。"}, "sentence_index": 0, "correct_answer": "调教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动员每天调教跑步的速度。", "explanation": "这里应该用〈训练〉。调教指驯化动物或管教人，提高速度要用训练。"}, {"text": "学校努力调教学生的音乐兴趣。", "explanation": "这里应该用〈培养〉。调教指驯化或管教，培养兴趣要用培养。"}, {"text": "导师调教学生的毕业论文。", "explanation": "这里应该用〈指导〉。调教强调驯化或管束，指导论文要用指导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调教", "is_correct": true, "explanation": "正确：调教指管教、训练人使其守规矩，与“很有耐心”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是环境或场所，不能用于孙子。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”用于机器设备，不能用于人。"}, {"text": "加工", "is_correct": false, "explanation": "语义：“加工”指处理物料，与管教孙子的语境不合。"}], "explanations": {"调教": "正确：调教指管教、训练人使其守规矩，与“很有耐心”相符。", "打扫": "搭配：“打扫”的对象是环境或场所，不能用于孙子。", "维修": "搭配：“维修”用于机器设备，不能用于人。", "加工": "语义：“加工”指处理物料，与管教孙子的语境不合。"}, "sentence_index": 6, "correct_answer": "调教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每天调教员工的考勤。", "explanation": "这里应该用〈管理〉。调教指驯化动物或管教人，管理考勤要用管理。"}, {"text": "农民每年调教小麦。", "explanation": "这里应该用〈种植〉。调教只用于动物或人，种植庄稼要用种植。"}, {"text": "保洁员每天调教楼道。", "explanation": "这里应该用〈清洁〉。调教指驯化动物或管教人，清洁楼道要用清洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈一步一步很调教这只小猫。", "corrected_sentence": "妈妈一步一步调教这只小猫。", "error_description": "错误：“很”是程度副词，不能修饰动词“调教”，应去掉“很”。正确：“妈妈一步一步调教这只小猫。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲把这只狗调教。", "corrected_sentence": "父亲把这只狗调教好。", "error_description": "错误：“把”字句中动词后要有结果补语，“把这只狗调教”不完整。正确：“父亲把这只狗调教好。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
