INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "训练教导（动物或人），使其学会某种技能或规矩。", "primary_collocate": null, "pronunciation": "tiáo jiào", "ipa": "tʰiɑʊ˧˥ tɕiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他花了三年调教这只警犬。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "驯兽师正在调教一只小老虎。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这匹马调教得很好，一听口令就走。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过几个月的调教，小狗学会了握手。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想把这只鹦鹉调教成会说话的宠物。", "target_word": "调教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅严格调教新来的徒弟。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练调教运动员很有办法。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸟刚买来，还没有调教过。", "target_word": "调教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把调教狗的方法写成了一本书。", "target_word": "调教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他调教出来的猎犬跑得又快又稳。", "target_word": "调教", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "调教了", "label": "体标"}, {"form": "调教过", "label": "体标"}], "register": "中性", "sense_fingerprint": "训练教导动物或人，使其学会技能或规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
