INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调教", "is_correct": true, "explanation": "正确：调教指训练教导人，使其守规矩、学本领，与“很有办法”的语境相符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋和场所，不能以运动员为对象。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”用于机器和设备，不能用于运动员。"}, {"text": "加工", "is_correct": false, "explanation": "语义：“加工”指对材料或产品做处理，与教练带运动员的语境不合。"}], "explanations": {"调教": "正确：调教指训练教导人，使其守规矩、学本领，与“很有办法”的语境相符。", "装修": "搭配：“装修”用于房屋和场所，不能以运动员为对象。", "维修": "搭配：“维修”用于机器和设备，不能用于运动员。", "加工": "语义：“加工”指对材料或产品做处理，与教练带运动员的语境不合。"}, "sentence_index": 6, "correct_answer": "调教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天调教身体，很认真。", "explanation": "这里应该用〈锻炼〉。调教指驯化动物或管教人，不用于身体锻炼。"}, {"text": "我每天花十分钟调教书桌。", "explanation": "这里应该用〈整理〉。调教指驯化动物或管教人，不用于书桌，整理书桌要用整理。"}, {"text": "工人每天调教水管。", "explanation": "这里应该用〈检修〉。调教指训练教导动物或人，不用于水管，检修水管要用检修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这匹马调教很听话。", "corrected_sentence": "这匹马调教得很听话。", "error_description": "错误：状态补语前漏了“得”。“调教很听话”应为“调教得很听话”，“得”用来引出表示程度的补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只小猫刚买来，还没调教了。", "corrected_sentence": "这只小猫刚买来，还没调教过。", "error_description": "错误：否定尚未发生的经历要用“没……过”，“没调教了”不成立。正确：“还没调教过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
