INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93337, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "调查者是去问、去看，弄清楚事情的人。", "primary_collocate": null, "pronunciation": "diào chá zhě", "ipa": "tjɑʊ˥˩ ʈʂʰa˧˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "调查者到村里看了看，也问了很多人。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位调查者想弄清楚河水为什么变黑了。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察是这件事的调查者之一。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的调查者既要多问，也要多看。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者在现场找到了一把旧钥匙。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个认真的调查者，每件事都问清楚。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者走了很多地方，才知道真相。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李做过调查者，知道怎么问人。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者想知道事情是怎么发生的。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者像调查者一样，去现场看一看。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "調查者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "去问去看、弄清楚事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调查者", "is_correct": true, "explanation": "正确：“调查者”指去问、去看、弄清事情的人，符合“到村里看了看，也问了很多人”的语境。"}, {"text": "被调查者", "is_correct": false, "explanation": "语义：“被调查者”是接受调查的人，不会到村里去看、去问，与句意冲突。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不能到村里去看、去问，与句中的施事冲突。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“问人”的主语必须是人，花朵不能去问人。"}], "explanations": {"调查者": "正确：“调查者”指去问、去看、弄清事情的人，符合“到村里看了看，也问了很多人”的语境。", "被调查者": "语义：“被调查者”是接受调查的人，不会到村里去看、去问，与句意冲突。", "镜子": "语义：镜子不能到村里去看、去问，与句中的施事冲突。", "花朵": "搭配：“问人”的主语必须是人，花朵不能去问人。"}, "sentence_index": 0, "correct_answer": "调查者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这件事写成了调查者，发表在报纸上。", "explanation": "这里应该用〈调查报告〉。调查者指进行调查的人，不能当作文章写出来或发表；写出来的要说“调查报告”。"}, {"text": "我是这次的调查者，别人问了我很多问题。", "explanation": "这里应该用〈被调查者〉。句中“我”是被问的人，不是去问的人。"}, {"text": "他是一把调查者。", "explanation": "这里应该用〈位〉。调查者指人，量词要用“位”或“个”；“把”多用于有柄的物件，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调查者", "is_correct": true, "explanation": "正确：“调查者”指去问、去看、弄清事情的人，符合“走了很多地方，才知道真相”的语境。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会去问人、看事情，也就无从知道真相。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能走访各地，也不会知道真相。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“走”的主语应是人，眼镜不能说走了很多地方。"}], "explanations": {"调查者": "正确：“调查者”指去问、去看、弄清事情的人，符合“走了很多地方，才知道真相”的语境。", "河流": "语义：河流不会去问人、看事情，也就无从知道真相。", "石头": "语义：石头不能走访各地，也不会知道真相。", "眼镜": "搭配：“走”的主语应是人，眼镜不能说走了很多地方。"}, "sentence_index": 6, "correct_answer": "调查者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那块石头是个调查者。", "explanation": "这里应该用〈证据〉。调查者指进行调查的人，不能指石头这样的实物；实物用作线索时要说“证据”。"}, {"text": "这次的调查者被印成了书，一共三百页。", "explanation": "这里应该用〈调查报告〉。调查者指进行调查的人，不能指被印成书的文件；说印成书、有几页，要用“调查报告”。"}, {"text": "我是那次的调查者，被记者问了很多问题。", "explanation": "这里应该用〈受访者〉。句中“我”是被问的人，调查者是去问的人，角色正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只调查者到村里去问人。", "corrected_sentence": "一位调查者到村里去问人。", "error_description": "量词错误：调查者指人，应用“位”，“只”用于动物，应改为“一位调查者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位调查者们在村里问了很多人。", "corrected_sentence": "三位调查者在村里问了很多人。", "error_description": "错误在“们”：“三位”已表示数量，不能再加“们”，应说“三位调查者”，不能说“三位调查者们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
