INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进行调查的人。", "primary_collocate": null, "pronunciation": "diào chá zhě", "ipa": "tjɑʊ˥˩ ʈʂʰa˧˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "调查者向路人问了几个问题。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的调查者一共有二十个人。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者要把结果写在表格里。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位调查者敲开了我家的门。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者说，大多数人喜欢坐地铁。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者不能改变调查的结果。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了几位调查者来做市场调查。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位调查者很有礼貌，也很耐心。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者把问卷交给了老师。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查者们在街上发了很多表。", "target_word": "调查者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "調查者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "进行调查的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调查者", "is_correct": true, "explanation": "正确：“调查者”指进行调查、去问人的人，符合“向路人问问题”的语境。"}, {"text": "被调查者", "is_correct": false, "explanation": "语义：“被调查者”是接受调查的人，不会去向路人提问，与句意的施事冲突。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能提问，与句中“问了几个问题”的主语冲突。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“问”的主语须是人，不能说花朵问问题。"}], "explanations": {"调查者": "正确：“调查者”指进行调查、去问人的人，符合“向路人问问题”的语境。", "被调查者": "语义：“被调查者”是接受调查的人，不会去向路人提问，与句意的施事冲突。", "石头": "语义：石头不能提问，与句中“问了几个问题”的主语冲突。", "花朵": "搭配：“问”的主语须是人，不能说花朵问问题。"}, "sentence_index": 0, "correct_answer": "调查者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一只调查者敲开了我家的门。", "explanation": "这里量词用错：调查者指人，要用〈位〉或〈个〉，“只”用于动物。"}, {"text": "我是这次的调查者，被大家问了很多问题。", "explanation": "这里应该用〈被调查者〉。句中“我”是被问的人，调查者是去问的人，角色相反。"}, {"text": "这台机器是个调查者。", "explanation": "这里应该用〈探测器〉。调查者指进行调查的人，不能指机器；用机器检测，要说“探测器”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调查者", "is_correct": true, "explanation": "正确：“调查者”指进行调查的人，符合“公司请人来做市场调查”的语境。"}, {"text": "被访者", "is_correct": false, "explanation": "语义：“被访者”是接受访问的人，不是被请来做调查的人，与句意冲突。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“机器”不用“位”计量，也不说“请了几位机器”。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“树木”不能被请来做市场调查，也不用“位”计量。"}], "explanations": {"调查者": "正确：“调查者”指进行调查的人，符合“公司请人来做市场调查”的语境。", "被访者": "语义：“被访者”是接受访问的人，不是被请来做调查的人，与句意冲突。", "机器": "搭配：“机器”不用“位”计量，也不说“请了几位机器”。", "树木": "搭配：“树木”不能被请来做市场调查，也不用“位”计量。"}, "sentence_index": 6, "correct_answer": "调查者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在那次活动里是调查者，被问了很多问题。", "explanation": "这里应该用〈受访者〉。句中“他”是被问的人，调查者是去问的人，两者角色不同。"}, {"text": "这个调查者一共有三十页，写得很详细。", "explanation": "这里应该用〈调查报告〉。调查者指人，不能指文件；说文件有几页、写得详细，要用“调查报告”。"}, {"text": "那座调查者很有礼貌。", "explanation": "量词用错：调查者指人，应用“位”，“座”用于建筑等大件物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只调查者在小区里访问了居民。", "corrected_sentence": "两位调查者在小区里访问了居民。", "error_description": "量词错误：调查者指人，应用“位”，“只”用于动物，应改为“两位调查者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位调查问了很多路人。", "corrected_sentence": "几位调查者问了很多路人。", "error_description": "漏掉了“者”：“调查”是动词，不能用来指人；指进行调查的人要说“调查者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
