INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一点不是一点也不。说一点不累，就是不累。", "primary_collocate": null, "pronunciation": "yì diǎn bù", "ipa": "i˥˩ tiɛn˨˩˦ pu˥˩", "syllable_count": 3, "sentences": [{"text": "他一点不胖，你为什么说他胖？", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一点不饿，你们先吃吧。", "target_word": "一点不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子一点不怕生，见谁都说话。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里一点不热，开着空调呢。", "target_word": "一点不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语很好，说话一点不紧张。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服一点不小，我穿正合适。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一点不想去，因为太远了。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一点不着急，慢慢地吃早饭。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上一点不堵，我们很快就到了。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了这个消息，她一点不高兴。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点儿不", "label": "儿化变体"}, {"form": "一點不", "label": "繁体"}], "register": "口语", "sense_fingerprint": "等于一点也不，后接形容词或心理动词表示完全不", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c6695f-4d15-45b9-91eb-7195eb7df105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语义：“非常胖”说他很胖，与后面“你为什么说他胖”的反问相矛盾。"}, {"text": "甚", "is_correct": false, "explanation": "语域：“甚”是书面用语，口语里不这样说；“甚胖”同样与反问的语境矛盾。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别胖”同样表示他很胖，与“你为什么说他胖”不协调。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不胖，与“你为什么说他胖”的反问相呼应，符合语境。"}], "explanations": {"非常": "语义：“非常胖”说他很胖，与后面“你为什么说他胖”的反问相矛盾。", "甚": "语域：“甚”是书面用语，口语里不这样说；“甚胖”同样与反问的语境矛盾。", "特别": "语义：“特别胖”同样表示他很胖，与“你为什么说他胖”不协调。", "一点不": "一点不：表示完全不胖，与“你为什么说他胖”的反问相呼应，符合语境。"}, "sentence_index": 0, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚跑完马拉松，腿软得站不住，一点不累。", "explanation": "这里应该用〈很〉（很累）。“一点不累”表示完全不累，与“腿软得站不住”所说的疲劳相矛盾。"}, {"text": "屋里暖气烧得很足，他却一点不热，脱掉了外套。", "explanation": "这里应该用〈有点〉（有点热）。“一点不热”表示完全不热，与“脱掉了外套”的动作相矛盾。"}, {"text": "我一点不困，所以打了一个大哈欠。", "explanation": "这里应该用〈挺〉（挺困的）。“一点不困”表示完全不困，与“打了一个大哈欠”所表现的困倦相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最", "is_correct": false, "explanation": "语义：“最想去”表示意愿最强，与后面“因为太远了”的不去理由相矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "语义：“十分想去”表示很想去，与“因为太远了”作为理由相矛盾。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”要与前面的转折相呼应，此句没有转折语境，“却想去”不通。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不想去，与“因为太远了”构成理由，语义连贯。"}], "explanations": {"最": "语义：“最想去”表示意愿最强，与后面“因为太远了”的不去理由相矛盾。", "十分": "语义：“十分想去”表示很想去，与“因为太远了”作为理由相矛盾。", "却": "搭配：“却”要与前面的转折相呼应，此句没有转折语境，“却想去”不通。", "一点不": "一点不：表示完全不想去，与“因为太远了”构成理由，语义连贯。"}, "sentence_index": 6, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一点不生气，把桌子拍得直响。", "explanation": "这里应该用〈非常〉（非常生气）。“一点不生气”表示完全不生气，与“把桌子拍得直响”所表现的怒气相矛盾。"}, {"text": "我一点不怕黑，吓得躲进了被子里。", "explanation": "这里应该用〈特别〉（特别怕黑）。“一点不怕黑”表示完全不怕，与“吓得躲进了被子里”的害怕相矛盾。"}, {"text": "他一点不冷，冻得直打哆嗦。", "explanation": "这里应该用〈很〉（很冷）。“一点不冷”表示完全不冷，与“冻得直打哆嗦”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的同学一点不不怕老师。", "corrected_sentence": "我们班的同学一点不怕老师。", "error_description": "“不”重复出现，形成双重否定，句意与原意相反。错误形式：一点不不怕；正确形式：一点不怕。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子一点不的晃，很稳。", "corrected_sentence": "这张桌子一点不晃，很稳。", "error_description": "“一点不”后面直接接形容词或动词，中间不能加“的”。错误形式：一点不的晃；正确形式：一点不晃。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
