INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一点也不；完全不。用于加强否定语气。", "primary_collocate": null, "pronunciation": "yì diǎn bù", "ipa": "i˥˩ tiɛn˨˩˦ pu˥˩", "syllable_count": 3, "sentences": [{"text": "这道菜一点不辣，你放心吃。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一点不累，还能再走一会儿。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲得太快，我一点不懂。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天天气很好，我一点不冷。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，这件事一点不难。", "target_word": "一点不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一点不生气，还笑着对我说话。", "target_word": "一点不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方一点不远，走十分钟就到。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天睡得很好，今天一点不困。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书一点不贵，才十块钱。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一点不怕黑，一个人在家很好。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点儿不", "label": "儿化变体"}, {"form": "一點不", "label": "繁体"}], "register": "口语", "sense_fingerprint": "放在形容词或动词前，完全否定，加强否定语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c6695f-4d15-45b9-91eb-7195eb7df105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太", "is_correct": false, "explanation": "语义：“太辣”表示辣得过分，与后面的“你放心吃”相矛盾。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最辣”表示辣度居首，同样与“你放心吃”的语境不符。"}, {"text": "甚是", "is_correct": false, "explanation": "语域：“甚是”偏书面语，这句口语里不这样说；而且“甚是辣”仍与“你放心吃”矛盾。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不辣，与“你放心吃”相呼应，符合语境。"}], "explanations": {"太": "语义：“太辣”表示辣得过分，与后面的“你放心吃”相矛盾。", "最": "语义：“最辣”表示辣度居首，同样与“你放心吃”的语境不符。", "甚是": "语域：“甚是”偏书面语，这句口语里不这样说；而且“甚是辣”仍与“你放心吃”矛盾。", "一点不": "一点不：表示完全不辣，与“你放心吃”相呼应，符合语境。"}, "sentence_index": 0, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿极了，一点不想吃饭。", "explanation": "这里应该用〈很〉（很想吃饭）。“一点不”表示完全没有某种意愿，与“饿极了”的状态正相反。"}, {"text": "我的腿一点不疼，可是走起路来还是一瘸一拐的。", "explanation": "这里应该用〈有点〉（有点疼）。「一点不疼」表示完全不疼，与「一瘸一拐」所表现的疼痛相矛盾。"}, {"text": "我一点不喝酒，只喝了一小杯。", "explanation": "这里应该用〈很少〉（很少喝酒）。“一点不”表示完全不做某事，与“只喝了一小杯”的少量相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语义：“非常远”说明距离很远，与“走十分钟就到”矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "语义：“十分远”同样说明很远，与“走十分钟就到”不符。"}, {"text": "甚", "is_correct": false, "explanation": "语域：“甚”偏书面，口语里不用；“甚远”也与“走十分钟就到”矛盾。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不远，与“走十分钟就到”相呼应，符合语境。"}], "explanations": {"非常": "语义：“非常远”说明距离很远，与“走十分钟就到”矛盾。", "十分": "语义：“十分远”同样说明很远，与“走十分钟就到”不符。", "甚": "语域：“甚”偏书面，口语里不用；“甚远”也与“走十分钟就到”矛盾。", "一点不": "一点不：表示完全不远，与“走十分钟就到”相呼应，符合语境。"}, "sentence_index": 6, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她刚拿到第一名，一点不开心，笑个不停。", "explanation": "这里应该用〈非常〉（非常开心）。“一点不”表示完全没有某种感受，与“笑个不停”所表现的快乐相矛盾。"}, {"text": "这次考试他一点不紧张，手心全是汗。", "explanation": "这里应该用〈特别〉（特别紧张）。“一点不”表示完全不紧张，与“手心全是汗”所描述的紧张相矛盾。"}, {"text": "这个孩子一点不害怕，躲在妈妈身后直发抖。", "explanation": "这里应该用〈有些〉（有些害怕）。“一点不”表示完全不怕，与“躲在妈妈身后直发抖”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服很一点不贵。", "corrected_sentence": "这件衣服一点不贵。", "error_description": "“一点不”前面不能再加程度副词“很”。错误形式：很一点不贵；正确形式：一点不贵。“一点不”本身已表示完全否定，不能与“很”叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路一点不都陡。", "corrected_sentence": "这条路一点不陡。", "error_description": "语序错误：“一点不”是整体的否定副词，后面直接接形容词，不能再插入“都”。错误形式：一点不都陡；正确形式：一点不陡（或：一点都不陡）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
