INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出钱或出物，支持某项活动或某人。", "primary_collocate": null, "pronunciation": "zàn zhù", "ipa": "tsan˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司赞助了我们的比赛。", "target_word": "赞助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每年都赞助一些学生。", "target_word": "赞助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁来赞助这次活动？", "target_word": "赞助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸的朋友赞助了他上大学。", "target_word": "赞助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司赞助过很多体育比赛。", "target_word": "赞助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行愿意赞助这场音乐会。", "target_word": "赞助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们没有钱，需要有人赞助。", "target_word": "赞助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个品牌赞助了学校的运动会。", "target_word": "赞助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板赞助我们十台电脑。", "target_word": "赞助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想找一家公司赞助她的画展。", "target_word": "赞助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞助了", "label": "体标"}, {"form": "赞助过", "label": "体标"}, {"form": "赞助商", "label": "复合"}, {"form": "贊助", "label": "繁体"}], "register": "中性", "sense_fingerprint": "出钱或物支持活动或某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5820b4e1-82a5-40c0-ae4a-682d87027408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞助", "is_correct": true, "explanation": "正确。赞助是出钱或出物支持比赛，与“这家公司”的身份和语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不与“比赛”搭配，不能说喝比赛。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与举办或支持比赛的行为无关。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要带接受者，“送了我们的比赛”结构不完整，语义也不通。"}], "explanations": {"赞助": "正确。赞助是出钱或出物支持比赛，与“这家公司”的身份和语境相符。", "喝": "搭配：“喝”不与“比赛”搭配，不能说喝比赛。", "吃": "语义：“吃”指进食，与举办或支持比赛的行为无关。", "送": "配价：“送”要带接受者，“送了我们的比赛”结构不完整，语义也不通。"}, "sentence_index": 0, "correct_answer": "赞助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我赞助你的想法。", "explanation": "这里应该用〈赞成〉。赞助是出钱或出物支持，不能用于对想法表示同意。"}, {"text": "老师赞助了他的作业。", "explanation": "这里应该用〈赞美〉。赞助指出钱物支持，不用于对作业的称赞。"}, {"text": "他赞助我解决了问题。", "explanation": "这里应该用〈帮助〉。赞助指出钱物支持，不用于一般的协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞助", "is_correct": true, "explanation": "正确。“没有钱，需要有人”出钱支持，正好是赞助的意思。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讽刺意味，与没钱需要帮助的语境相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不能表示需要别人提供帮助。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要带被扔的东西，“需要有人扔”缺少宾语。"}], "explanations": {"赞助": "正确。“没有钱，需要有人”出钱支持，正好是赞助的意思。", "嘲笑": "语义：“嘲笑”带有讽刺意味，与没钱需要帮助的语境相反。", "忘记": "语义：“忘记”不能表示需要别人提供帮助。", "扔": "配价：“扔”需要带被扔的东西，“需要有人扔”缺少宾语。"}, "sentence_index": 6, "correct_answer": "赞助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她赞助孩子长大。", "explanation": "这里应该用〈陪伴〉。赞助指出钱物支持，不能用来说陪伴孩子成长。"}, {"text": "他赞助了我一个拥抱。", "explanation": "这里应该用〈给〉。赞助指出钱物支持，不能用来表示给人一个拥抱。"}, {"text": "他赞助童年的事。", "explanation": "这里应该用〈回忆〉。赞助不用于对往事的回想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市赞助了过学校的晚会。", "corrected_sentence": "这家超市赞助过学校的晚会。", "error_description": "错误：“赞助了过”，同时用了“了”和“过”两个动态助词。正确：“赞助过”，表示曾有过这种经历，不再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家银行赞助的这次展览。", "corrected_sentence": "这家银行赞助了这次展览。", "error_description": "错误：“的”代替了“了”，使“赞助的这次展览”成为名词短语，句子缺少谓语。正确：动词后用“了”表示完成，写作“这家银行赞助了这次展览。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
