INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93344, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组织机构中职位或层级比自己高的人或单位。", "primary_collocate": null, "pronunciation": "shàng jí", "ipa": "ʂɑŋ˥˩ t͡ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这件事要先报告上级。", "target_word": "上级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上级发来了新通知。", "target_word": "上级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要听上级的安排。", "target_word": "上级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂把情况告诉了上级。", "target_word": "上级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级明天要来公司检查工作。", "target_word": "上级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的上级是经理，经理的上级是总经理。", "target_word": "上级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要服从上级的命令。", "target_word": "上级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "县里的上级是市里。", "target_word": "上级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上级对这个办法很满意。", "target_word": "上级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "如果上级同意，我们就开始做。", "target_word": "上级", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位上级", "label": "量词"}, {"form": "上级部门", "label": "复合"}], "register": "中性", "sense_fingerprint": "组织中层级更高的人或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5cbcac1-4e17-487d-bba3-6efb4b2cfcde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上级", "is_correct": true, "explanation": "正确：“上级”是组织中层级更高的人或单位，可以接受“报告”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是物体，不能接受报告，语义不通。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：“水杯”不是组织或人，不能作“报告”的对象。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：“报告”要求接收者是人或机构，“雨伞”不能作报告的对象。"}], "explanations": {"上级": "正确：“上级”是组织中层级更高的人或单位，可以接受“报告”。", "冰箱": "语义：“冰箱”是物体，不能接受报告，语义不通。", "水杯": "语义：“水杯”不是组织或人，不能作“报告”的对象。", "雨伞": "配价：“报告”要求接收者是人或机构，“雨伞”不能作报告的对象。"}, "sentence_index": 0, "correct_answer": "上级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他是同班同学，他是我的上级。", "explanation": "这里应该用〈同学〉。“上级”指组织中层级更高的人，同班同学之间是平等的，没有上下级。"}, {"text": "这家饭店是我们公司的上级。", "explanation": "这里应该用〈合作单位〉。“上级”指有管理关系的单位，合作单位之间不是上下级。"}, {"text": "他是我小时候的上级，我们常常一起玩。", "explanation": "这里应该用〈玩伴〉。“上级”指工作或组织中的上下级关系，小时候一起玩的人是玩伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上级", "is_correct": true, "explanation": "正确：“上级”是组织中有命令权的人，符合“服从……的命令”的说法。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是有意志的主体，不能服从命令。"}, {"text": "闹钟", "is_correct": false, "explanation": "配价：“服从”要求有意志的主体，“闹钟”不能作服从的对象。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”不与“服从……的命令”搭配，不能发出命令。"}], "explanations": {"上级": "正确：“上级”是组织中有命令权的人，符合“服从……的命令”的说法。", "天空": "语义：“天空”不是有意志的主体，不能服从命令。", "闹钟": "配价：“服从”要求有意志的主体，“闹钟”不能作服从的对象。", "石头": "搭配：“石头”不与“服从……的命令”搭配，不能发出命令。"}, "sentence_index": 6, "correct_answer": "上级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同桌是我的上级，所以我们一起做作业。", "explanation": "这里应该用〈搭档〉。“上级”表示职位高低，一起做作业的搭档之间没有职位关系。"}, {"text": "这只猫是我们单位的上级。", "explanation": "这里应该用〈吉祥物〉。“上级”指有管理权的人或单位，不能指动物。"}, {"text": "我们俩同一年出生，是同岁的上级。", "explanation": "这里应该用〈同龄人〉。“上级”表示职位高低，不表示年龄相同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事要先上级报告。", "corrected_sentence": "这件事要先向上级报告。", "error_description": "错误：缺少介词“向”，“上级”作报告的对象时要用介词引出。正确：说“先向上级报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该尊重一只上级的决定。", "corrected_sentence": "我们应该尊重一位上级的决定。", "error_description": "错误：“上级”指人，量词应用“位”，不能用“只”。正确：说“一位上级的决定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
