INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人名是一个人的名字。", "primary_collocate": null, "pronunciation": "rén míng", "ipa": "ʐən˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个人名怎么读？", "target_word": "人名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小李是一个常见的人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的书里有很多外国人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试要写出课文中的人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人名听起来很特别。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我常常记不住新认识的人名。", "target_word": "人名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地名和人名都要大写。", "target_word": "人名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把这个人名读两遍。", "target_word": "人名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个人名是什么意思吗？", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在本子上写了几个人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个人名", "label": "量词"}, {"form": "人名地名", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5cbcac1-4e17-487d-bba3-6efb4b2cfcde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93347, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人名", "is_correct": true, "explanation": "正确。人名 rén míng 指一个人的名字。"}, {"text": "人民", "is_correct": false, "explanation": "人民 rénmín 与 人名 rénmíng 只有第二音节韵尾不同（-n 与 -ng），意思是人民群众。"}, {"text": "人命", "is_correct": false, "explanation": "人命 rénmìng 只有第二音节声调不同（第四声与第二声），意思是人的生命。"}, {"text": "任命", "is_correct": false, "explanation": "任命 rènmìng 的两个音节声调都和 人名 rénmíng 不同。任命的意思是委派职务。"}, {"text": "认命", "is_correct": false, "explanation": "认命 rènmìng 的两个音节声调都和 人名 rénmíng 不同。认命的意思是接受命运。"}], "explanations": {"人名": "正确。人名 rén míng 指一个人的名字。", "人民": "人民 rénmín 与 人名 rénmíng 只有第二音节韵尾不同（-n 与 -ng），意思是人民群众。", "人命": "人命 rénmìng 只有第二音节声调不同（第四声与第二声），意思是人的生命。", "任命": "任命 rènmìng 的两个音节声调都和 人名 rénmíng 不同。任命的意思是委派职务。", "认命": "认命 rènmìng 的两个音节声调都和 人名 rénmíng 不同。认命的意思是接受命运。"}, "sentence_index": null, "correct_answer": "人名"}, "level_3": {"options": [{"text": "人名", "is_correct": true, "explanation": "正确。人名是一个人的名字，这个人名可以问怎么读。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“怎么读”用于文字、名称，不说“读饭菜”。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是电器，不是可以朗读的文字，与“怎么读”不合。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是衣物，没有读法，与“怎么读”冲突。"}], "explanations": {"人名": "正确。人名是一个人的名字，这个人名可以问怎么读。", "饭菜": "搭配：“怎么读”用于文字、名称，不说“读饭菜”。", "空调": "语义：空调是电器，不是可以朗读的文字，与“怎么读”不合。", "手套": "语义：手套是衣物，没有读法，与“怎么读”冲突。"}, "sentence_index": 0, "correct_answer": "人名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我欠他一个人名。", "explanation": "这里应该用〈人情〉。“欠”的是人情，指人与人之间的情分或恩惠；人名指人的姓名，不能欠。"}, {"text": "这条河的人名很好听。", "explanation": "这里应该用〈地名〉。人名专指人的姓名，河流的名称要说地名。"}, {"text": "老师在人名上记下了迟到的同学。", "explanation": "这里应该用〈名册〉。名册是登记名字的册子，人名是人的姓名，不能当作记录的表格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人名", "is_correct": true, "explanation": "正确。“地名和人名都要大写”，人名是需要大写的专名。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：汉字是方块字，没有大小写之分，不能说“都要大写”。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字没有大小写之分，不能说“都要大写”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不是需要书写形式处理的名称，与“大写”不合。"}], "explanations": {"人名": "正确。“地名和人名都要大写”，人名是需要大写的专名。", "汉字": "语义：汉字是方块字，没有大小写之分，不能说“都要大写”。", "数字": "语义：数字没有大小写之分，不能说“都要大写”。", "颜色": "语义：颜色是视觉属性，不是需要书写形式处理的名称，与“大写”不合。"}, "sentence_index": 6, "correct_answer": "人名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个物品的人名是什么？", "explanation": "这里应该用〈名称〉。人名只指人的姓名，问物品的叫法要用名称。"}, {"text": "他以学习的人名出国了。", "explanation": "这里应该用〈名义〉。“以……的名义”表示借口或身份，人名不能这样用。"}, {"text": "他买的是人名服装。", "explanation": "这里应该用〈名牌〉。名牌指有名的品牌，服装的牌子要说名牌，人名不能修饰服装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天记住了两本人名。", "corrected_sentence": "我昨天记住了两个人名。", "error_description": "“两本人名”错在量词：“本”多用于书册，人名作量词应用“个”，应说“两个人名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前从没见了这个人名。", "corrected_sentence": "我以前从没见过这个人名。", "error_description": "“了”用错了体标：否定经历要用“没……过”，“从没”后不能用“了”。正确：说“从没见过这个人名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
