INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的姓名。", "primary_collocate": null, "pronunciation": "rén míng", "ipa": "ʐən˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书里有很多人名。", "target_word": "人名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个人名我不认识。", "target_word": "人名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地图上有地名，书里有人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人名很长，我记不住。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国人名一般有姓和名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们读课文里的人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国人名翻译成中文很难。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上出现了很多人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这个人名写错了。", "target_word": "人名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在名单上查一查这个人名。", "target_word": "人名", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个人名", "label": "量词"}, {"form": "人名地名", "label": "复合"}], "register": "中性", "sense_fingerprint": "人的姓名，区别于地名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5cbcac1-4e17-487d-bba3-6efb4b2cfcde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人名", "is_correct": true, "explanation": "正确。人名 rén míng 指人的姓名。"}, {"text": "人民", "is_correct": false, "explanation": "人民 rénmín 与 人名 rénmíng 只有第二音节韵尾不同（-n 与 -ng），意思是人民群众。"}, {"text": "任命", "is_correct": false, "explanation": "任命 rènmìng 两个音节的声调都与 人名 rénmíng 不同，意思是委派职务。"}, {"text": "人命", "is_correct": false, "explanation": "人命 rénmìng 只有第二音节声调不同（第四声与第二声），意思是人的生命。"}, {"text": "认命", "is_correct": false, "explanation": "认命 rènmìng 两个音节的声调都与 人名 rénmíng 不同，意思是接受命运。"}], "explanations": {"人名": "正确。人名 rén míng 指人的姓名。", "人民": "人民 rénmín 与 人名 rénmíng 只有第二音节韵尾不同（-n 与 -ng），意思是人民群众。", "任命": "任命 rènmìng 两个音节的声调都与 人名 rénmíng 不同，意思是委派职务。", "人命": "人命 rénmìng 只有第二音节声调不同（第四声与第二声），意思是人的生命。", "认命": "认命 rènmìng 两个音节的声调都与 人名 rénmíng 不同，意思是接受命运。"}, "sentence_index": null, "correct_answer": "人名"}, "level_3": {"options": [{"text": "人名", "is_correct": true, "explanation": "正确。人名指人的姓名，书里可以有很多人名。"}, {"text": "空气", "is_correct": false, "explanation": "语义：书里不会装着很多空气，与“这本书里”不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“书里有”一般接文字、图画，不接窗户。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，不会装在书里，与“书里有”矛盾。"}], "explanations": {"人名": "正确。人名指人的姓名，书里可以有很多人名。", "空气": "语义：书里不会装着很多空气，与“这本书里”不符。", "窗户": "搭配：“书里有”一般接文字、图画，不接窗户。", "书包": "语义：书包是装书的袋子，不会装在书里，与“书里有”矛盾。"}, "sentence_index": 0, "correct_answer": "人名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们学校的人名。", "explanation": "这里应该用〈名人〉。人名指人的姓名，名人指有名望的人，“他是……的”要用名人。"}, {"text": "交通安全关系到每个人名。", "explanation": "这里应该用〈人命〉。“关系到”的是人的生命，即人命；人名只指人的姓名，读音相近但意思不同。"}, {"text": "我们要为人名服务。", "explanation": "这里应该用〈人民〉。“为……服务”的对象是人民；人名只指姓名，读音与人民相近，但不能服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人名", "is_correct": true, "explanation": "正确。外国人名指外国人的姓名，翻译成中文很难。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，不能被翻译成中文。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以被翻译的文字或名称，“外国空气”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是文字或名称，不能被翻译成中文。"}], "explanations": {"人名": "正确。外国人名指外国人的姓名，翻译成中文很难。", "大象": "语义：大象是动物，不能被翻译成中文。", "空气": "语义：空气不是可以被翻译的文字或名称，“外国空气”不成立。", "天气": "语义：天气不是文字或名称，不能被翻译成中文。"}, "sentence_index": 6, "correct_answer": "人名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我欠他一个人名。", "explanation": "这里应该用〈人情〉。“欠”的是人情，指人与人之间的情分或恩惠；人名指人的姓名，不能欠。"}, {"text": "班长在人名上记下了迟到的同学。", "explanation": "这里应该用〈名单〉。人名是人的姓名，不是记录用的表格；“在……上记下”要用名单。"}, {"text": "他一直很看重人名。", "explanation": "这里应该用〈名声〉。“看重”的是名声，即社会上的评价；人名只指人的姓名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在纸上写了一只人名。", "corrected_sentence": "他在纸上写了一个人名。", "error_description": "“一只人名”错在量词：“只”多用于动物，人名作量词应用“个”，应说“一个人名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在报纸上看到了一只外国人名。", "corrected_sentence": "我在报纸上看到了一个外国人名。", "error_description": "“一只外国人名”的量词用错了。“只”多用于动物，人名的量词要用“个”，应该说“一个外国人名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f1466b-9760-465d-a291-b3d78710f73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "醒来是睡着以后，睁开眼睛。", "primary_collocate": null, "pronunciation": "xǐng lái", "ipa": "ɕiŋ˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "今天早上我六点就醒来了。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他醒来的时候，天还没有亮。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子醒来以后，先找妈妈。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我醒来看了看手机，已经八点了。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她醒来以后，看见窗外有太阳。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫醒来了，慢慢走到我身边。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上太累，我今早很晚才醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闹钟响了，可是他没有醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你醒来的时候，我已经做好早饭了。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我醒来时，房间里很安静。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醒来了", "label": "体标"}, {"form": "醒来过", "label": "体标"}, {"form": "醒來", "label": "繁体"}], "register": "通用", "sense_fingerprint": "睡着以后睁开眼睛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b5a7c1a-21c0-4822-b161-907b245b99f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "醒来", "is_correct": true, "explanation": "正确。醒来指睡着以后睁开眼睛，与“六点就”的起床语境相符。"}, {"text": "下课", "is_correct": false, "explanation": "语义：早上六点不会下课，与“今天早上”的时间矛盾。"}, {"text": "吃晚饭", "is_correct": false, "explanation": "语义：早上六点不吃晚饭，与“今天早上”的时间矛盾。"}, {"text": "醒悟", "is_correct": false, "explanation": "搭配：醒悟要说“醒悟过来”或指想明白道理，不说“六点就醒悟了”。"}], "explanations": {"醒来": "正确。醒来指睡着以后睁开眼睛，与“六点就”的起床语境相符。", "下课": "语义：早上六点不会下课，与“今天早上”的时间矛盾。", "吃晚饭": "语义：早上六点不吃晚饭，与“今天早上”的时间矛盾。", "醒悟": "搭配：醒悟要说“醒悟过来”或指想明白道理，不说“六点就醒悟了”。"}, "sentence_index": 0, "correct_answer": "醒来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸醒来了妹妹，让她起床上学。", "explanation": "这里应该用〈叫醒〉。醒来是不及物动词，不能带宾语表示使别人醒过来，应说叫醒。"}, {"text": "我整夜醒来，一直没有合眼。", "explanation": "这里应该用〈醒着〉。醒来是从睡眠中醒过来，句中说整夜醒来又一直没有合眼，表示整夜保持清醒，与醒来的意思不符。"}, {"text": "我整晚没睡，一直醒来到天亮。", "explanation": "这里应该用〈清醒〉。醒来是一次性的动作，不能表示一直保持清醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "醒来", "is_correct": true, "explanation": "正确。醒来指睡后醒过来，与“今早很晚才”的语境相符。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜指夜里不睡，与“今早”的时间矛盾。"}, {"text": "吃晚饭", "is_correct": false, "explanation": "语义：晚饭在晚上吃，与“今早”的时间矛盾。"}, {"text": "上晚自习", "is_correct": false, "explanation": "语义：晚自习在晚上进行，不会发生在“今早”。"}], "explanations": {"醒来": "正确。醒来指睡后醒过来，与“今早很晚才”的语境相符。", "熬夜": "语义：熬夜指夜里不睡，与“今早”的时间矛盾。", "吃晚饭": "语义：晚饭在晚上吃，与“今早”的时间矛盾。", "上晚自习": "语义：晚自习在晚上进行，不会发生在“今早”。"}, "sentence_index": 6, "correct_answer": "醒来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他醒来了弟弟，两个人一起去上学。", "explanation": "这里应该用〈叫醒〉。醒来是不及物动词，不能带宾语表示使别人醒过来，应说叫醒。"}, {"text": "我醒来后一直沉睡，没有睁开眼睛。", "explanation": "这里的〈醒来〉被用成了“仍未醒过来”的意思。醒来表示已经醒过来、睁开眼睛，句中却说没有睁开眼睛，前后矛盾。"}, {"text": "他醒来后一直睡着，还在打呼噜。", "explanation": "这里的〈醒来〉被用成了“醒后仍在睡”的意思。醒来表示已经醒过来，句中又说一直在睡，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我醒来了时，天已经亮了。", "corrected_sentence": "我醒来时，天已经亮了。", "error_description": "错误：“醒来了时”。正确：“醒来时”。“了”不能夹在动词“醒来”和时间词“时”之间，应直接说“醒来时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被醒来后，先喝了一杯水。", "corrected_sentence": "她醒来后，先喝了一杯水。", "error_description": "错误：“被醒来后”。正确：“醒来后”。“醒来”是不及物动词，不能用“被”字句表示被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
