INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93351, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "保护人是照顾你、不让你受伤的人。", "primary_collocate": null, "pronunciation": "bǎo hù rén", "ipa": "pau˨˩˦ xu˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "在我心里，爸爸是我的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把主人当成自己的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥总是我的保护人，没人敢欺负我。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是我的保护人，我什么都不怕。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想做妹妹的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学校里，大个子同学成了我的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候，外婆就是我的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友说：“你就是我的保护人。”", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有你这个保护人，我很放心。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子遇到危险，会去找保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "保護人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常生活中照顾自己、不让自己受伤害的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护人", "is_correct": true, "explanation": "正确答案：「在我心里，爸爸是我的保护人」中的保护人指日常生活中照顾自己、不让自己受伤的人。"}, {"text": "同桌", "is_correct": false, "explanation": "语义：同桌是同一张桌子上学习的同学，爸爸不可能是同桌，与句子语境不符。"}, {"text": "同学", "is_correct": false, "explanation": "语义：父亲不是同学，「爸爸是我的同学」与语境矛盾。"}, {"text": "主人", "is_correct": false, "explanation": "搭配：「主人」不用于父亲等亲属，说「爸爸是我的主人」不符合习惯。"}], "explanations": {"保护人": "正确答案：「在我心里，爸爸是我的保护人」中的保护人指日常生活中照顾自己、不让自己受伤的人。", "同桌": "语义：同桌是同一张桌子上学习的同学，爸爸不可能是同桌，与句子语境不符。", "同学": "语义：父亲不是同学，「爸爸是我的同学」与语境矛盾。", "主人": "搭配：「主人」不用于父亲等亲属，说「爸爸是我的主人」不符合习惯。"}, "sentence_index": 0, "correct_answer": "保护人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈请了一个保护人来做饭，洗衣服。", "explanation": "这里应该用〈保姆〉。保护人指照顾、保护自己的人，做饭、做家务的要说保姆。"}, {"text": "我的哥哥是一棵保护人。", "explanation": "这里应该用〈位〉。保护人指人，「棵」用于植物，不用于人。"}, {"text": "保护人每天在公司里管理员工和业务。", "explanation": "这里应该用〈老板〉。保护人指照顾你、不让你受伤的人，管理员工、经营公司的要说老板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护人", "is_correct": true, "explanation": "正确答案：「我小时候，外婆就是我的保护人」中的保护人指日常照顾自己的人。"}, {"text": "同事", "is_correct": false, "explanation": "语义：同事是同单位工作的人，外婆不可能是我的同事。"}, {"text": "房东", "is_correct": false, "explanation": "语义：房东指出租房屋的人，与家中长辈照顾孩子的语境不符。"}, {"text": "对象", "is_correct": false, "explanation": "搭配：「对象」多指恋爱中的一方，不用来指外婆。"}], "explanations": {"保护人": "正确答案：「我小时候，外婆就是我的保护人」中的保护人指日常照顾自己的人。", "同事": "语义：同事是同单位工作的人，外婆不可能是我的同事。", "房东": "语义：房东指出租房屋的人，与家中长辈照顾孩子的语境不符。", "对象": "搭配：「对象」多指恋爱中的一方，不用来指外婆。"}, "sentence_index": 6, "correct_answer": "保护人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "城门口站着一个保护人，专门盘查来往的人。", "explanation": "这里应该用〈守卫〉。保护人指照顾、不让人受伤的人，盘查来往人员的要说守卫。"}, {"text": "他是我的一支保护人。", "explanation": "这里应该用〈位〉。保护人指人，「支」用于杆状物或队伍，不用于人。"}, {"text": "每周六，保护人都会来我家教我数学。", "explanation": "这里应该用〈家教〉。保护人指照顾你、不让你受伤的人，上门辅导功课的要说家教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直是我保护人，陪我长大。", "corrected_sentence": "她一直是我的保护人，陪我长大。", "error_description": "结构助词错误：「我」和「保护人」之间要加「的」，说「我的保护人」，不说「我保护人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他就是帮过我的那棵保护人。", "corrected_sentence": "他就是帮过我的那位保护人。", "error_description": "量词错误：保护人指人，量词应用「位」，「棵」用于植物，不说「那棵保护人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
