INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93352, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责保护、监督或照料他人的人；监护人。", "primary_collocate": null, "pronunciation": "bǎo hù rén", "ipa": "pau˨˩˦ xu˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "孩子还小，他的保护人是奶奶。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的保护人要在表格上签字。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师打电话给小明的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不在时，叔叔是她的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请让保护人陪孩子来办手续。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十岁时，爷爷成了他的保护人。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要先问过保护人的意见。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有保护人的同意，孩子不能出国。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护人要照顾孩子，也要管好他的钱。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十八岁以后，就不需要保护人了。", "target_word": "保护人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "保護人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "法律或正式意义上负责照料、监督孩子等人的监护人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护人", "is_correct": true, "explanation": "正确答案：「孩子还小，他的保护人是奶奶」中的保护人指依法负责监护孩子的人。"}, {"text": "同事", "is_correct": false, "explanation": "语义：同事指同单位工作的人，与「孩子还小」的语境不符。"}, {"text": "老板", "is_correct": false, "explanation": "语义：孩子不会有老板，与「孩子还小」的语境矛盾。"}, {"text": "主人", "is_correct": false, "explanation": "搭配：「主人」多指物主或宠物的饲养者，不用来指监护孩子的人。"}], "explanations": {"保护人": "正确答案：「孩子还小，他的保护人是奶奶」中的保护人指依法负责监护孩子的人。", "同事": "语义：同事指同单位工作的人，与「孩子还小」的语境不符。", "老板": "语义：孩子不会有老板，与「孩子还小」的语境矛盾。", "主人": "搭配：「主人」多指物主或宠物的饲养者，不用来指监护孩子的人。"}, "sentence_index": 0, "correct_answer": "保护人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家请了一位保护人，专门做饭、打扫卫生。", "explanation": "这里应该用〈保姆〉。保护人指依法负责监护的人，做饭、打扫等家务要请保姆。"}, {"text": "我的表哥是一只保护人。", "explanation": "这里应该用〈位〉。保护人指人，计量人要用「位」，「只」多用于动物。"}, {"text": "人们在庙里向保护人祈祷，希望能保佑平安。", "explanation": "这里应该用〈保护神〉。保护人指负责监护、照料他人的人，庙里被祈求保佑的神要用保护神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护人", "is_correct": true, "explanation": "正确答案：「学校要先问过保护人的意见」中的保护人指负责监护孩子的人。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：学校不会去征求宠物的意见，与句子语境不符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本没有意见，学校不会去征求课本的意见，句子无法成立。"}, {"text": "情侣", "is_correct": false, "explanation": "语义：学校不会征求情侣的意见，这一搭配在语义上说不通。"}], "explanations": {"保护人": "正确答案：「学校要先问过保护人的意见」中的保护人指负责监护孩子的人。", "宠物": "语义：学校不会去征求宠物的意见，与句子语境不符。", "课本": "语义：课本没有意见，学校不会去征求课本的意见，句子无法成立。", "情侣": "语义：学校不会征求情侣的意见，这一搭配在语义上说不通。"}, "sentence_index": 6, "correct_answer": "保护人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛中，保护人一直站在场边，负责判罚犯规的球员。", "explanation": "这里应该用〈裁判〉。保护人指负责监护、照料他人的人，比赛中判罚犯规的要说裁判。"}, {"text": "他是我的一头保护人。", "explanation": "这里应该用〈位〉。保护人指人，计量人要用「位」，「头」多用于牲畜。"}, {"text": "这栋楼的保护人每晚都在门口巡逻。", "explanation": "这里应该用〈保安〉。保护人指负责监护的人，巡逻维持安全的要用保安。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她小时候有过一棵保护人。", "corrected_sentence": "她小时候有过一位保护人。", "error_description": "量词错误：保护人指人，量词应用「位」，「棵」用于植物，不说「一棵保护人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她父母不在，法院给她找了一保护人。", "corrected_sentence": "她父母不在，法院给她找了一位保护人。", "error_description": "量词缺失：「一」后面要加量词，应说「一位保护人」，不说「一保护人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
