INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93353, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "又细又长的一条东西。", "primary_collocate": null, "pronunciation": "cháng tiáo", "ipa": "ʈʂʰɑŋ˧˥ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他把纸剪成一个长条，像一根绳子。", "target_word": "长条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一个白色的长条，是什么？", "target_word": "长条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想要一个长条，不要圆的。", "target_word": "长条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用一个长条把头发扎起来。", "target_word": "长条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿来一个长条，量了量桌子的宽度。", "target_word": "长条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从包里拿出一个小长条。", "target_word": "长条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外挂着一个红色的长条。", "target_word": "长条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面包是长条，不是圆的。", "target_word": "长条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长条放在盒子里，很容易找到。", "target_word": "长条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个长条。", "target_word": "长条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "長條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又细又长的一条东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5820b4e1-82a5-40c0-ae4a-682d87027408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93353, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长条", "is_correct": true, "explanation": "正确。长条指又细又长的一条东西，与“又细又长”相符。"}, {"text": "圆球", "is_correct": false, "explanation": "体貌：圆球是圆形立体，不可能又细又长。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是一条细长的东西，与“像一根绳子”矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“这个”不能修饰空气这样的不可数物质。"}], "explanations": {"长条": "正确。长条指又细又长的一条东西，与“又细又长”相符。", "圆球": "体貌：圆球是圆形立体，不可能又细又长。", "天空": "语义：天空不是一条细长的东西，与“像一根绳子”矛盾。", "空气": "搭配：“这个”不能修饰空气这样的不可数物质。"}, "sentence_index": 0, "correct_answer": "长条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个长条是圆的，像一个球。", "explanation": "体貌：长条指又细又长的东西，不能指团块状的东西；这句却把它当成了团块。"}, {"text": "他买了一只长条。", "explanation": "量词：细长之物不用“只”计数，应说“一根长条”。"}, {"text": "他把长条喝了一口。", "explanation": "搭配：“喝”的对象应是液体，长条不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长条", "is_correct": true, "explanation": "正确。窗外可以挂着一个细长的红色条状物。"}, {"text": "石块", "is_correct": false, "explanation": "语义：石块重而硬，不能像这样挂在窗外。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“挂”不能与“声音”搭配。"}, {"text": "高山", "is_correct": false, "explanation": "体貌：高山体积巨大，无法挂在窗外。"}], "explanations": {"长条": "正确。窗外可以挂着一个细长的红色条状物。", "石块": "语义：石块重而硬，不能像这样挂在窗外。", "声音": "搭配：“挂”不能与“声音”搭配。", "高山": "体貌：高山体积巨大，无法挂在窗外。"}, "sentence_index": 6, "correct_answer": "长条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让长条跑起来。", "explanation": "配价：“让”后要接能够施动的对象，长条是无生命的东西，不能跑。"}, {"text": "老师中午吃了一只长条。", "explanation": "量词：细长之物不用“只”计数，应说“一根长条”。"}, {"text": "老师的长条是一位数学家。", "explanation": "语义：长条指又细又长的东西，不能指人；这句把它当成了人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只长条又细又长。", "corrected_sentence": "这根长条又细又长。", "error_description": "错误：“长条”前的量词用了“只”。“只”用于动物或成对之物，细长之物应用“根”；应说“这根长条又细又长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师用粉笔画了一只长条。", "corrected_sentence": "老师用粉笔画了一根长条。", "error_description": "错误：“长条”前的量词用了“只”。“只”用于动物或成对之物，细长之物应用“根”；应说“老师用粉笔画了一根长条。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
