INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93355, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出门是从家里走出去，到外面去。", "primary_collocate": null, "pronunciation": "chū mén", "ipa": "ʈʂʰu˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "早上我八点出门，九点到公司。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，出门别忘了带伞。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚出门，手机就响了。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷了，我不想出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出门前把灯关了。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你出门的时候，请把门关好。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天出门都带着书。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还没穿好鞋，不能出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一出门，就看见下雪了。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天早点儿出门，别迟到。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了门", "label": "体标"}, {"form": "出过门", "label": "体标"}, {"form": "出门去", "label": "趋向"}], "register": "口语", "sense_fingerprint": "从家里走出去到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出门", "is_correct": true, "explanation": "出门：离开家到外面去，与「九点到公司」前后呼应。"}, {"text": "下班", "is_correct": false, "explanation": "语义：“下班”指结束工作，“八点下班”与“九点到公司”矛盾。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”指学校课程结束，与“九点到公司”不符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休后不再到公司，与“九点到公司”矛盾。"}], "explanations": {"出门": "出门：离开家到外面去，与「九点到公司」前后呼应。", "下班": "语义：“下班”指结束工作，“八点下班”与“九点到公司”矛盾。", "下课": "语义：“下课”指学校课程结束，与“九点到公司”不符。", "退休": "语义：退休后不再到公司，与“九点到公司”矛盾。"}, "sentence_index": 0, "correct_answer": "出门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份包裹刚出门，就被退回来了。", "explanation": "这里应该用〈寄出〉。出门指人离开家到外面去，包裹寄出要用“寄出”，不能用“出门”。"}, {"text": "他一出门就脱下外套，换上拖鞋。", "explanation": "这里应该用〈进门〉。出门是离开家到外面去，脱外套、换拖鞋是进门之后的动作。"}, {"text": "这碗汤刚出门，就凉了。", "explanation": "这里应该用〈端出来〉。出门指人离开家到外面去，汤端出来要用“端出来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出门", "is_correct": true, "explanation": "出门：离开家到外面去，与「每天都带着书」搭配。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡时不能带着书，与「带着书」矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳时不能带着书下水，与「带着书」矛盾。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”指争吵，与“每天都带着书”不搭。"}], "explanations": {"出门": "出门：离开家到外面去，与「每天都带着书」搭配。", "洗澡": "语义：洗澡时不能带着书，与「带着书」矛盾。", "游泳": "语义：游泳时不能带着书下水，与「带着书」矛盾。", "吵架": "语义：“吵架”指争吵，与“每天都带着书”不搭。"}, "sentence_index": 6, "correct_answer": "出门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一出门就脱鞋上床睡觉了。", "explanation": "这里应该用〈进门〉。出门是离开家到外面去，脱鞋上床是进门之后的事。"}, {"text": "孩子放学就出门，躺在床上睡觉。", "explanation": "这里应该用〈在家〉。出门是离开家，躺在床上睡觉应在家里，要说“在家”。"}, {"text": "他今天一直出门，在屋里看书。", "explanation": "这里应该用〈在家〉。出门是离开家，在屋里看书要说“在家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他了出门，去超市买东西。", "corrected_sentence": "他出了门，去超市买东西。", "error_description": "错误在于“了”的位置。应说“出了门”，“了”放在动词“出”之后、宾语“门”之前；放在“出”之前是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天出门得很早。", "corrected_sentence": "我今天出门出得很早。", "error_description": "错误：“出门得很早”。“出门”是离合词，后面带“得”时要重复动词“出”，说成“出门出得很早”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
