INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开家到外面去；外出。", "primary_collocate": null, "pronunciation": "chū mén", "ipa": "ʈʂʰu˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶年纪大了，很少出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常在家，不太爱出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出门去买菜了，一会儿就回来。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出门工作，晚上才回家。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很怕冷，冬天几乎不出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪的时候，大家都不出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每次出门都要带很多东西。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张昨天出门办事，还没回来。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪路滑，出门要小心。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王今天不在，他出门了。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了门", "label": "体标"}, {"form": "出过门", "label": "体标"}, {"form": "出门去", "label": "趋向"}], "register": "口语", "sense_fingerprint": "离开家到外面去，外出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出门", "is_correct": true, "explanation": "出门：离开家到外面去，与「很少」搭配，表示少外出。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”与“奶奶年纪大了”不符，奶奶不需要上学。"}, {"text": "当兵", "is_correct": false, "explanation": "语义：“当兵”与奶奶的身份不符，句子语义不通。"}, {"text": "罢工", "is_correct": false, "explanation": "搭配：“罢工”的主语应是工作的人，不能用于“奶奶”。"}], "explanations": {"出门": "出门：离开家到外面去，与「很少」搭配，表示少外出。", "上学": "语义：“上学”与“奶奶年纪大了”不符，奶奶不需要上学。", "当兵": "语义：“当兵”与奶奶的身份不符，句子语义不通。", "罢工": "搭配：“罢工”的主语应是工作的人，不能用于“奶奶”。"}, "sentence_index": 0, "correct_answer": "出门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份包裹刚出门，就被退回来了。", "explanation": "这里应该用〈寄出〉。出门指人离开家到外面去，包裹寄出要用“寄出”，不能用“出门”。"}, {"text": "我下班后刚出门，妈妈就做好了饭。", "explanation": "这里应该用〈进门〉。出门是离开家，下班回家要用“进门”。"}, {"text": "这碗汤刚出门，就凉了。", "explanation": "这里应该用〈端出来〉。出门指人离开家到外面去，汤端出来要用“端出来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出门", "is_correct": true, "explanation": "出门：离开家到外面去，与「每次都要带很多东西」搭配。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”不是需要外出带很多东西的活动，与句意矛盾。"}, {"text": "做梦", "is_correct": false, "explanation": "语义：做梦时不需要带很多东西，与句意矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时不需要带很多东西，与句意矛盾。"}], "explanations": {"出门": "出门：离开家到外面去，与「每次都要带很多东西」搭配。", "发烧": "语义：“发烧”不是需要外出带很多东西的活动，与句意矛盾。", "做梦": "语义：做梦时不需要带很多东西，与句意矛盾。", "睡觉": "语义：睡觉时不需要带很多东西，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "出门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一出门就脱鞋上床睡觉了。", "explanation": "这里应该用〈进门〉。出门是离开家到外面去，脱鞋上床是进门之后的事。"}, {"text": "孩子放学就出门，躺在床上睡觉。", "explanation": "这里应该用〈在家〉。出门是离开家，躺在床上睡觉应在家里，要说“在家”。"}, {"text": "他今天一直出门，在屋里看书。", "explanation": "这里应该用〈在家〉。出门是离开家，在屋里看书要说“在家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天没出门了。", "corrected_sentence": "他昨天没出门。", "error_description": "错误：“没出门了”。用“没”否定已经发生的事时，句尾不能再加“了”；正确：“没出门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出门了去，没有带钥匙。", "corrected_sentence": "他出门去了，没有带钥匙。", "error_description": "错误在于“了”与趋向补语“去”的顺序。应说“出门去了”，“去”紧接“出门”，“了”放在最后；“出门了去”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
