INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93357, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闪是一下子亮一下，又不见了。", "primary_collocate": null, "pronunciation": "shǎn", "ipa": "ʂan˨˩˦", "syllable_count": 1, "sentences": [{"text": "天上的星星一闪一闪的。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕闪了一下，又黑了。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的灯塔一直在闪。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑夜里，我看见窗外有一道光闪了一下。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯在闪，请你们先别过马路。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路口的黄灯闪着，车都慢了下来。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "萤火虫在草丛里一闪一闪地飞。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机灯一闪，我就知道有信息了。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才天上好像有什么东西闪了一下。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑上的小灯一直闪，大概是没电了。", "target_word": "闪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闪了", "label": "体标"}, {"form": "闪着", "label": "体标"}, {"form": "闪过", "label": "体标"}, {"form": "閃", "label": "繁体"}], "register": "通用", "sense_fingerprint": "闪：光一下子亮起又不见了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5820b4e1-82a5-40c0-ae4a-682d87027408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93357, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "闪", "is_correct": true, "explanation": "正确。闪（shǎn）意思是光一下子亮起又不见了。"}, {"text": "山", "is_correct": false, "explanation": "山（shān，第一声）与闪（shǎn，第三声）声调不同，意思是山。"}, {"text": "扇", "is_correct": false, "explanation": "扇（shàn，第四声）与闪（shǎn，第三声）声调不同，意思是扇子。"}, {"text": "赏", "is_correct": false, "explanation": "赏（shǎng）与闪（shǎn）韵母不同，意思是欣赏或奖赏。"}, {"text": "伞", "is_correct": false, "explanation": "伞（sǎn）与闪（shǎn）声母不同，意思是雨伞。"}, {"text": "产", "is_correct": false, "explanation": "产（chǎn）与闪（shǎn）声母不同，意思是生产。"}], "explanations": {"闪": "正确。闪（shǎn）意思是光一下子亮起又不见了。", "山": "山（shān，第一声）与闪（shǎn，第三声）声调不同，意思是山。", "扇": "扇（shàn，第四声）与闪（shǎn，第三声）声调不同，意思是扇子。", "赏": "赏（shǎng）与闪（shǎn）韵母不同，意思是欣赏或奖赏。", "伞": "伞（sǎn）与闪（shǎn）声母不同，意思是雨伞。", "产": "产（chǎn）与闪（shǎn）声母不同，意思是生产。"}, "sentence_index": null, "correct_answer": "闪"}, "level_3": {"options": [{"text": "闪", "is_correct": true, "explanation": "正确。“一闪一闪的”描述星光忽明忽暗，正是闪的意思。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，无法描述星光的明暗变化。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不用于形容星星发光的样子。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”与星光无关，无法表示闪烁。"}], "explanations": {"闪": "正确。“一闪一闪的”描述星光忽明忽暗，正是闪的意思。", "吃": "语义：“吃”指进食，无法描述星光的明暗变化。", "唱": "搭配：“唱”不用于形容星星发光的样子。", "咬": "语义：“咬”与星光无关，无法表示闪烁。"}, "sentence_index": 0, "correct_answer": "闪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他闪了闪书包。", "explanation": "这里应该用〈背〉。闪不能描述背书包的动作。"}, {"text": "雪花闪下来了。", "explanation": "这里应该用〈飘〉。闪不用于雪花飘落。"}, {"text": "炊烟闪上了天空。", "explanation": "这里应该用〈升〉。闪不用于炊烟升起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93357, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "闪", "is_correct": true, "explanation": "正确。闪（shǎn）意思是光一下子亮起又不见了。"}, {"text": "删", "is_correct": false, "explanation": "删（shān，第一声）与闪（shǎn，第三声）声调不同，意思是删除。"}, {"text": "善", "is_correct": false, "explanation": "善（shàn，第四声）与闪（shǎn，第三声）声调不同，意思是善良。"}, {"text": "铲", "is_correct": false, "explanation": "铲（chǎn）与闪（shǎn）声母不同，意思是铲子。"}, {"text": "伞", "is_correct": false, "explanation": "伞（sǎn）与闪（shǎn）声母不同，意思是雨伞。"}], "explanations": {"闪": "正确。闪（shǎn）意思是光一下子亮起又不见了。", "删": "删（shān，第一声）与闪（shǎn，第三声）声调不同，意思是删除。", "善": "善（shàn，第四声）与闪（shǎn，第三声）声调不同，意思是善良。", "铲": "铲（chǎn）与闪（shǎn）声母不同，意思是铲子。", "伞": "伞（sǎn）与闪（shǎn）声母不同，意思是雨伞。"}, "sentence_index": null, "correct_answer": "闪"}, "level_3": {"options": [{"text": "闪", "is_correct": true, "explanation": "正确。“一闪一闪地飞”描述萤火虫的光忽明忽暗，正是闪的意思。"}, {"text": "数", "is_correct": false, "explanation": "搭配：“数”一般带数量或对象，不与“一……一……地飞”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”与飞行无关，无法描述萤火虫的光亮。"}, {"text": "扛", "is_correct": false, "explanation": "配价：“扛”需要带受事宾语，后面不能直接接“地飞”。"}], "explanations": {"闪": "正确。“一闪一闪地飞”描述萤火虫的光忽明忽暗，正是闪的意思。", "数": "搭配：“数”一般带数量或对象，不与“一……一……地飞”搭配。", "洗": "语义：“洗”与飞行无关，无法描述萤火虫的光亮。", "扛": "配价：“扛”需要带受事宾语，后面不能直接接“地飞”。"}, "sentence_index": 6, "correct_answer": "闪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨闪了。", "explanation": "这里应该用〈停〉。闪不用于雨停止。"}, {"text": "学生们闪了一首歌。", "explanation": "这里应该用〈唱〉。闪不能表示唱歌。"}, {"text": "门闪了。", "explanation": "这里应该用〈开〉。闪不能描述门的开合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盏小灯闪了三个就灭了。", "corrected_sentence": "这盏小灯闪了三下就灭了。", "error_description": "错误：“闪了三个”，表示动作次数应用动量词“下”，不能用“个”。正确：“闪了三下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那台电视机的画面闪得一下。", "corrected_sentence": "那台电视机的画面闪了一下。", "error_description": "错误：“闪得一下”，动量补语前的助词应为“了”，“得”用于程度补语，不能用于动量。正确：“闪了一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "正确：“关闭”与“开办”相对，指停止营业或使店铺、学校停止运作。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”是文娱活动，与“开办”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”指进食，与创立机构没有反义关系。"}, {"text": "看书", "is_correct": false, "explanation": "无关：“看书”指阅读，与“开办”不构成反义。"}], "correct_answer": "关闭", "explanations": {"关闭": "正确：“关闭”与“开办”相对，指停止营业或使店铺、学校停止运作。", "跳舞": "无关：“跳舞”是文娱活动，与“开办”没有反义关系。", "吃饭": "无关：“吃饭”指进食，与创立机构没有反义关系。", "看书": "无关：“看书”指阅读，与“开办”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "正确：“关闭”与“开办”相对，指停止营业或使店铺停止运作。"}, {"text": "钓鱼", "is_correct": false, "explanation": "无关：“钓鱼”是休闲活动，与“开办”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清除污物，与创立机构没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "无关：“洗澡”指清洁身体，与“开办”不构成反义。"}], "correct_answer": "关闭", "explanations": {"关闭": "正确：“关闭”与“开办”相对，指停止营业或使店铺停止运作。", "钓鱼": "无关：“钓鱼”是休闲活动，与“开办”没有反义关系。", "打扫": "无关：“打扫”指清除污物，与创立机构没有反义关系。", "洗澡": "无关：“洗澡”指清洁身体，与“开办”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开办是新开一家学校或店，让它开始做事。", "primary_collocate": null, "pronunciation": "kāi bàn", "ipa": "kʰaɪ˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "我姐姐想开办一家花店。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店是去年开办的。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开办了一所幼儿园。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学校下个月就要开办了。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开办一家小店不太容易。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人开办过一家面包店。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的饭店刚开办，客人还不多。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用存款开办了一家咖啡店。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李先生在城里开办一所音乐学校。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把开办小店的想法告诉了妈妈。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开办了", "label": "体标"}, {"form": "开办过", "label": "体标"}, {"form": "開辦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "新开学校或店铺并使其开始运作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b5a7c1a-21c0-4822-b161-907b245b99f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开办", "is_correct": true, "explanation": "正确：“开办”指新开店铺并使其开始运作，与“我姐姐想……一家花店”吻合。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”指采下果实或花朵，不能用于开店，句子不通。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”的对象是动植物，不能说养一家花店。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹饪，不能用于开一家店，句子语义不通。"}], "explanations": {"开办": "正确：“开办”指新开店铺并使其开始运作，与“我姐姐想……一家花店”吻合。", "摘": "语义：“摘”指采下果实或花朵，不能用于开店，句子不通。", "养": "搭配：“养”的对象是动植物，不能说养一家花店。", "煮": "语义：“煮”指烹饪，不能用于开一家店，句子语义不通。"}, "sentence_index": 0, "correct_answer": "开办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府开办了一个新基金。", "explanation": "这里应该用〈设立〉。开办指创办学校、店铺等机构，基金要用〈设立〉。"}, {"text": "我们开办了一次郊游。", "explanation": "这里应该用〈组织〉。开办用于创办机构，活动要用〈组织〉。"}, {"text": "剧组开办了一部电影。", "explanation": "这里应该用〈拍摄〉。开办用于创办机构，影片要用〈拍摄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开办", "is_correct": true, "explanation": "正确：“开办”指饭店刚刚开始经营，与“我们的饭店刚……，客人还不多”吻合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于饭店的经营状态，句子不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要带宾语，“刚送”后缺少对象，句子不完整。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲”指说话，饭店不能“讲”，句子语义不通。"}], "explanations": {"开办": "正确：“开办”指饭店刚刚开始经营，与“我们的饭店刚……，客人还不多”吻合。", "吃": "语义：“吃”指进食，不能用于饭店的经营状态，句子不通。", "送": "配价：“送”需要带宾语，“刚送”后缺少对象，句子不完整。", "讲": "语义：“讲”指说话，饭店不能“讲”，句子语义不通。"}, "sentence_index": 6, "correct_answer": "开办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生开办了电灯。", "explanation": "这里应该用〈发明〉。开办用于创办机构，电灯要用〈发明〉。"}, {"text": "这家出版社开办了很多书。", "explanation": "这里应该用〈出版〉。开办用于创办机构，书籍要用〈出版〉。"}, {"text": "农民开办了很多蔬菜。", "explanation": "这里应该用〈种植〉。开办用于创办机构，蔬菜要用〈种植〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹想把开办一家面馆。", "corrected_sentence": "我妹妹想开办一家面馆。", "error_description": "“把”字误用。“想”后直接接动词“开办”，不需要“把”，应删去“把”，改为“想开办一家面馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅在镇上开办了一只超市。", "corrected_sentence": "我舅舅在镇上开办了一家超市。", "error_description": "量词误用。超市应用量词“家”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
