INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强制手段惩罚违反规定或法律的人或国家。", "primary_collocate": null, "pronunciation": "zhì cái", "ipa": "ʈʂɻ̩⁵¹ tsʰaɪ̯³⁵", "syllable_count": 2, "sentences": [{"text": "联合国决定制裁违反协议的国家。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家一起制裁了那个破坏和平的国家。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司违反法律，受到了严厉的制裁。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定制裁污染河水的工厂。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他违反了比赛规定，协会会制裁他。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际社会曾经制裁过这个国家。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律要制裁每一个违法的人。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违反规定的球队，联盟一定会制裁。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国关系紧张，其中一国宣布制裁对方。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际足联制裁了作弊的球队。", "target_word": "制裁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制裁了", "label": "体标（了）"}, {"form": "制裁过", "label": "体标（过）"}, {"form": "经济制裁", "label": "复合"}], "register": "正式", "sense_fingerprint": "以强制手段惩罚违反规定或法律的人或国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制裁", "is_correct": true, "explanation": "制裁：用强制手段惩罚违反协议的国家，符合句意。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞好的行为，与违反协议的国家不相容。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是给予好处，句中对象是违反协议的国家，意思正相反。"}, {"text": "逮捕", "is_correct": false, "explanation": "配价：“逮捕”的对象应是人，不能用于国家。"}], "explanations": {"制裁": "制裁：用强制手段惩罚违反协议的国家，符合句意。", "表扬": "语义：“表扬”是称赞好的行为，与违反协议的国家不相容。", "奖励": "语义：“奖励”是给予好处，句中对象是违反协议的国家，意思正相反。", "逮捕": "配价：“逮捕”的对象应是人，不能用于国家。"}, "sentence_index": 0, "correct_answer": "制裁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师决定制裁每天按时交作业的学生。", "explanation": "这里应该用〈表扬〉。制裁是惩罚违反规定的人，用于按时交作业的学生，意思正相反。"}, {"text": "这种药能制裁细菌。", "explanation": "这里应该用〈消灭〉。制裁的对象是违反规定或法律的人或国家，不能用于细菌。"}, {"text": "妈妈制裁了考试得满分的我。", "explanation": "这里应该用〈表扬〉。制裁是惩罚，用在考试得满分的孩子身上，与语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制裁", "is_correct": true, "explanation": "制裁：用强制手段惩罚违反法律的人，符合句意。"}, {"text": "包庇", "is_correct": false, "explanation": "语义：“包庇”是袒护坏人，与“法律要……违法的人”的意思相反。"}, {"text": "纵容", "is_correct": false, "explanation": "语义：“纵容”是放任坏行为，法律不会去纵容违法者。"}, {"text": "赦免", "is_correct": false, "explanation": "搭配：“赦免”多由元首或当局对已定罪者施行，与“法律要”的主语和对象都不搭。"}], "explanations": {"制裁": "制裁：用强制手段惩罚违反法律的人，符合句意。", "包庇": "语义：“包庇”是袒护坏人，与“法律要……违法的人”的意思相反。", "纵容": "语义：“纵容”是放任坏行为，法律不会去纵容违法者。", "赦免": "搭配：“赦免”多由元首或当局对已定罪者施行，与“法律要”的主语和对象都不搭。"}, "sentence_index": 6, "correct_answer": "制裁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国际足联制裁了受伤的球员。", "explanation": "这里应该用〈慰问〉。制裁只针对违反规定的人，受伤的球员没有违规，不能用制裁。"}, {"text": "裁判制裁了这个进球。", "explanation": "这里应该用〈取消〉。制裁是对违规的人或国家的惩罚，不能用于进球；裁判判定进球无效应说〈取消〉。"}, {"text": "这位医生制裁了那个感冒的病人。", "explanation": "这里应该用〈治疗〉。制裁是对违规者的强制惩罚，感冒的病人没有违规，医生对病人应说〈治疗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "联合国明天会制裁过那个国家。", "corrected_sentence": "联合国明天会制裁那个国家。", "error_description": "“过”表示已经发生过的经历，句中“明天会”指将来，不能用“过”；应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国际足联决定制裁给作弊的球队。", "corrected_sentence": "国际足联决定制裁作弊的球队。", "error_description": "“制裁”后面不能直接接“给”，“给”使句子不通；应去掉“给”，改为“国际足联决定制裁作弊的球队。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
