INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在此以前；先前。多用于书面语。", "primary_collocate": null, "pronunciation": "qián cǐ", "ipa": "tɕʰjɛn˧˥ tsʰɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "前此他从未来过这个城市。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此我们没有见过面。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此公司没有这样的规定。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此他一直住在乡下，去年才搬到北京。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此大家都不知道这件事。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此这里没有医院，现在有了。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此她很少说话，今天却说了很多。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此我对音乐没有兴趣。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此他从没迟到，这次是第一次。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此学校没有游泳池，同学们只能去外面游泳。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面语副词，在此以前、先前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4240d01-219b-4bd2-9ad0-703dd789f62b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED