rrors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前此", "is_correct": true, "explanation": "正确。前此表示在此以前，与“今天却说了很多”形成对比。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生不久，与“很少说话”所描述的长期习惯不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“很少说话”所说的一贯状态不合。"}, {"text": "压根", "is_correct": false, "explanation": "搭配：“压根”要与否定词连用，不能修饰“很少说话”。"}], "explanations": {"前此": "正确。前此表示在此以前，与“今天却说了很多”形成对比。", "刚刚": "语义：“刚刚”指刚发生不久，与“很少说话”所描述的长期习惯不合。", "立刻": "语义：“立刻”表示马上发生，与“很少说话”所说的一贯状态不合。", "压根": "搭配：“压根”要与否定词连用，不能修饰“很少说话”。"}, "sentence_index": 6, "correct_answer": "前此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前此他再也没有来过这个城市。", "explanation": "这里应该用〈此后〉。前此指在此之前，与“再也没有来过”所说的此后情况矛盾。"}, {"text": "前此我们明天去爬山。", "explanation": "这里应该用〈以后〉。前此指此前的时间，不能与“明天去爬山”这样的将来安排搭配。"}, {"text": "我们先吃饭，前此去公园。", "explanation": "这里应该用〈然后〉。前此指在此之前，而句子说的是吃饭之后去公园，顺序颠倒了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的前此没有听说过这件事。", "corrected_sentence": "他前此没有听说过这件事。", "error_description": "“前此”是副词，前面不能加“的”。“的”应去掉，说“他前此没有听说过这件事。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的前此很少在周末出门。", "corrected_sentence": "我们前此很少在周末出门。", "error_description": "“前此”是副词，前面不能加“的”。“的”应去掉，说“我们前此很少在周末出门。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "劳动力是能干活的人，有力气去做事的人。", "primary_collocate": null, "pronunciation": "láo dòng lì", "ipa": "lɑʊ˧˥ tʊŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "这家工厂需要很多劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的年轻劳动力都去城里工作了。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方缺少劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算招一些劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村里的劳动力不多。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多劳动力从农村来到大城市。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天农忙时，家里需要更多劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有很多年轻的劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板雇了十个劳动力来搬东西。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳动力少，工作就做得慢。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "劳动力：能干活的人，指人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6126fc-082d-4972-80f0-b37b1dacae83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诗人", "is_correct": false, "explanation": "语义：工厂需要的是能干活的人手，不需要很多诗人，与“工厂”的语境不合。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指能干活的人，工厂需要很多这样的人手，语义吻合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“花朵”是植物的花，工厂不需要很多花朵，与语境不符。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“需要很多”后面的宾语应是可被需要的人或物，“季节”不能这样使用。"}], "explanations": {"诗人": "语义：工厂需要的是能干活的人手，不需要很多诗人，与“工厂”的语境不合。", "劳动力": "劳动力指能干活的人，工厂需要很多这样的人手，语义吻合。", "花朵": "语义：“花朵”是植物的花，工厂不需要很多花朵，与语境不符。", "季节": "搭配：“需要很多”后面的宾语应是可被需要的人或物，“季节”不能这样使用。"}, "sentence_index": 0, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位劳动力长得很漂亮。", "explanation": "这里应该用〈工人〉。“劳动力”指能干活的人或其劳动能力，不用来形容人的长相，说人漂亮时不用它。"}, {"text": "他是我的劳动力，我很爱他。", "explanation": "这里应该用〈亲人〉。“劳动力”指能干活的人或其劳动能力，不指家人，也不用来表达亲情。"}, {"text": "公司打算招一只劳动力。", "explanation": "这里的量词应改用〈名〉。“只”用于动物或成对器官中的一个，不用于指人的劳动力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节日", "is_correct": false, "explanation": "搭配：“需要更多”的对象应是人手或物资，“节日”在农忙语境中不能这样使用。"}, {"text": "真理", "is_correct": false, "explanation": "语义：农忙时家里缺的是干活的人，“真理”与农活无关。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指能干活的人，农忙时家里需要的正是这种人手，语义通顺。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”是天体，农忙时家里并不需要它们，与语境不符。"}], "explanations": {"节日": "搭配：“需要更多”的对象应是人手或物资，“节日”在农忙语境中不能这样使用。", "真理": "语义：农忙时家里缺的是干活的人，“真理”与农活无关。", "劳动力": "劳动力指能干活的人，农忙时家里需要的正是这种人手，语义通顺。", "星星": "语义：“星星”是天体，农忙时家里并不需要它们，与语境不符。"}, "sentence_index": 6, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "劳动力坏了，生产就停了。", "explanation": "这里应该用〈机器〉。“劳动力”指人，不能说“坏了”，会出故障的是机器。"}, {"text": "他是劳动力，唱得很好听。", "explanation": "这里应该用〈歌手〉。“劳动力”指能干活的人或其劳动能力，不指会唱歌的人。"}, {"text": "工厂今年招了一台劳动力。", "explanation": "这里应该用〈名〉或〈个〉。“台”用于机器等器械，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂今年要增加一根劳动力。", "corrected_sentence": "这家工厂今年要增加一批劳动力。", "error_description": "量词错误：“劳动力”（指人）前应用〈一批〉，“根”用于细长的东西，不能修饰劳动力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城里来了一把劳动力。", "corrected_sentence": "城里来了一批劳动力。", "error_description": "量词错误：“劳动力”（指人）前应用〈一批〉，“把”用于有柄的器具，不能修饰人员。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人所具有的从事劳动的能力（指能力本身，不指人）。", "primary_collocate": null, "pronunciation": "láo dòng lì", "ipa": "lɑʊ˧˥ tʊŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "他生病以后，失去了劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，没有劳动力了。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人还有一点劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤后，他丧失了劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要还有劳动力，他就不会闲着。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场病让他部分丧失了劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手受伤了，暂时没有劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去劳动力的人可以得到帮助。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然很老，但是还有劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，有劳动力就要自己赚钱。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "劳动力：人所具有的劳动能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6126fc-082d-4972-80f0-b37b1dacae83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：名字是别人给的称呼，生病不会使人失去名字。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指人所具有的劳动能力，生病后失去它，语义通顺。"}, {"text": "皮肤", "is_correct": false, "explanation": "搭配：皮肤是身体的一部分，不能说“生病以后失去皮肤”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人身上的东西，生病不会使人失去天气。"}], "explanations": {"名字": "语义：名字是别人给的称呼，生病不会使人失去名字。", "劳动力": "劳动力指人所具有的劳动能力，生病后失去它，语义通顺。", "皮肤": "搭配：皮肤是身体的一部分，不能说“生病以后失去皮肤”。", "天气": "语义：天气不是人身上的东西，生病不会使人失去天气。"}, "sentence_index": 0, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的劳动力有五十公斤。", "explanation": "这里应该用〈体重〉。“劳动力”指能从事劳动的人或其劳动能力，不能用来说重量，说人的重量要用〈体重〉。"}, {"text": "他用劳动力推开了门。", "explanation": "这里应该用〈力气〉。“劳动力”指人的劳动能力或劳动人员，不能用来表示用身体的力量做动作，用力推门要说〈力气〉。"}, {"text": "他失去了一只劳动力。", "explanation": "这里应该用〈一部分〉。“只”用于动物或成对器官中的一个，不能修饰抽象的劳动能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": false, "explanation": "搭配：“没有”后接的应是可以缺少的人或物，“脚步”是动作，不能这样用。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指能干活的能力，手受伤后暂时没有它，语义吻合。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶与手受伤、干活的语境无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”是人本来就有的属性，不能用“没有”来表示暂时缺少。"}], "explanations": {"脚步": "搭配：“没有”后接的应是可以缺少的人或物，“脚步”是动作，不能这样用。", "劳动力": "劳动力指能干活的能力，手受伤后暂时没有它，语义吻合。", "树叶": "语义：树叶与手受伤、干活的语境无关。", "年龄": "搭配：“年龄”是人本来就有的属性，不能用“没有”来表示暂时缺少。"}, "sentence_index": 6, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的劳动力很好，很远的声音也听得清楚。", "explanation": "这里应该用〈听力〉。“劳动力”指人从事劳动的能力，不指耳朵听声音的能力。"}, {"text": "他的劳动力很差，看不清字。", "explanation": "这里应该用〈视力〉。“劳动力”指能从事体力劳动的能力，不用来说眼睛看东西的能力。"}, {"text": "他失去了一台劳动力。", "explanation": "这里应该用〈一部分〉。“台”用于机器等器械，不能修饰抽象的劳动能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "女儿病好以后，劳动力就恢复了一根。", "corrected_sentence": "女儿病好以后，劳动力就恢复了一部分。", "error_description": "量词错误：“劳动力”（能力义）前应用〈一部分〉，“根”用于细长的东西，不能修饰劳动能力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的手受伤以后，失去了一根劳动力。", "corrected_sentence": "他的手受伤以后，失去了一部分劳动力。", "error_description": "量词错误：“劳动力”前应用〈一部分〉，“根”用于细长的物体，不能修饰劳动能力。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
