INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93373, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回顾是回头想一想以前发生过的事。", "primary_collocate": null, "pronunciation": "huí gù", "ipa": "xweɪ˧˥ ku˥˩", "syllable_count": 2, "sentences": [{"text": "年底了，我们回顾一下今年的工作。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，我们回顾了三年的中学生活。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在窗边，回顾自己的大学生活。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起回顾了这次旅行。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，经理先回顾去年的成绩。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，我常常回顾一天发生的事。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回顾过去，她觉得很幸福。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回顾这几年，他觉得自己长大了。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶喜欢回顾年轻时的故事。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们回顾了十年前的那些往事，聊了很久。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回顾了", "label": "体标"}, {"form": "回顾过", "label": "体标"}, {"form": "回顾着", "label": "体标"}, {"form": "回顧", "label": "繁体"}], "register": "中性", "sense_fingerprint": "回头想以前发生过的事；总结过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93373, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回顾", "is_correct": true, "explanation": "正确。“回顾一下今年的工作”是回头想一想今年做过的工作，符合句意。"}, {"text": "预习", "is_correct": false, "explanation": "语义：“预习”指上课前先看课本，不能用于工作。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是不及物动词，不能带“今年的工作”做宾语。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”用于食物或物件，不能说“烧今年的工作”。"}], "explanations": {"回顾": "正确。“回顾一下今年的工作”是回头想一想今年做过的工作，符合句意。", "预习": "语义：“预习”指上课前先看课本，不能用于工作。", "散步": "搭配：“散步”是不及物动词，不能带“今年的工作”做宾语。", "烧": "搭配：“烧”用于食物或物件，不能说“烧今年的工作”。"}, "sentence_index": 0, "correct_answer": "回顾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周末回顾了一个博物馆。", "explanation": "这里应该用〈参观〉。回顾指回想过去的事，不能用来说去看一个地方。"}, {"text": "工人回顾了这条电路。", "explanation": "这里应该用〈检查〉。回顾指回想过去发生的事，不能用于检查眼前的东西。"}, {"text": "我们回顾了这幅画。", "explanation": "这里应该用〈欣赏〉。回顾指回想过去的事，不能用于眼前正在看的画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93373, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回顾", "is_correct": true, "explanation": "正确。“回顾过去”是回想过去的事，符合句意。"}, {"text": "预言", "is_correct": false, "explanation": "语义：“预言”指预测将来，不能用于已经过去的事。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是新东西，不能说“发明过去”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于坏了的东西，不能说“修理过去”。"}], "explanations": {"回顾": "正确。“回顾过去”是回想过去的事，符合句意。", "预言": "语义：“预言”指预测将来，不能用于已经过去的事。", "发明": "搭配：“发明”的对象是新东西，不能说“发明过去”。", "修理": "搭配：“修理”用于坏了的东西，不能说“修理过去”。"}, "sentence_index": 6, "correct_answer": "回顾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家回顾了明年的经济走势。", "explanation": "这里应该用〈预测〉。回顾指回想过去的事，不能用于还没发生的事。"}, {"text": "我周末回顾了朋友的家。", "explanation": "这里应该用〈拜访〉。回顾指回想过去的事，不能用来说去看望人。"}, {"text": "电视台回顾了明晚的节目。", "explanation": "这里应该用〈预告〉。回顾指回想过去的事，不能用于还没播出的节目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93373, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我们回顾了一下今年的工作。", "corrected_sentence": "明天我们回顾一下今年的工作。", "error_description": "时态与体标错误：“明天”指将来，动作还没有发生，不能用“了”表示完成，应说“明天我们回顾一下今年的工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93373, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们回顾了过那次比赛的过程。", "corrected_sentence": "我们回顾过那次比赛的过程。", "error_description": "体标错误：“过”表示经历，不能和“了”同时用在“回顾”后面，应说“回顾过”，不说“回顾了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
