INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回过头来看；回想过去的经历或事情。", "primary_collocate": null, "pronunciation": "huí gù", "ipa": "xweɪ˧˥ ku˥˩", "syllable_count": 2, "sentences": [{"text": "他回顾自己走过的路，很感动。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书回顾了中国的历史。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回顾这一年，我学到了很多。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业时，同学们回顾了四年的生活。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览回顾了这座城市五十年的变化。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人回顾一生，觉得没有后悔的事。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回顾比赛，教练说我们还可以更好。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一篇文章回顾这次经历。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回顾昨天的会议，大家都觉得很有用。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回顾过去的错误，是为了以后做得更好。", "target_word": "回顾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回顾了", "label": "体标"}, {"form": "回顾过", "label": "体标"}, {"form": "回顾着", "label": "体标"}, {"form": "回顧", "label": "繁体"}], "register": "中性", "sense_fingerprint": "回过头来看；回想过去的经历", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回顾", "is_correct": true, "explanation": "正确。“回顾自己走过的路”是回想过去的经历，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是不及物动词，不能带“自己走过的路”做宾语。"}, {"text": "预言", "is_correct": false, "explanation": "语义：“预言”指预测将来，不能用于自己走过的路。"}, {"text": "预习", "is_correct": false, "explanation": "语义：“预习”指上课前先看书，与走过的路无关。"}], "explanations": {"回顾": "正确。“回顾自己走过的路”是回想过去的经历，符合句意。", "散步": "搭配：“散步”是不及物动词，不能带“自己走过的路”做宾语。", "预言": "语义：“预言”指预测将来，不能用于自己走过的路。", "预习": "语义：“预习”指上课前先看书，与走过的路无关。"}, "sentence_index": 0, "correct_answer": "回顾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议上，他回顾了公司的未来。", "explanation": "这里应该用〈展望〉。回顾指回想过去的经历，说未来要用展望。"}, {"text": "科学家回顾了这颗星星。", "explanation": "这里应该用〈观察〉。回顾指回想过去的经历，不能用于眼前正在观察的东西。"}, {"text": "工人回顾了这台机器。", "explanation": "这里应该用〈修理〉。回顾指回想过去的经历，不能用于正在修理的机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回顾", "is_correct": true, "explanation": "正确。“回顾比赛”是回想比赛的过程，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于坏了的东西，不能说“修理比赛”。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只用于食物，不能说“煮比赛”。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是夸奖人，不能用来说比赛，句意不通。"}], "explanations": {"回顾": "正确。“回顾比赛”是回想比赛的过程，符合句意。", "修理": "搭配：“修理”用于坏了的东西，不能说“修理比赛”。", "煮": "搭配：“煮”只用于食物，不能说“煮比赛”。", "表扬": "语义：“表扬”是夸奖人，不能用来说比赛，句意不通。"}, "sentence_index": 6, "correct_answer": "回顾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈回顾了一件新衣服。", "explanation": "这里应该用〈挑选〉。回顾指回想过去的经历，不能用来说在商店里选东西。"}, {"text": "气象台回顾了明天的天气。", "explanation": "这里应该用〈预报〉。回顾指回想过去的经历，不能用于对明天天气的预报。"}, {"text": "园丁回顾了那些花树。", "explanation": "这里应该用〈修剪〉。回顾指回想过去的经历，不能用于修剪眼前的花树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她回顾得自己写过的日记，觉得很亲切。", "corrected_sentence": "她回顾自己写过的日记，觉得很亲切。", "error_description": "补语标记错误：“得”后面必须接补语（如“回顾得很仔细”），这里“得”后直接接宾语，不通；应去掉“得”，说“回顾自己写过的日记”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没回顾了那段往事，所以忘了很多。", "corrected_sentence": "我没回顾过那段往事，所以忘了很多。", "error_description": "体标错误：否定词“没”与“过”搭配，表示没有经历过，应说“没回顾过”，不说“没回顾了”。错误只在“过”和“了”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
