INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93375, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93375, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "因之是因为这个，所以那样。", "primary_collocate": null, "pronunciation": "yīn zhī", "ipa": "in⁵⁵ ʈʂɻ̩⁵⁵", "syllable_count": 2, "sentences": [{"text": "昨天下大雨，因之比赛改到了今天。", "target_word": "因之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该企业连续亏损，因之缩减了研发投入。", "target_word": "因之", "complexity_tier": "T3", "furigana": "yīn zhī", "sentence_source": "generated"}, {"text": "该路段施工封闭，因之交通严重拥堵。", "target_word": "因之", "complexity_tier": "T3", "furigana": "yīn zhī", "sentence_source": "generated"}, {"text": "该地区空气质量优良，因之吸引了大量居民迁入。", "target_word": "因之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该地区连续降雨，因之农田大面积受淹。", "target_word": "因之", "complexity_tier": "T3", "furigana": "yīn zhī", "sentence_source": "generated"}, {"text": "该研究团队长期攻关，因之取得了突破性进展。", "target_word": "因之", "complexity_tier": "T3", "furigana": "yīn zhī", "sentence_source": "generated"}, {"text": "该桥年久失修，因之禁止车辆通行。", "target_word": "因之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原材料价格下跌，因之产品利润明显提升。", "target_word": "因之", "complexity_tier": "T3", "furigana": "yīn zhī", "sentence_source": "generated"}, {"text": "该校教学质量突出，因之报考人数逐年增加。", "target_word": "因之", "complexity_tier": "T3", "furigana": "yīn zhī", "sentence_source": "generated"}, {"text": "全国多地出现高温，因之用电负荷明显上升。", "target_word": "因之", "complexity_tier": "T3", "furigana": "yīn zhī", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "连接原因和结果，表示因为这个所以那样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因之", "is_correct": true, "explanation": "因之：表示因此、所以，连接原因和结果，符合句意。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，与“下大雨，比赛改期”的因果关系不符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”或“却”配合使用，句中没有对应的关联词。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或补充，不表示因果，与句意不符。"}], "explanations": {"因之": "因之：表示因此、所以，连接原因和结果，符合句意。", "但是": "语义：“但是”表示转折，与“下大雨，比赛改期”的因果关系不符。", "虽然": "搭配：“虽然”要与“但是”或“却”配合使用，句中没有对应的关联词。", "而且": "语义：“而且”表示递进或补充，不表示因果，与句意不符。"}, "sentence_index": 0, "correct_answer": "因之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长期努力学习，因之没有考上大学。", "explanation": "这里应该用〈但是〉。“因之”表示因此、所以，前后应是因果关系；这里前后是转折，不能用“因之”。"}, {"text": "虽然天气很冷，因之大家都来参加了活动。", "explanation": "这里应该用〈但是〉。“虽然”引出让步，后文应用“但是”表示转折；“因之”表示因果，与让步不搭配。"}, {"text": "如果他明天来，因之我们就开会。", "explanation": "这里应该用〈那么〉。“因之”引出已经发生的原因所造成的结果，不能用于假设的条件；假设条件后应说〈那么〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因之", "is_correct": true, "explanation": "因之：表示因此、所以，连接原因和结果，符合句意。"}, {"text": "此外", "is_correct": false, "explanation": "语义：“此外”表示补充，与“桥年久失修”和“禁止车辆通行”之间的因果关系不符。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，而“桥年久失修”与“禁止车辆通行”是顺承的因果关系。"}, {"text": "既然", "is_correct": false, "explanation": "搭配：“既然”应放在句首表示前提，不能插在两句之间表示结果。"}], "explanations": {"因之": "因之：表示因此、所以，连接原因和结果，符合句意。", "此外": "语义：“此外”表示补充，与“桥年久失修”和“禁止车辆通行”之间的因果关系不符。", "然而": "语义：“然而”表示转折，而“桥年久失修”与“禁止车辆通行”是顺承的因果关系。", "既然": "搭配：“既然”应放在句首表示前提，不能插在两句之间表示结果。"}, "sentence_index": 6, "correct_answer": "因之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不仅会唱歌，因之也会跳舞。", "explanation": "这里应该用〈而且〉。“因之”表示因果，不能表示并列递进；这里应说“不仅…而且…”。"}, {"text": "我正在做饭，因之窗外下起了雪。", "explanation": "这里应该用〈与此同时〉。“因之”表示因果关系，而这两件事同时发生且彼此无关，应说〈与此同时〉。"}, {"text": "他没有复习，因之考试成绩很好。", "explanation": "前后是相反的关系，“因之”引出的结果应与原因顺承，这里应改用〈但是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "该公司亏损严重因之，裁减了很多员工。", "corrected_sentence": "该公司亏损严重，因之裁减了很多员工。", "error_description": "“因之”是连词，应紧接在表示原因的分句之后的逗号后面，引出结果；写成“严重因之，”把它放在原因分句末尾，句子不通。应改为“该公司亏损严重，因之裁减了很多员工。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校临时停课，所以因之家长都来接孩子。", "corrected_sentence": "学校临时停课，因之家长都来接孩子。", "error_description": "“所以”与“因之”都表示因果，句中重复使用；应只保留一个，改为“学校临时停课，因之家长都来接孩子。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
