INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93378, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在山体、地下或水底开凿的供交通通行的通道。", "primary_collocate": null, "pronunciation": "suì dào", "ipa": "swei˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "这条隧道穿过大山，一共长三公里。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车慢慢驶进了隧道，窗外一下子黑了。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道里的灯很亮，开车不用担心。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海底修了一条很长的隧道。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了隧道，前面就是一座小城。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道口有人守着，请先停车。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁隧道里有风，站台上很凉。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雪，山上的隧道关了一天。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座隧道是去年才修好的。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车一进隧道，手机就没有信号了。", "target_word": "隧道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "海底隧道", "label": "复合"}, {"form": "隧道口", "label": "复合"}], "register": "中性", "sense_fingerprint": "山体、地下或水底开凿的交通通道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59bfadb7-bca0-4e03-be83-d192fc022fe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93378, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隧道", "is_correct": true, "explanation": "隧道指在山体、地下或水底开凿、供交通通行的通道，即目标词。"}, {"text": "随到", "is_correct": false, "explanation": "suí（第二声）与 suì（第四声）声母韵母相同，只差声调，意思是随到。"}, {"text": "睡到", "is_correct": false, "explanation": "shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡到。"}, {"text": "醉到", "is_correct": false, "explanation": "zuì 与 suì 声母不同（z 与 s），声调相同，意思是醉到。"}], "explanations": {"隧道": "隧道指在山体、地下或水底开凿、供交通通行的通道，即目标词。", "随到": "suí（第二声）与 suì（第四声）声母韵母相同，只差声调，意思是随到。", "睡到": "shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡到。", "醉到": "zuì 与 suì 声母不同（z 与 s），声调相同，意思是醉到。"}, "sentence_index": null, "correct_answer": "隧道"}, "level_3": {"options": [{"text": "隧道", "is_correct": true, "explanation": "隧道是开凿的交通通道，能够穿过大山，符合「这条___穿过大山」的句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能穿过大山，与句意不符。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：量词「条」不用于人，学生不能与「这条」搭配。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不能穿过大山，句子不通。"}], "explanations": {"隧道": "隧道是开凿的交通通道，能够穿过大山，符合「这条___穿过大山」的句意。", "石头": "语义：石头不能穿过大山，与句意不符。", "学生": "搭配：量词「条」不用于人，学生不能与「这条」搭配。", "饭": "语义：饭不能穿过大山，句子不通。"}, "sentence_index": 0, "correct_answer": "隧道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条隧道里住着一只熊。", "explanation": "这里应该用〈山洞〉。隧道是供交通通行的通道，不是住的地方，住着动物的应说「山洞」。"}, {"text": "我每天坐隧道上学。", "explanation": "这里应该用〈地铁〉。隧道是通道，本身不是交通工具，不能说「坐隧道」。"}, {"text": "我们在隧道买了火车票，然后上车。", "explanation": "这里应该用〈车站〉。隧道是供车辆通过的通道，不是买票、上车的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隧道", "is_correct": true, "explanation": "隧道是开凿的交通通道，「地铁隧道里有风」符合句意。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是可以让风流动的空间，「地铁玻璃里」不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：「地铁」后接的场所名词要能容纳风，「地铁手机」不能组成场所。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不在地铁中，「地铁河流里有风」句子不通。"}], "explanations": {"隧道": "隧道是开凿的交通通道，「地铁隧道里有风」符合句意。", "玻璃": "语义：玻璃不是可以让风流动的空间，「地铁玻璃里」不通。", "手机": "搭配：「地铁」后接的场所名词要能容纳风，「地铁手机」不能组成场所。", "河流": "语义：河流不在地铁中，「地铁河流里有风」句子不通。"}, "sentence_index": 6, "correct_answer": "隧道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在隧道上吹着风，看着河水。", "explanation": "这里应该用〈桥〉。桥架在河上，人可以站在上面；隧道是穿过山体或地下的通道，人不能站在它上面。"}, {"text": "隧道在山路上快速地跑。", "explanation": "这里应该用〈汽车〉。隧道是固定的通道，不会跑。"}, {"text": "很久以前，人们住在隧道里，靠打猎生活。", "explanation": "这里应该用〈山洞〉。隧道是人工开凿的交通通道，古人居住的是天然的山洞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这头隧道去年才通车。", "corrected_sentence": "这条隧道去年才通车。", "error_description": "隧道应用量词「条」，「头」用于大型牲畜，这里把「条」错成「头」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只隧道修了五年。", "corrected_sentence": "那座隧道修了五年。", "error_description": "「只」用于动物，隧道应用量词「座」或「条」，这里把「座」错成「只」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
