INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93379, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坑是地上挖出来的小洞。", "primary_collocate": null, "pronunciation": "kēng", "ipa": "kʰɤŋ⁵⁵", "syllable_count": 1, "sentences": [{"text": "爷爷在院子里挖了一个坑。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们挖好坑，再把小树种进去。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在地上挖坑，准备盖房子。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在坑里放了一些肥料。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坑不深，只有半米。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在坑边坐着，看他们种菜。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在海边挖了一个坑。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在花园里挖三个坑。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们先挖坑，然后放进种子。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坑太小了，大树放不进去。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "水坑", "label": "复合"}, {"form": "泥坑", "label": "复合"}], "register": "中性", "sense_fingerprint": "人在地上挖出来的小洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93379, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：坑（kēng）指地上挖出来的小洞。"}, {"text": "空", "is_correct": false, "explanation": "kōng（第一声）与 kēng 只差韵母 e/o，意思是空。"}, {"text": "哼", "is_correct": false, "explanation": "hēng（第一声）与 kēng 只差声母 h/k，意思是哼唱。"}, {"text": "康", "is_correct": false, "explanation": "kāng（第一声）与 kēng 只差韵母 a/e，意思是健康。"}, {"text": "耕", "is_correct": false, "explanation": "gēng（第一声）与 kēng 只差声母 g/k，意思是耕种。"}], "explanations": {"坑": "正确答案：坑（kēng）指地上挖出来的小洞。", "空": "kōng（第一声）与 kēng 只差韵母 e/o，意思是空。", "哼": "hēng（第一声）与 kēng 只差声母 h/k，意思是哼唱。", "康": "kāng（第一声）与 kēng 只差韵母 a/e，意思是健康。", "耕": "gēng（第一声）与 kēng 只差声母 g/k，意思是耕种。"}, "sentence_index": null, "correct_answer": "坑"}, "level_3": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：「爷爷在院子里挖了一个坑」中的坑指挖出来的小洞。"}, {"text": "沙堡", "is_correct": false, "explanation": "搭配：挖出的是坑或洞，沙堡要用堆或搭，不说「挖了一个沙堡」。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不能被挖出来，「挖了一个蛋糕」说不通。"}, {"text": "理想", "is_correct": false, "explanation": "语义：理想是抽象的概念，不能被挖，句子无法成立。"}], "explanations": {"坑": "正确答案：「爷爷在院子里挖了一个坑」中的坑指挖出来的小洞。", "沙堡": "搭配：挖出的是坑或洞，沙堡要用堆或搭，不说「挖了一个沙堡」。", "蛋糕": "语义：蛋糕不能被挖出来，「挖了一个蛋糕」说不通。", "理想": "语义：理想是抽象的概念，不能被挖，句子无法成立。"}, "sentence_index": 0, "correct_answer": "坑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的袜子破了一个坑，得赶紧补。", "explanation": "这里应该用〈洞〉。坑指挖出来的凹洞，袜子上穿透的口子要用洞。"}, {"text": "燕子在屋檐下做了一个坑，每年都回来住。", "explanation": "这里应该用〈巢〉。坑指地上挖出来的小洞，燕子在屋檐下住的地方要用巢。"}, {"text": "他在地上挖了一颗坑，准备种树。", "explanation": "这里应该用〈个〉。坑的量词是「个」，「颗」用于小而圆的东西，不用于坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93379, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：坑（kēng）指地上挖出来的小洞。"}, {"text": "烹", "is_correct": false, "explanation": "pēng（第一声）与 kēng 只差声母 p/k，意思是烹煮。"}, {"text": "砰", "is_correct": false, "explanation": "pēng（第一声）与 kēng 只差声母 p/k，是拟声词，意思是撞击声。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 kēng 只差韵尾 ng，意思是科目或科学。"}, {"text": "棵", "is_correct": false, "explanation": "kē（第一声）与 kēng 只差韵尾 ng，是量词，用于计算植物。"}], "explanations": {"坑": "正确答案：坑（kēng）指地上挖出来的小洞。", "烹": "pēng（第一声）与 kēng 只差声母 p/k，意思是烹煮。", "砰": "pēng（第一声）与 kēng 只差声母 p/k，是拟声词，意思是撞击声。", "科": "kē（第一声）与 kēng 只差韵尾 ng，意思是科目或科学。", "棵": "kē（第一声）与 kēng 只差韵尾 ng，是量词，用于计算植物。"}, "sentence_index": null, "correct_answer": "坑"}, "level_3": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：「孩子们在海边挖了一个坑」中的坑指挖出来的小洞。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦不能被挖，「挖了一个梦」说不通。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是活动，不能被挖出来，句子无法成立。"}, {"text": "城堡", "is_correct": false, "explanation": "搭配：城堡是堆或建出来的，不说「挖了一个城堡」。"}], "explanations": {"坑": "正确答案：「孩子们在海边挖了一个坑」中的坑指挖出来的小洞。", "梦": "语义：梦不能被挖，「挖了一个梦」说不通。", "游戏": "语义：游戏是活动，不能被挖出来，句子无法成立。", "城堡": "搭配：城堡是堆或建出来的，不说「挖了一个城堡」。"}, "sentence_index": 6, "correct_answer": "坑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋顶漏了一个坑，雨水都进来了。", "explanation": "这里应该用〈窟窿〉。坑指凹下去的地方，屋顶破开的大口子要用窟窿。"}, {"text": "小猫在草堆里做了一个坑，每天都在里面睡觉。", "explanation": "这里应该用〈窝〉。坑指地上挖出来的小洞，猫睡觉的地方要用窝。"}, {"text": "他在院子里挖了一块坑，准备种树。", "explanation": "这里应该用〈个〉。坑的量词是「个」，「块」用于块状物，不用于坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version =