INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们挖好一只坑，再把小树种进去。", "corrected_sentence": "我们挖好一个坑，再把小树种进去。", "error_description": "量词错误：坑应该用「个」，不说「一只坑」。「只」多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们小时候在海边挖一过个坑。", "corrected_sentence": "我们小时候在海边挖过一个坑。", "error_description": "「过」位置错误：「过」应紧跟动词「挖」，说「挖过一个坑」，不说「挖一过个坑」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
