INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上凹下去的小洼或洞。", "primary_collocate": null, "pronunciation": "kēng", "ipa": "kʰɤŋ⁵⁵", "syllable_count": 1, "sentences": [{"text": "路上有一个坑，骑车要小心。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，坑里都是水。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脚踩进了坑里。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上的坑太多，车开得很慢。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把路上的坑填平了。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后草地上出现了一个大坑。", "target_word": "坑", "complexity_tier": "T3", "furigana": "kēng", "sentence_source": "generated"}, {"text": "孩子们在沙地上玩，坑里放着小石头。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路没看路，掉进了坑里。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后路边的坑里有一只青蛙。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很不平，到处都是小坑。", "target_word": "坑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "水坑", "label": "复合"}, {"form": "泥坑", "label": "复合"}], "register": "中性", "sense_fingerprint": "地面上凹下去的小洼或洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93380, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：坑（kēng）指地面上凹下去的小洼或洞。"}, {"text": "空", "is_correct": false, "explanation": "kōng（第一声）与 kēng 只差韵母 e/o，意思是空。"}, {"text": "耕", "is_correct": false, "explanation": "gēng（第一声）与 kēng 只差声母 g/k，意思是耕种。"}, {"text": "哼", "is_correct": false, "explanation": "hēng（第一声）与 kēng 只差声母 h/k，意思是哼唱。"}, {"text": "康", "is_correct": false, "explanation": "kāng（第一声）与 kēng 只差韵母 a/e，意思是健康。"}], "explanations": {"坑": "正确答案：坑（kēng）指地面上凹下去的小洼或洞。", "空": "kōng（第一声）与 kēng 只差韵母 e/o，意思是空。", "耕": "gēng（第一声）与 kēng 只差声母 g/k，意思是耕种。", "哼": "hēng（第一声）与 kēng 只差声母 h/k，意思是哼唱。", "康": "kāng（第一声）与 kēng 只差韵母 a/e，意思是健康。"}, "sentence_index": null, "correct_answer": "坑"}, "level_3": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：「路上有一个坑」指路面凹下去的地方，骑车要小心。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户装在墙上，不会出现在路面上，与「骑车要小心」的语境不符。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦不是实物，不会放在路上，句子无法成立。"}, {"text": "尘埃", "is_correct": false, "explanation": "语义：尘埃是很细的灰尘，不能论“一个”，也不会让骑车的人需要小心。"}], "explanations": {"坑": "正确答案：「路上有一个坑」指路面凹下去的地方，骑车要小心。", "窗户": "语义：窗户装在墙上，不会出现在路面上，与「骑车要小心」的语境不符。", "梦": "语义：梦不是实物，不会放在路上，句子无法成立。", "尘埃": "语义：尘埃是很细的灰尘，不能论“一个”，也不会让骑车的人需要小心。"}, "sentence_index": 0, "correct_answer": "坑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服上有一个坑，得补一下。", "explanation": "这里应该用〈洞〉。坑指地面上凹下去的地方，衣服上穿透的口子要用洞。"}, {"text": "树杈上有一个坑，几只小鸟住在里面。", "explanation": "这里应该用〈窝〉。坑指地面上凹下去的地方，鸟住的地方要用窝。"}, {"text": "我家门口有一只坑，每次下雨都积水。", "explanation": "这里应该用〈个〉。坑的量词是「个」，「只」多用于动物，不用于坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93380, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：坑（kēng）指地面上凹下去的小洼或洞。"}, {"text": "烹", "is_correct": false, "explanation": "pēng（第一声）与 kēng 只差声母 p/k，意思是烹煮。"}, {"text": "砰", "is_correct": false, "explanation": "pēng（第一声）与 kēng 只差声母 p/k，是拟声词，意思是撞击声。"}, {"text": "科", "is_correct": false, "explanation": "kē（第一声）与 kēng 只差韵尾 ng，意思是科目或科学。"}, {"text": "棵", "is_correct": false, "explanation": "kē（第一声）与 kēng 只差韵尾 ng，是量词，用于计算植物。"}], "explanations": {"坑": "正确答案：坑（kēng）指地面上凹下去的小洼或洞。", "烹": "pēng（第一声）与 kēng 只差声母 p/k，意思是烹煮。", "砰": "pēng（第一声）与 kēng 只差声母 p/k，是拟声词，意思是撞击声。", "科": "kē（第一声）与 kēng 只差韵尾 ng，意思是科目或科学。", "棵": "kē（第一声）与 kēng 只差韵尾 ng，是量词，用于计算植物。"}, "sentence_index": null, "correct_answer": "坑"}, "level_3": {"options": [{"text": "坑", "is_correct": true, "explanation": "正确答案：「孩子们在沙地上玩，坑里放着小石头」中的坑指地上凹下去的小洼。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能放东西，与「坑里放着小石头」的语境不符。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期是时间单位，不是可以放东西的地方。"}, {"text": "脑海", "is_correct": false, "explanation": "语义：脑海指头脑里，是抽象的，不能在里面放小石头，与沙地玩耍的场景不符。"}], "explanations": {"坑": "正确答案：「孩子们在沙地上玩，坑里放着小石头」中的坑指地上凹下去的小洼。", "天空": "语义：天空不能放东西，与「坑里放着小石头」的语境不符。", "学期": "语义：学期是时间单位，不是可以放东西的地方。", "脑海": "语义：脑海指头脑里，是抽象的，不能在里面放小石头，与沙地玩耍的场景不符。"}, "sentence_index": 6, "correct_answer": "坑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的裤子被刮破了一个坑，得赶紧补。", "explanation": "这里应该用〈窟窿〉。坑指凹下去的地方，衣物被刮破的口子要用窟窿。"}, {"text": "路边的草地上有一颗坑，小朋友在里面玩。", "explanation": "这里应该用〈个〉。坑的量词是「个」，「颗」用于小而圆的东西，不用于坑。"}, {"text": "这条路上有一块坑，走的人都得绕着走。", "explanation": "这里应该用〈个〉。坑的量词是「个」，「块」用于块状物，不用于坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口有一只坑，小心别绊倒。", "corrected_sentence": "门口有一个坑，小心别绊倒。", "error_description": "量词错误：坑应该用「个」，说成「一只坑」是错的。「只」多用于动物等，不用于坑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把院子里的坑填了平。", "corrected_sentence": "工人把院子里的坑填平了。", "error_description": "结果补语位置错误：应说「填平」，「了」放在补语之后，不说「填了平」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
