INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93381, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电报是很久以前，用电把短短的信送到远处。", "primary_collocate": null, "pronunciation": "diàn bào", "ipa": "tjɛn˥˩ pɑu˥˩", "syllable_count": 2, "sentences": [{"text": "很久以前，人们靠电报传递消息。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，她年轻时收到过一封电报。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封电报只写了一句话。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电报要按字数收钱，所以大家写得很短。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里能看到以前发电报的老照片。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给家里发了一封电报，说自己平安。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候没有手机，急事只能发电报。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读到过一个电报的故事。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电报里的话越短越好。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把旧电报放在盒子里，一直留着。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "量词"}, {"form": "电报局", "label": "复合"}, {"form": "电报机", "label": "复合"}, {"form": "電報", "label": "繁体"}], "register": "通用", "sense_fingerprint": "电报：很久以前用电把短信送到远处的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5820b4e1-82a5-40c0-ae4a-682d87027408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93381, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电报", "is_correct": true, "explanation": "正确。电报是很久以前用电把短信送到远处的通信方式。"}, {"text": "战报", "is_correct": false, "explanation": "zhàn（第四声）与 diàn（第四声）声母不同（zh 与 d），意思是战报，指报告战况的文件。"}, {"text": "见报", "is_correct": false, "explanation": "jiàn（第四声）与 diàn（第四声）声母不同（j 与 d），意思是见报，指文章或消息在报纸上刊登。"}, {"text": "办报", "is_correct": false, "explanation": "bàn（第四声）与 diàn（第四声）声母不同（b 与 d），意思是办报，指经营和编辑报纸。"}, {"text": "念报", "is_correct": false, "explanation": "niàn（第四声）与 diàn（第四声）声母不同（n 与 d），意思是念报，指朗读报纸上的内容。"}], "explanations": {"电报": "正确。电报是很久以前用电把短信送到远处的通信方式。", "战报": "zhàn（第四声）与 diàn（第四声）声母不同（zh 与 d），意思是战报，指报告战况的文件。", "见报": "jiàn（第四声）与 diàn（第四声）声母不同（j 与 d），意思是见报，指文章或消息在报纸上刊登。", "办报": "bàn（第四声）与 diàn（第四声）声母不同（b 与 d），意思是办报，指经营和编辑报纸。", "念报": "niàn（第四声）与 diàn（第四声）声母不同（n 与 d），意思是念报，指朗读报纸上的内容。"}, "sentence_index": null, "correct_answer": "电报"}, "level_3": {"options": [{"text": "电报", "is_correct": true, "explanation": "正确。很久以前人们用电报传递消息，符合“靠……传递消息”的语境。"}, {"text": "视频", "is_correct": false, "explanation": "语义：视频是现在才普及的技术，“很久以前”的人不可能靠视频传递消息，与语境冲突。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：玩具不能用来传递消息，“靠……传递消息”不搭配“玩具”。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：地图用来指示路线，不能用来传递消息，与“传递消息”搭配不当。"}], "explanations": {"电报": "正确。很久以前人们用电报传递消息，符合“靠……传递消息”的语境。", "视频": "语义：视频是现在才普及的技术，“很久以前”的人不可能靠视频传递消息，与语境冲突。", "玩具": "搭配：玩具不能用来传递消息，“靠……传递消息”不搭配“玩具”。", "地图": "搭配：地图用来指示路线，不能用来传递消息，与“传递消息”搭配不当。"}, "sentence_index": 0, "correct_answer": "电报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的电报没电了，只好借别人的充电器。", "explanation": "这里应该用〈手机〉。电报是通信方式或电文，不是需要充电的设备。"}, {"text": "这份电报很厚，有十几页。", "explanation": "这里应该用〈信〉。电报按字收费，内容很短，不会厚到十几页。"}, {"text": "他收到一块电报，是家里寄来的。", "explanation": "量词错误：电报按“封”计，“块”用于块状的东西。这里应该用〈封〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电报", "is_correct": true, "explanation": "正确。“急事只能发电报”，电报是没有手机时的通信方式。"}, {"text": "语音", "is_correct": false, "explanation": "语义：语音消息要靠手机发送，与“没有手机”的语境冲突。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能用来传递急事的消息，“发饼干”与语境不符。"}, {"text": "网页", "is_correct": false, "explanation": "语义：网页需要联网浏览，与“没有手机”的语境冲突，也不能作为急事的传递方式。"}], "explanations": {"电报": "正确。“急事只能发电报”，电报是没有手机时的通信方式。", "语音": "语义：语音消息要靠手机发送，与“没有手机”的语境冲突。", "饼干": "语义：饼干是食物，不能用来传递急事的消息，“发饼干”与语境不符。", "网页": "语义：网页需要联网浏览，与“没有手机”的语境冲突，也不能作为急事的传递方式。"}, "sentence_index": 6, "correct_answer": "电报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电报坏了，大家只好走楼梯上十楼。", "explanation": "这里应该用〈电梯〉。电报是通信方式或电文，不是可以乘坐的设备。"}, {"text": "屋里的电报突然亮了，大家都松了一口气。", "explanation": "这里应该用〈电灯〉。电报是通信方式或电文，不会“亮”起来。"}, {"text": "妈妈每天早上都收听电报里的天气预报。", "explanation": "这里应该用〈电台〉。电报是通信方式或电文，不能用来“收听”天气预报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶说，她年轻时收到过一封很短地电报。", "corrected_sentence": "奶奶说，她年轻时收到过一封很短的电报。", "error_description": "结构助词错误：修饰名词“电报”应用“的”，不用“地”。错误形式：很短地电报；正确形式：很短的电报。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人留下一只电报，内容很短。", "corrected_sentence": "老人留下一封电报，内容很短。", "error_description": "量词错误：电报的量词是“封”，不能用“只”（“只”多用于动物、成对器物等）。错误形式：一只电报；正确形式：一封电报。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
