INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用电信号远距离传递文字的通信方式，或所传的文字。", "primary_collocate": null, "pronunciation": "diàn bào", "ipa": "tjɛn˥˩ pɑu˥˩", "syllable_count": 2, "sentences": [{"text": "以前的人用电报联系远方的亲人。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电报是一种用电传送文字的通信方式。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在邮局里发过电报。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收到一封电报，说妈妈明天回来。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电报的字很少，所以每个字都要想好。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了电话以后，用电报的人越来越少了。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那封电报只有四个字：我已到家。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，消息常常靠电报传回国内。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮递员把电报送到了他家门口。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电报比写信快多了。", "target_word": "电报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "量词"}, {"form": "电报局", "label": "复合"}, {"form": "电报机", "label": "复合"}, {"form": "電報", "label": "繁体"}], "register": "通用", "sense_fingerprint": "电报：用电信号远距离传文字的通信方式，或所传的电文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5820b4e1-82a5-40c0-ae4a-682d87027408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93382, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电报", "is_correct": true, "explanation": "正确。电报是利用电信号远距离传递文字的通信方式，也指所传的电文。"}, {"text": "战报", "is_correct": false, "explanation": "zhàn（第四声）与 diàn（第四声）声母不同（zh 与 d），意思是战报，指报告战况的文件。"}, {"text": "见报", "is_correct": false, "explanation": "jiàn（第四声）与 diàn（第四声）声母不同（j 与 d），意思是见报，指文章或消息在报纸上刊登。"}, {"text": "办报", "is_correct": false, "explanation": "bàn（第四声）与 diàn（第四声）声母不同（b 与 d），意思是办报，指经营和编辑报纸。"}, {"text": "念报", "is_correct": false, "explanation": "niàn（第四声）与 diàn（第四声）声母不同（n 与 d），意思是念报，指朗读报纸上的内容。"}], "explanations": {"电报": "正确。电报是利用电信号远距离传递文字的通信方式，也指所传的电文。", "战报": "zhàn（第四声）与 diàn（第四声）声母不同（zh 与 d），意思是战报，指报告战况的文件。", "见报": "jiàn（第四声）与 diàn（第四声）声母不同（j 与 d），意思是见报，指文章或消息在报纸上刊登。", "办报": "bàn（第四声）与 diàn（第四声）声母不同（b 与 d），意思是办报，指经营和编辑报纸。", "念报": "niàn（第四声）与 diàn（第四声）声母不同（n 与 d），意思是念报，指朗读报纸上的内容。"}, "sentence_index": null, "correct_answer": "电报"}, "level_3": {"options": [{"text": "电报", "is_correct": true, "explanation": "正确。电报是用电信号传递文字的通信方式，符合“用……联系远方的亲人”的语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：钥匙不是通信工具，不能用来“联系远方的亲人”。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：地图不能用来与远方的亲人联系，“用……联系”不能搭配“地图”。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：玩具没有传递消息的功能，不能用来“联系远方的亲人”。"}], "explanations": {"电报": "正确。电报是用电信号传递文字的通信方式，符合“用……联系远方的亲人”的语境。", "钥匙": "搭配：钥匙不是通信工具，不能用来“联系远方的亲人”。", "地图": "搭配：地图不能用来与远方的亲人联系，“用……联系”不能搭配“地图”。", "玩具": "搭配：玩具没有传递消息的功能，不能用来“联系远方的亲人”。"}, "sentence_index": 0, "correct_answer": "电报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里的电报突然灭了，我们只好在黑暗中坐了一个小时。", "explanation": "这里应该用〈电灯〉。电报是通信方式或电文，不会像电灯那样突然“灭”掉。"}, {"text": "我收到一本电报，上面写着好消息。", "explanation": "量词错误：电报按“封”计，“本”用于书籍。这里应该用〈封〉。"}, {"text": "这封电报写了十页，非常详细。", "explanation": "这里应该用〈信〉。电报按字收费，内容要求简短，不能写十页。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电报", "is_correct": true, "explanation": "正确。“那封电报只有四个字：我已到家”，电报是用电信号传送文字的通信方式，符合“封”与“四个字”的语境。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“封”用于信件、电报一类，不用于椅子，“那封椅子”不成立。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“封”不用于钥匙，“那封钥匙”不成立。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“封”不用于饼干，“那封饼干”不成立。"}], "explanations": {"电报": "正确。“那封电报只有四个字：我已到家”，电报是用电信号传送文字的通信方式，符合“封”与“四个字”的语境。", "椅子": "搭配：“封”用于信件、电报一类，不用于椅子，“那封椅子”不成立。", "钥匙": "搭配：“封”不用于钥匙，“那封钥匙”不成立。", "饼干": "搭配：“封”不用于饼干，“那封饼干”不成立。"}, "sentence_index": 6, "correct_answer": "电报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一带的电报突然中断了，家家户户都用不了电。", "explanation": "这里应该用〈电力〉。电报指通信方式或电文，不能说“中断”造成停电。"}, {"text": "他每天早上躺在床上收听电报里的新闻。", "explanation": "这里应该用〈电台〉。电报是通信方式或电文，不能用来“收听”新闻。"}, {"text": "电报坏了，我们只好去外面的饭店看球赛。", "explanation": "这里应该用〈电视〉。电报是通信方式或电文，不是能用来看球赛的设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天收到了一只电报。", "corrected_sentence": "他昨天收到了一封电报。", "error_description": "量词错误：电报的量词是“封”，不能用“只”。错误形式：一只电报；正确形式：一封电报。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈发来一封很短地电报。", "corrected_sentence": "妈妈发来一封很短的电报。", "error_description": "结构助词错误：修饰名词“电报”应用“的”，不用“地”（“地”用于修饰动词）。错误形式：很短地电报；正确形式：很短的电报。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74f92a7c-9b5c-40cd-958c-5c2d74a45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
