INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93383, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "灵是反应快，动得又快又准。", "primary_collocate": null, "pronunciation": "líng", "ipa": "liŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他手脚很灵，一下就爬上了树。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手很灵，三下就修好了。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫的动作特别灵。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的腿脚还很灵，每天都去爬山。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗跑起来很灵，一下就钻过了栏杆。", "target_word": "灵", "complexity_tier": "T3", "furigana": "zhè zhī xiǎo gǒu pǎo qǐ lái hěn líng yí xià jiù zuān guò le lángān", "sentence_source": "generated"}, {"text": "他身子灵，一闪就躲开了球。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子手灵，折纸折得又快又好。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员的反应真灵，把球扑了出去。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅的手还是那么灵。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子身手灵，几下就跳上了墙。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "靈", "label": "繁体"}, {"form": "灵不灵", "label": "正反问"}], "register": "口语", "sense_fingerprint": "灵_形容词_反应快、动作又快又准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93383, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵（líng）：反应快，动作又快又准。这是目标词。"}, {"text": "另", "is_correct": false, "explanation": "lìng（第四声）与 líng（第二声）声调不同，意思是另外。"}, {"text": "宁", "is_correct": false, "explanation": "níng 与 líng 声母不同（n／l），意思是安宁。"}, {"text": "林", "is_correct": false, "explanation": "lín 与 líng 韵母不同（in／ing），意思是树林。"}, {"text": "岭", "is_correct": false, "explanation": "lǐng（第三声）与 líng（第二声）声调不同，意思是山岭。"}], "explanations": {"灵": "灵（líng）：反应快，动作又快又准。这是目标词。", "另": "lìng（第四声）与 líng（第二声）声调不同，意思是另外。", "宁": "níng 与 líng 声母不同（n／l），意思是安宁。", "林": "lín 与 líng 韵母不同（in／ing），意思是树林。", "岭": "lǐng（第三声）与 líng（第二声）声调不同，意思是山岭。"}, "sentence_index": null, "correct_answer": "灵"}, "level_3": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵：动作敏捷，符合“一下就爬上了树”。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说动作迟缓，与“一下就爬上了树”矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容体形，不用来形容手脚的敏捷程度。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”说僵直，与“一下就爬上了树”的敏捷矛盾。"}], "explanations": {"灵": "灵：动作敏捷，符合“一下就爬上了树”。", "慢": "语义：“慢”说动作迟缓，与“一下就爬上了树”矛盾。", "胖": "体貌：“胖”形容体形，不用来形容手脚的敏捷程度。", "硬": "语义：“硬”说僵直，与“一下就爬上了树”的敏捷矛盾。"}, "sentence_index": 0, "correct_answer": "灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木板很灵，一压就断了。", "explanation": "这里应该用〈脆〉。灵说动作或反应，不用来说木板的坚韧程度。"}, {"text": "这把椅子很灵，坐上去很稳。", "explanation": "这里应该用〈稳〉。灵说动作或反应，不用来说椅子稳不稳。"}, {"text": "这个箱子很灵，压不坏。", "explanation": "这里应该用〈结实〉。灵说动作或反应，不用来说物件坚固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93383, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵（líng）：反应快，动作又快又准。这是目标词。"}, {"text": "领", "is_correct": false, "explanation": "lǐng（第三声）与 líng（第二声）声调不同，意思是衣领、带领。"}, {"text": "凝", "is_correct": false, "explanation": "níng 与 líng 声母不同（n／l），意思是凝结。"}, {"text": "令", "is_correct": false, "explanation": "lìng（第四声）与 líng（第二声）声调不同，意思是命令。"}, {"text": "临", "is_correct": false, "explanation": "lín 与 líng 韵母不同（in／ing），意思是靠近。"}], "explanations": {"灵": "灵（líng）：反应快，动作又快又准。这是目标词。", "领": "lǐng（第三声）与 líng（第二声）声调不同，意思是衣领、带领。", "凝": "níng 与 líng 声母不同（n／l），意思是凝结。", "令": "lìng（第四声）与 líng（第二声）声调不同，意思是命令。", "临": "lín 与 líng 韵母不同（in／ing），意思是靠近。"}, "sentence_index": null, "correct_answer": "灵"}, "level_3": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵：手灵活，与“折得又快又好”相符。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”说人的勤惰，与“折得又快又好”矛盾。"}, {"text": "软", "is_correct": false, "explanation": "语义：“软”说手无力，与“折得又快又好”矛盾。"}, {"text": "厚", "is_correct": false, "explanation": "体貌：“厚”说物体的厚度，不用来形容手的灵活程度。"}], "explanations": {"灵": "灵：手灵活，与“折得又快又好”相符。", "懒": "语义：“懒”说人的勤惰，与“折得又快又好”矛盾。", "软": "语义：“软”说手无力，与“折得又快又好”矛盾。", "厚": "体貌：“厚”说物体的厚度，不用来形容手的灵活程度。"}, "sentence_index": 6, "correct_answer": "灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面很灵，我吃了两碗。", "explanation": "这里应该用〈好吃〉。灵不用来形容食物的味道。"}, {"text": "图书馆里很灵，大家都在看书。", "explanation": "这里应该用〈安静〉。灵不用来形容环境的安静与否。"}, {"text": "这间教室很灵，同学们都很开心。", "explanation": "这里应该用〈宽敞〉。灵不用来形容空间的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小猫跳地很灵，一下就跳上了桌子。", "corrected_sentence": "这只小猫跳得很灵，一下就跳上了桌子。", "error_description": "错误在补语标记。动词后带程度补语时要用“得”，不能用表示状语的“地”，应说“跳得很灵”，不说“跳地很灵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的动作灵很，一下就躲开了飞来的球。", "corrected_sentence": "他的动作很灵，一下就躲开了飞来的球。", "error_description": "错误在程度副词“很”的位置。“很”应放在形容词“灵”之前，说“很灵”，不说“灵很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
