INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93384, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "灵活；灵敏；效果好。", "primary_collocate": null, "pronunciation": "líng", "ipa": "liŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这种药真灵，我吃了一天就好了。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脑子很灵，一学就会。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的耳朵还很灵。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的屏幕不太灵。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的鼻子真灵，什么味道都闻得到。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方法很灵，我试过。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板消息很灵。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑今天不太灵，老是卡住。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王脑子灵，做生意很会算。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个开关不灵了，我得换一个。", "target_word": "灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "靈", "label": "繁体"}, {"form": "灵不灵", "label": "正反问"}], "register": "口语", "sense_fingerprint": "灵_形容词_效果好、灵活、灵敏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93384, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵（líng）：灵活、灵敏，效果好。这是目标词。"}, {"text": "领", "is_correct": false, "explanation": "lǐng（第三声）与 líng（第二声）声调不同，意思是衣领、带领。"}, {"text": "宁", "is_correct": false, "explanation": "níng 与 líng 声母不同（n／l），意思是安宁。"}, {"text": "林", "is_correct": false, "explanation": "lín 与 líng 韵母不同（in／ing），意思是树林。"}, {"text": "另", "is_correct": false, "explanation": "lìng（第四声）与 líng（第二声）声调不同，意思是另外。"}], "explanations": {"灵": "灵（líng）：灵活、灵敏，效果好。这是目标词。", "领": "lǐng（第三声）与 líng（第二声）声调不同，意思是衣领、带领。", "宁": "níng 与 líng 声母不同（n／l），意思是安宁。", "林": "lín 与 líng 韵母不同（in／ing），意思是树林。", "另": "lìng（第四声）与 líng（第二声）声调不同，意思是另外。"}, "sentence_index": null, "correct_answer": "灵"}, "level_3": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵：效果好，药吃下去很快见效，符合句意。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说见效慢，与“吃了一天就好了”的快速见效矛盾。"}, {"text": "笨", "is_correct": false, "explanation": "搭配：“笨”只用于形容人的智力或动作反应，不能用来形容药。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，不能用来形容药的效果。"}], "explanations": {"灵": "灵：效果好，药吃下去很快见效，符合句意。", "慢": "语义：“慢”说见效慢，与“吃了一天就好了”的快速见效矛盾。", "笨": "搭配：“笨”只用于形容人的智力或动作反应，不能用来形容药。", "远": "语义：“远”说距离，不能用来形容药的效果。"}, "sentence_index": 0, "correct_answer": "灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌很灵，我每天都听。", "explanation": "这里应该用〈好听〉。灵说反应快、动作准或效果好，不用来评价歌曲好不好听。"}, {"text": "这家餐厅的菜很灵，大家都喜欢。", "explanation": "这里应该用〈好吃〉。灵不用来形容食物的味道。"}, {"text": "这件衣服很灵，我很喜欢。", "explanation": "这里应该用〈好看〉。灵不用来形容衣服的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93384, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵（líng）：灵活、灵敏，效果好。这是目标词。"}, {"text": "岭", "is_correct": false, "explanation": "lǐng（第三声）与 líng（第二声）声调不同，意思是山岭。"}, {"text": "凝", "is_correct": false, "explanation": "níng 与 líng 声母不同（n／l），意思是凝结。"}, {"text": "令", "is_correct": false, "explanation": "lìng（第四声）与 líng（第二声）声调不同，意思是命令。"}, {"text": "临", "is_correct": false, "explanation": "lín 与 líng 韵母不同（in／ing），意思是靠近。"}], "explanations": {"灵": "灵（líng）：灵活、灵敏，效果好。这是目标词。", "岭": "lǐng（第三声）与 líng（第二声）声调不同，意思是山岭。", "凝": "níng 与 líng 声母不同（n／l），意思是凝结。", "令": "lìng（第四声）与 líng（第二声）声调不同，意思是命令。", "临": "lín 与 líng 韵母不同（in／ing），意思是靠近。"}, "sentence_index": null, "correct_answer": "灵"}, "level_3": {"options": [{"text": "灵", "is_correct": true, "explanation": "灵：消息灵通，符合“消息很灵”的说法。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说物体的厚薄，消息没有厚薄之分。"}, {"text": "窄", "is_correct": false, "explanation": "语义：“窄”说空间或宽度，不用来形容消息。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或物的体形，不能用来形容消息。"}], "explanations": {"灵": "灵：消息灵通，符合“消息很灵”的说法。", "厚": "语义：“厚”说物体的厚薄，消息没有厚薄之分。", "窄": "语义：“窄”说空间或宽度，不用来形容消息。", "瘦": "体貌：“瘦”形容人或物的体形，不能用来形容消息。"}, "sentence_index": 6, "correct_answer": "灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个游戏很灵，我玩了一下午。", "explanation": "这里应该用〈好玩〉。灵不用来评价游戏有没有趣味。"}, {"text": "这杯茶很灵，我喝了两杯。", "explanation": "这里应该用〈好喝〉。灵不用来形容饮料的味道。"}, {"text": "这朵花很灵，大家都来拍照。", "explanation": "这里应该用〈漂亮〉。灵不用来形容花的外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED