INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小偏方很挺灵，妈妈常用。", "corrected_sentence": "这个小偏方挺灵，妈妈常用。", "error_description": "错误在程度副词的重复。“很”和“挺”都是程度副词，不能同时修饰形容词“灵”，应去掉“很”，只说“挺灵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老奶奶的手脚很还灵，什么活儿都能干。", "corrected_sentence": "老奶奶的手脚还很灵，什么活儿都能干。", "error_description": "错误在副词的位置。“还”应放在“很”之前，应说“还很灵”，不说“很还灵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
