INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93385, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外国人是别的国家的人，不是我们自己国家的人。", "primary_collocate": null, "pronunciation": "wài guó rén", "ipa": "uaɪ˥˩ kuo˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "街上有很多外国人。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我的朋友，是一个外国人。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个外国人在问路，我带他去了车站。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和外国人练习英语口语。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里住着很多外国人。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是外国人，所以说汉语有口音。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人也喜欢吃我们的饺子。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次见到外国人，有点紧张。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国旅游的外国人越来越多。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位外国人请我帮他拍照。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别的国家的人，不是自己国家的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93385, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外星人", "is_correct": false, "explanation": "语义：外星人并不会在街上大量出现，与“街上有很多”的常识不符。"}, {"text": "外国人", "is_correct": true, "explanation": "正确：街上常见很多外国人，只有它符合“街上有很多”的语境。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不会成群在街上出现，与句意冲突。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象不会大量出现在街上，与句意不符。"}], "explanations": {"外星人": "语义：外星人并不会在街上大量出现，与“街上有很多”的常识不符。", "外国人": "正确：街上常见很多外国人，只有它符合“街上有很多”的语境。", "老虎": "语义：老虎不会成群在街上出现，与句意冲突。", "大象": "语义：大象不会大量出现在街上，与句意不符。"}, "sentence_index": 0, "correct_answer": "外国人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班新来了一本外国人。", "explanation": "这里应该用〈个〉或〈位〉。〈本〉用于书册，不用于人；〈外国人〉指人，应用〈个〉或〈位〉。"}, {"text": "我们家有一条外国人。", "explanation": "这里应该用〈个〉或〈位〉。〈条〉用于细长的东西，不用于人；〈外国人〉指人，应用〈个〉或〈位〉。"}, {"text": "周末我们用外国人做了一个蛋糕。", "explanation": "〈外国人〉指人，不能当材料；做蛋糕应用〈面粉〉这类食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93385, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会吃东西，也不会喜欢吃饺子，与句意冲突。"}, {"text": "外国人", "is_correct": true, "explanation": "正确：句子说的是有喜好、会吃饺子的人，只有外国人符合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有喜好，不会喜欢吃饺子。"}, {"text": "大米", "is_correct": false, "explanation": "搭配：“喜欢吃”的主语须是有生命的人或动物，“大米”不能作它的主语。"}], "explanations": {"电脑": "语义：电脑不会吃东西，也不会喜欢吃饺子，与句意冲突。", "外国人": "正确：句子说的是有喜好、会吃饺子的人，只有外国人符合。", "石头": "语义：石头没有喜好，不会喜欢吃饺子。", "大米": "搭配：“喜欢吃”的主语须是有生命的人或动物，“大米”不能作它的主语。"}, "sentence_index": 6, "correct_answer": "外国人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会说三种外国人。", "explanation": "这里应该用〈外语〉。〈外国人〉指人，不指语言；说语言要用〈外语〉。"}, {"text": "这次我们去外国人旅行。", "explanation": "这里应该用〈外国〉作地点。〈外国人〉指人，不指地方，去的地方要说〈外国〉。"}, {"text": "这盆花是我的外国人。", "explanation": "这里应该用〈植物〉类词；〈外国人〉指有国籍的人，不能指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上走过来一只外国人。", "corrected_sentence": "街上走过来一位外国人。", "error_description": "〈只〉用于动物，指人应用〈位〉或〈个〉，〈位〉更礼貌。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天在车站遇到一外国人。", "corrected_sentence": "我昨天在车站遇到一个外国人。", "error_description": "数词与名词之间需要量词，〈一外国人〉应为〈一个外国人〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
