INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "具有外国国籍的人；本国以外国家的人。", "primary_collocate": null, "pronunciation": "wài guó rén", "ipa": "uaɪ˥˩ kuo˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "外国人入境时需要出示护照。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是外国人，不能参加这个国家的选举。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人在这里工作，要办理工作证件。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生在中国，但是国籍是美国，算外国人。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司雇了十名外国人。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人买房子需要符合一定的条件。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿着外国护照，所以是外国人。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人在中国居住，要登记住址。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律对外国人和本国人有不同的规定。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学每年招收几百名外国人。", "target_word": "外国人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "具有外国国籍、在法律上不属于本国的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车入境要登记车辆证件，不出示护照，与句意不符。"}, {"text": "外国人", "is_correct": true, "explanation": "正确：只有具有外国国籍的人入境时需要出示护照，符合句意。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李没有护照，入境时不会出示护照。"}, {"text": "货物", "is_correct": false, "explanation": "搭配：货物入境要提交报关单，不说“出示护照”，这里不搭配。"}], "explanations": {"汽车": "语义：汽车入境要登记车辆证件，不出示护照，与句意不符。", "外国人": "正确：只有具有外国国籍的人入境时需要出示护照，符合句意。", "行李": "语义：行李没有护照，入境时不会出示护照。", "货物": "搭配：货物入境要提交报关单，不说“出示护照”，这里不搭配。"}, "sentence_index": 0, "correct_answer": "外国人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出生在美国，但是拥有中国国籍，算外国人。", "explanation": "〈外国人〉指具有外国国籍的人。此人拥有中国国籍，不算外国人，这里应该用〈中国人〉，语义矛盾。"}, {"text": "这家公司雇了一台外国人。", "explanation": "这里应该用〈名〉或〈位〉。〈台〉用于机器，不用于人；〈外国人〉指人，应用〈名〉或〈位〉。"}, {"text": "周末我们一起去外国人吃饭。", "explanation": "〈外国人〉是名词，不是地点，不能说“去外国人”；这里应该用〈饭馆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中国人", "is_correct": false, "explanation": "语义：拿着外国护照的人不会因此是中国人，这样说与句中的护照相矛盾。"}, {"text": "外国人", "is_correct": true, "explanation": "正确：句中的“外国护照”说明她具有外国国籍，所以是外国人。"}, {"text": "本国人", "is_correct": false, "explanation": "语义：拿着外国护照的人不属于本国人，与“所以是本国人”矛盾。"}, {"text": "外国", "is_correct": false, "explanation": "语义：“外国”指地方，不指人，不能说“她是外国”，应说“外国人”。"}], "explanations": {"中国人": "语义：拿着外国护照的人不会因此是中国人，这样说与句中的护照相矛盾。", "外国人": "正确：句中的“外国护照”说明她具有外国国籍，所以是外国人。", "本国人": "语义：拿着外国护照的人不属于本国人，与“所以是本国人”矛盾。", "外国": "语义：“外国”指地方，不指人，不能说“她是外国”，应说“外国人”。"}, "sentence_index": 6, "correct_answer": "外国人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所大学是外国人，每年招收几百名学生。", "explanation": "〈外国人〉指人，不指学校机构；若说学校的外国性质，应用〈外国〉或〈外资〉作修饰，如“外资大学”。"}, {"text": "我会说三种外国人。", "explanation": "这里应该用〈外语〉。〈外国人〉指人，不是语言。"}, {"text": "这所大学每年印刷几百名外国人。", "explanation": "这里应该用可以印刷的东西，如〈教材〉；〈外国人〉指人，不能被印刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在北京读书外国人需要办理居留证件。", "corrected_sentence": "在北京读书的外国人需要办理居留证件。", "error_description": "定语与中心语之间需要〈的〉，〈在北京读书外国人〉应为〈在北京读书的外国人〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的朋友是一外国人，他很幽默。", "corrected_sentence": "我的朋友是一位外国人，他很幽默。", "error_description": "数词与名词之间需要量词，〈一外国人〉应为〈一位外国人〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
