INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "胆量大，敢做敢为，不畏惧。", "primary_collocate": null, "pronunciation": "dà dǎn", "ipa": "ta˥˩ tan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个想法很大胆，以前没人敢这样做。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做了一个大胆的决定，辞职去开店。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大胆地在会上提出了一个新方案。", "target_word": "大胆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板大胆用年轻人，公司越来越好。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要大胆尝试，不要怕错。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的做法很大胆，让大家都吃了一惊。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大胆地说出了自己的看法。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位大胆的设计师把花园建在了屋顶上。", "target_word": "大胆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大胆提问，老师不会生气。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻时的做法很大胆，什么新东西都想试。", "target_word": "大胆", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大胆地", "label": "状语形式"}, {"form": "大膽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "胆量大、敢做敢为的想法、决定或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e00da9fe-c9f4-4fde-8aa7-2a7d288258f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大胆", "is_correct": true, "explanation": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。"}, {"text": "大单", "is_correct": false, "explanation": "dān（第一声）与 dǎn（第三声）声调不同，意思是大额订单。"}, {"text": "大党", "is_correct": false, "explanation": "dǎng 与 dǎn 韵尾不同（ng 与 n），意思是大的政党。"}, {"text": "大岛", "is_correct": false, "explanation": "dǎo（第三声）与 dǎn 韵尾不同（o 与 n），意思是大岛屿。"}], "explanations": {"大胆": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。", "大单": "dān（第一声）与 dǎn（第三声）声调不同，意思是大额订单。", "大党": "dǎng 与 dǎn 韵尾不同（ng 与 n），意思是大的政党。", "大岛": "dǎo（第三声）与 dǎn 韵尾不同（o 与 n），意思是大岛屿。"}, "sentence_index": null, "correct_answer": "大胆"}, "level_3": {"options": [{"text": "大胆", "is_correct": true, "explanation": "“大胆”形容想法敢于突破，与“以前没人敢这样做”相符。"}, {"text": "普通", "is_correct": false, "explanation": "语义：“普通”指平常，与“以前没人敢这样做”的新奇相矛盾。"}, {"text": "寻常", "is_correct": false, "explanation": "语域：“寻常”偏书面，口语中很少这样形容想法，且与“以前没人敢这样做”的含义相反。"}, {"text": "稳妥", "is_correct": false, "explanation": "语义：“稳妥”指不冒险，与“以前没人敢这样做”所说的敢于突破相反。"}], "explanations": {"大胆": "“大胆”形容想法敢于突破，与“以前没人敢这样做”相符。", "普通": "语义：“普通”指平常，与“以前没人敢这样做”的新奇相矛盾。", "寻常": "语域：“寻常”偏书面，口语中很少这样形容想法，且与“以前没人敢这样做”的含义相反。", "稳妥": "语义：“稳妥”指不冒险，与“以前没人敢这样做”所说的敢于突破相反。"}, "sentence_index": 0, "correct_answer": "大胆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老板很大胆，每次进货都要先请示上级，不敢拿主意。", "explanation": "这里应该用〈犹豫〉。大胆指敢做、敢拿主意，与“不敢拿主意”相矛盾。"}, {"text": "他很大胆，整天躺在床上，什么事都不愿做。", "explanation": "这里应该用〈懒惰〉。大胆指敢做、不畏惧，不指不愿动。"}, {"text": "这个孩子很大胆，见了生人就脸红。", "explanation": "这里应该用〈害羞〉。大胆指敢做、不畏惧，不指怕生、脸红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大胆", "is_correct": true, "explanation": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。"}, {"text": "大喊", "is_correct": false, "explanation": "hǎn（第三声）与 dǎn 声母不同（h 与 d），意思是大声喊叫。"}, {"text": "大伞", "is_correct": false, "explanation": "sǎn（第三声）与 dǎn 声母不同（s 与 d），意思是大号的伞。"}, {"text": "大板", "is_correct": false, "explanation": "bǎn（第三声）与 dǎn 声母不同（b 与 d），意思是大木板。"}, {"text": "打蛋", "is_correct": false, "explanation": "dǎ dàn 两个音节的声调都与 dà dǎn 不同，意思是打鸡蛋。"}], "explanations": {"大胆": "大胆（dà dǎn）指胆量大、敢做敢为，是听到的目标词。", "大喊": "hǎn（第三声）与 dǎn 声母不同（h 与 d），意思是大声喊叫。", "大伞": "sǎn（第三声）与 dǎn 声母不同（s 与 d），意思是大号的伞。", "大板": "bǎn（第三声）与 dǎn 声母不同（b 与 d），意思是大木板。", "打蛋": "dǎ dàn 两个音节的声调都与 dà dǎn 不同，意思是打鸡蛋。"}, "sentence_index": null, "correct_answer": "大胆"}, "level_3": {"options": [{"text": "大胆", "is_correct": true, "explanation": "“大胆”形容敢做、不畏惧，与“她……说出了自己的看法”的敢于表达相符。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，与“说出了自己的看法”相矛盾。"}, {"text": "唯唯诺诺", "is_correct": false, "explanation": "语域：“唯唯诺诺”偏书面，且形容顺从、不敢表态，与“说出了自己的看法”不合。"}, {"text": "不敢", "is_correct": false, "explanation": "搭配：“不敢地说出”不通，且与“说出了自己的看法”的敢言相反。"}], "explanations": {"大胆": "“大胆”形容敢做、不畏惧，与“她……说出了自己的看法”的敢于表达相符。", "沉默": "语义：“沉默”指不说话，与“说出了自己的看法”相矛盾。", "唯唯诺诺": "语域：“唯唯诺诺”偏书面，且形容顺从、不敢表态，与“说出了自己的看法”不合。", "不敢": "搭配：“不敢地说出”不通，且与“说出了自己的看法”的敢言相反。"}, "sentence_index": 6, "correct_answer": "大胆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很大胆，见了生人就躲到妈妈身后。", "explanation": "这里应该用〈害羞〉。大胆指敢做、不畏惧，与“躲到妈妈身后”的怕生正相反。"}, {"text": "他很大胆，一见大场面就发抖。", "explanation": "这里应该用〈胆怯〉。大胆指敢做、不畏惧，与“发抖”的怯场状态正相反。"}, {"text": "他很大胆，做什么事都要先问问别人的意见。", "explanation": "这里应该用〈谨慎〉。大胆指敢做敢为，不指凡事小心、先问别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
