INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位大胆地画家把画挂在了屋顶上。", "corrected_sentence": "这位大胆的画家把画挂在了屋顶上。", "error_description": "“大胆”修饰名词“画家”时要用“的”，“地”只用于修饰动词，应说“大胆的画家”，不能说“大胆地画家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
