INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93391, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鼻子是脸上用来闻味道的器官。", "primary_collocate": null, "pronunciation": "bí zi", "ipa": "pi˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "我用鼻子闻到了花的香味。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感冒了，鼻子闻不到味道。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭很香，我的鼻子先闻到了。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼻子是用来闻味道的。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闻了闻，鼻子里全是咖啡香。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间有怪味，我用鼻子一闻就知道。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的鼻子很灵，一下就闻出了鱼的味道。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明捂着鼻子，因为垃圾很臭。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我鼻子不好，闻不出汽油味。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕刚出炉，鼻子就闻到了甜味。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大鼻子", "label": "复合"}], "register": "中性", "sense_fingerprint": "脸上用来闻味道的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼻子", "is_correct": true, "explanation": "正确：鼻子是用来闻味道的器官，“用鼻子闻到花香”符合句意。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵是用来听的，不能用来闻香味。"}, {"text": "舌头", "is_correct": false, "explanation": "语义：舌头用来尝味道，闻花香不靠舌头。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“闻”的对象是气味，不说用眼睛闻。"}], "explanations": {"鼻子": "正确：鼻子是用来闻味道的器官，“用鼻子闻到花香”符合句意。", "耳朵": "语义：耳朵是用来听的，不能用来闻香味。", "舌头": "语义：舌头用来尝味道，闻花香不靠舌头。", "眼睛": "搭配：“闻”的对象是气味，不说用眼睛闻。"}, "sentence_index": 0, "correct_answer": "鼻子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用鼻子吃饭，吃得很香。", "explanation": "这里应该用〈嘴〉。鼻子只用来闻味道，吃饭要用嘴。"}, {"text": "我用鼻子听声音，很清楚。", "explanation": "这里应该用〈耳朵〉。鼻子不能用来听声音，听声音要用耳朵。"}, {"text": "我脸上有一条鼻子。", "explanation": "这里应该用〈个〉。鼻子的量词用“个”，“条”一般用于长条形的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鼻子", "is_correct": true, "explanation": "正确：“妈妈的鼻子很灵”指嗅觉好，能一下闻出鱼的味道，符合句意。"}, {"text": "手", "is_correct": false, "explanation": "语义：手不能用来闻味道，“手很灵，闻出鱼的味道”不合常理。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：嘴用来尝味道，不用来闻，句中的“闻出”与“嘴”不合。"}, {"text": "脸", "is_correct": false, "explanation": "搭配：“灵”一般用于感官，不说“脸很灵”。"}], "explanations": {"鼻子": "正确：“妈妈的鼻子很灵”指嗅觉好，能一下闻出鱼的味道，符合句意。", "手": "语义：手不能用来闻味道，“手很灵，闻出鱼的味道”不合常理。", "嘴": "语义：嘴用来尝味道，不用来闻，句中的“闻出”与“嘴”不合。", "脸": "搭配：“灵”一般用于感官，不说“脸很灵”。"}, "sentence_index": 6, "correct_answer": "鼻子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用鼻子踢足球，踢得很远。", "explanation": "这里应该用〈脚〉。鼻子只用来闻味道，踢球要用脚。"}, {"text": "我用鼻子写字，写得很整齐。", "explanation": "这里应该用〈手〉。鼻子不能用来写字，写字要用手。"}, {"text": "妈妈的脸上有一只鼻子。", "explanation": "这里应该用〈个〉。鼻子的量词用“个”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈有一只大鼻子。", "corrected_sentence": "妈妈有一个大鼻子。", "error_description": "量词用错。“鼻子”的量词用“个”，不用“只”（“只”多用于动物或成对物件中的一件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明有一条很灵的鼻子。", "corrected_sentence": "小明有一个很灵的鼻子。", "error_description": "量词用错。“鼻子”的量词用“个”，不用“条”（“条”多用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
