INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物的呼吸与嗅觉器官。", "primary_collocate": null, "pronunciation": "bí zi", "ipa": "pi˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "大象的鼻子又长又大。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用鼻子呼吸，不用嘴。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒了，我的鼻子不通气。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的鼻子湿湿的。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的鼻子高高的，很好看。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷，我的鼻子冻红了。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸自己的鼻子。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，鼻子红红的。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用纸擦一下鼻子。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猪用鼻子在地上找吃的。", "target_word": "鼻子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大鼻子", "label": "复合"}], "register": "中性", "sense_fingerprint": "人和动物的呼吸与嗅觉器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼻子", "is_correct": true, "explanation": "正确：大象的鼻子又长又大，符合句意。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：大象没有翅膀，“大象的翅膀又长又大”不成立。"}, {"text": "头发", "is_correct": false, "explanation": "语义：大象身上不说“头发”，句意不通。"}, {"text": "手", "is_correct": false, "explanation": "搭配：大象没有手，“手”不搭配大象的身体部位。"}], "explanations": {"鼻子": "正确：大象的鼻子又长又大，符合句意。", "翅膀": "语义：大象没有翅膀，“大象的翅膀又长又大”不成立。", "头发": "语义：大象身上不说“头发”，句意不通。", "手": "搭配：大象没有手，“手”不搭配大象的身体部位。"}, "sentence_index": 0, "correct_answer": "鼻子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用鼻子看书，看得很清楚。", "explanation": "这里应该用〈眼睛〉。鼻子用来呼吸和闻味，看书要用眼睛。"}, {"text": "小狗用鼻子跑步，跑得很快。", "explanation": "这里应该用〈腿〉。鼻子用来呼吸，跑步要用腿。"}, {"text": "小狗有一条鼻子。", "explanation": "这里应该用〈个〉。鼻子的量词用“个”，不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鼻子", "is_correct": true, "explanation": "正确：“用手摸了摸自己的鼻子”是身体部位，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是身体部位，“摸了摸自己的汽车”句意不通。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不是身体部位，句中“自己的”后不能接墨水。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“摸”一般针对实物，不说“摸自己的影子”。"}], "explanations": {"鼻子": "正确：“用手摸了摸自己的鼻子”是身体部位，符合句意。", "汽车": "语义：汽车不是身体部位，“摸了摸自己的汽车”句意不通。", "墨水": "语义：墨水不是身体部位，句中“自己的”后不能接墨水。", "影子": "搭配：“摸”一般针对实物，不说“摸自己的影子”。"}, "sentence_index": 6, "correct_answer": "鼻子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用鼻子喝水，喝了一大杯。", "explanation": "这里应该用〈嘴〉。鼻子用来呼吸，喝水要用嘴。"}, {"text": "猪用鼻子写字。", "explanation": "这里应该用〈手〉。鼻子不能用来写字，写字要用手。"}, {"text": "他用鼻子唱歌，唱得很好听。", "explanation": "这里应该用〈嗓子〉。鼻子用来呼吸，唱歌要靠嗓子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大象有一本长长的鼻子。", "corrected_sentence": "大象有一个长长的鼻子。", "error_description": "量词用错。“鼻子”的量词用“个”，不用“本”（“本”用于书册等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹有一只小鼻子。", "corrected_sentence": "妹妹有一个小鼻子。", "error_description": "量词用错。“鼻子”的量词用“个”，不用“只”（“只”多用于动物或成对物件中的一件）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
