INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "恋爱关系中的女方。", "primary_collocate": null, "pronunciation": "nǚ péng you", "ipa": "ny˨˩˦ pʰɤŋ˧˥ joʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他的女朋友在银行工作。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想带女朋友去看电影。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和女朋友已经谈了三年。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我要陪女朋友逛街。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给女朋友买了一束花。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有女朋友吗？", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的女朋友会做很好吃的菜。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分手后，他没有再找女朋友。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把女朋友的生日记在手机里。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女朋友生气时，他会先道歉。", "target_word": "女朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女友", "label": "简称"}], "register": "口语", "sense_fingerprint": "女朋友：恋爱关系中的女方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6126fc-082d-4972-80f0-b37b1dacae83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小猫", "is_correct": false, "explanation": "语义：“在银行工作”的主语应是人，小猫不能在银行上班。"}, {"text": "女朋友", "is_correct": true, "explanation": "女朋友指恋爱关系中的女方，她在银行工作，语义通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能在银行工作。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工作”的主语应是人，“工资”是报酬，不能做“工作”的主语。"}], "explanations": {"小猫": "语义：“在银行工作”的主语应是人，小猫不能在银行上班。", "女朋友": "女朋友指恋爱关系中的女方，她在银行工作，语义通顺。", "椅子": "语义：椅子是家具，不能在银行工作。", "工资": "搭配：“工作”的主语应是人，“工资”是报酬，不能做“工作”的主语。"}, "sentence_index": 0, "correct_answer": "女朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和女朋友已经结婚三年了。", "explanation": "这里应该用〈妻子〉。“女朋友”指恋爱关系中的女方，不指已经结婚的配偶。"}, {"text": "这家饭馆的女朋友很热情，每天招呼客人。", "explanation": "这里应该用〈女老板〉。“女朋友”指恋爱关系中的女方，不能指饭馆的经营者。"}, {"text": "我交了一只女朋友。", "explanation": "这里应该用〈个〉。“只”用于动物或成对器官中的一个，不用于指人的恋人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会做菜，与“会做很好吃的菜”的语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有做饭的能力，不能会做菜。"}, {"text": "女朋友", "is_correct": true, "explanation": "女朋友是人，可以会做菜，语义通顺。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“做菜”的主语应是人，“手机”不能做菜。"}], "explanations": {"小狗": "语义：小狗不会做菜，与“会做很好吃的菜”的语境不合。", "石头": "语义：石头没有做饭的能力，不能会做菜。", "女朋友": "女朋友是人，可以会做菜，语义通顺。", "手机": "搭配：“做菜”的主语应是人，“手机”不能做菜。"}, "sentence_index": 6, "correct_answer": "女朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班里的女朋友都很认真学习。", "explanation": "这里应该用〈女生〉。“女朋友”只指恋爱中的女方，不能用来泛指全班的女生。"}, {"text": "他的女朋友是他的爷爷，每天给他做饭。", "explanation": "这里应该用〈长辈〉。“女朋友”指恋爱关系中的女方，不能用来指自己的长辈。"}, {"text": "我交了一把女朋友。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，不用于指人的恋人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最近交了一头女朋友。", "corrected_sentence": "他最近交了一个女朋友。", "error_description": "量词错误：“女朋友”前应用〈个〉，“头”用于大牲畜，不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一条女朋友，常常送她花。", "corrected_sentence": "他有一位女朋友，常常送她花。", "error_description": "量词错误：“女朋友”前应用〈位〉或〈个〉，“条”用于细长的东西，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
