INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，指堆积在一起的很多东西。", "primary_collocate": null, "pronunciation": "yì duī", "ipa": "i˥˩ tweɪ˥", "syllable_count": 2, "sentences": [{"text": "他买了一堆水果回家。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一堆吃的。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发给我们一堆练习题。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从箱子里拿出一堆照片。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有一堆便宜的苹果。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车里装着一堆行李。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店门口放了一堆旧书，很便宜。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把一堆玩具放进了箱子里。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她洗了一堆碗，累坏了。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子旁边有一堆盒子。", "target_word": "一堆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一大堆", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量词，指堆积在一起的很多东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b5a7c1a-21c0-4822-b161-907b245b99f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一堆", "is_correct": true, "explanation": "“一堆”指堆积在一起的很多东西，买来的水果正是这样，句意成立。"}, {"text": "一台", "is_correct": false, "explanation": "搭配：“台”用于机器、仪器等，水果不能用“台”计量。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定物体，水果不能用“座”计量。"}, {"text": "一场", "is_correct": false, "explanation": "语义：“场”用于一段活动或事件，“他买了一场水果”说不通。"}], "explanations": {"一堆": "“一堆”指堆积在一起的很多东西，买来的水果正是这样，句意成立。", "一台": "搭配：“台”用于机器、仪器等，水果不能用“台”计量。", "一座": "搭配：“座”用于山、房屋等大型固定物体，水果不能用“座”计量。", "一场": "语义：“场”用于一段活动或事件，“他买了一场水果”说不通。"}, "sentence_index": 0, "correct_answer": "一堆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气喝完了一堆牛奶。", "explanation": "这里应该用〈一杯〉。“一堆”指堆在一起的固体东西，牛奶是液体，要用“杯”计量。"}, {"text": "他端来一堆汤给客人喝。", "explanation": "这里应该用〈一碗〉。“一堆”指堆在一起的固体东西，汤是液体，盛出来要说“一碗汤”。"}, {"text": "操场上站着一堆大树。", "explanation": "这里应该用〈一排〉。“一堆”指堆在一起的东西，整齐排列的树要说“一排”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一堆", "is_correct": true, "explanation": "“一堆”指堆积在一起的很多东西，门口放着的旧书正是这样，句意成立。"}, {"text": "一顶", "is_correct": false, "explanation": "搭配：“顶”用于帽子、帐篷等，书不能用“顶”计量。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，成堆的旧书不能用“根”计量。"}, {"text": "一位", "is_correct": false, "explanation": "语义：“位”用于人，旧书不是人，“放了一位旧书”说不通。"}], "explanations": {"一堆": "“一堆”指堆积在一起的很多东西，门口放着的旧书正是这样，句意成立。", "一顶": "搭配：“顶”用于帽子、帐篷等，书不能用“顶”计量。", "一根": "搭配：“根”用于细长的东西，成堆的旧书不能用“根”计量。", "一位": "语义：“位”用于人，旧书不是人，“放了一位旧书”说不通。"}, "sentence_index": 6, "correct_answer": "一堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子旁边站着一堆书架。", "explanation": "这里应该用〈一个〉。“一堆”指很多东西堆在一起，单独的一件家具要用“个”计数。"}, {"text": "我把一堆眼镜戴在了鼻子上。", "explanation": "这里应该用〈一副〉。“一堆”指堆放的东西，成对成套的眼镜要说“一副”。"}, {"text": "他坐在一堆椅子上吃饭。", "explanation": "这里应该用〈一把〉。“一堆”指很多东西堆在一起，坐的椅子只能一把，要说“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们搬走了一堆了旧书。", "corrected_sentence": "我们搬走了一堆旧书。", "error_description": "助词位置错误：“了”只能放在动词后，不能插在“一堆”后面。应删去“一堆”后多出的“了”，改为“搬走了一堆旧书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d32cef-912c-4cdf-9c1c-2c466a01477e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
