INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难吃", "is_correct": true, "explanation": "正确：“难吃”是“好吃”的反义词，说食物味道不好。"}, {"text": "便宜", "is_correct": false, "explanation": "与“好吃”无反义关系，“便宜”说价钱低。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“好吃”无反义关系，“漂亮”说外貌好看。"}, {"text": "干净", "is_correct": false, "explanation": "与“好吃”无反义关系，“干净”说整洁。"}], "correct_answer": "难吃", "explanations": {"难吃": "正确：“难吃”是“好吃”的反义词，说食物味道不好。", "便宜": "与“好吃”无反义关系，“便宜”说价钱低。", "漂亮": "与“好吃”无反义关系，“漂亮”说外貌好看。", "干净": "与“好吃”无反义关系，“干净”说整洁。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难吃", "is_correct": true, "explanation": "正确：“难吃”是“好吃”的反义词，说食物味道不好。"}, {"text": "高兴", "is_correct": false, "explanation": "与“好吃”无反义关系，“高兴”说心情好。"}, {"text": "凉快", "is_correct": false, "explanation": "与“好吃”无反义关系，“凉快”说温度低。"}, {"text": "整齐", "is_correct": false, "explanation": "与“好吃”无反义关系，“整齐”说排列有序。"}], "correct_answer": "难吃", "explanations": {"难吃": "正确：“难吃”是“好吃”的反义词，说食物味道不好。", "高兴": "与“好吃”无反义关系，“高兴”说心情好。", "凉快": "与“好吃”无反义关系，“凉快”说温度低。", "整齐": "与“好吃”无反义关系，“整齐”说排列有序。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好吃是吃起来味道很好。", "primary_collocate": null, "pronunciation": "hǎo chī", "ipa": "xaʊ˨˩ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "妈妈做的鱼很好吃，我吃了两碗饭。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面条又便宜又好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果看起来很大，但是不太好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做的蛋糕真好吃，再给我一块吧。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京烤鸭好吃极了，我还想再吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个菜最好吃？我想点一个。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说奶奶包的饺子比饭馆的更好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果不贵，而且都很好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我们吃的火锅特别好吃。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子都喜欢好吃的东西。", "target_word": "好吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更好吃", "label": "比较"}, {"form": "最好吃", "label": "最高级"}, {"form": "不好吃", "label": "否定"}, {"form": "好吃的", "label": "的字结构"}], "register": "口语", "sense_fingerprint": "食物吃起来味道很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好吃", "is_correct": true, "explanation": "正确：“很好吃”说鱼的味道好，与“吃了两碗饭”相符。"}, {"text": "好喝", "is_correct": false, "explanation": "搭配：“好喝”说饮料，不能用来形容鱼。"}, {"text": "好听", "is_correct": false, "explanation": "语义：“好听”说声音，不能用来形容鱼的味道。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价钱，自己做的鱼不谈价钱，与句子不搭。"}], "explanations": {"好吃": "正确：“很好吃”说鱼的味道好，与“吃了两碗饭”相符。", "好喝": "搭配：“好喝”说饮料，不能用来形容鱼。", "好听": "语义：“好听”说声音，不能用来形容鱼的味道。", "贵": "搭配：“贵”说价钱，自己做的鱼不谈价钱，与句子不搭。"}, "sentence_index": 0, "correct_answer": "好吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子很好吃。", "explanation": "这里应该用〈结实〉。好吃说食物味道好，桌子坚固要说结实。"}, {"text": "这把剪刀很好吃。", "explanation": "这里应该用〈好用〉。好吃用于食物，工具好不好用要说好用。"}, {"text": "这首歌很好吃。", "explanation": "这里应该用〈好听〉。好吃说食物味道，歌曲好不好要说好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好吃", "is_correct": true, "explanation": "正确：“比饭馆的更好吃”说饺子味道更好，与句意相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说人的头脑，不能用来形容饺子。"}, {"text": "勤快", "is_correct": false, "explanation": "语义：“勤快”说人的做事态度，不能用来形容饺子。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多说场面，不搭配饺子的味道比较。"}], "explanations": {"好吃": "正确：“比饭馆的更好吃”说饺子味道更好，与句意相符。", "聪明": "语义：“聪明”说人的头脑，不能用来形容饺子。", "勤快": "语义：“勤快”说人的做事态度，不能用来形容饺子。", "热闹": "搭配：“热闹”多说场面，不搭配饺子的味道比较。"}, "sentence_index": 6, "correct_answer": "好吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很好吃。", "explanation": "这里应该用〈好看〉。好吃说食物味道好，衣服样子好要说好看。"}, {"text": "这个游戏很好吃。", "explanation": "这里应该用〈好玩〉。好吃用于食物，游戏有趣要说好玩。"}, {"text": "这个房间很好吃。", "explanation": "这里应该用〈舒服〉。好吃用于食物，房间住着感觉好要说舒服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这碗面条真好吃得，我还想再来一碗。", "corrected_sentence": "这碗面条真好吃，我还想再来一碗。", "error_description": "错误：“得”不能接在没有补语的“好吃”后面，“真好吃得”应去掉“得”。正确形式是“真好吃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的饺子最更好吃，每天都排队。", "corrected_sentence": "这家店的饺子最好吃，每天都排队。", "error_description": "错误：“最”和“更”都表示程度，不能同时用。“最好吃”是最高级，应去掉多余的“更”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93401, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93401, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93401, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就便是顺着做一件事，同时做另一件事，不用多跑一趟。", "primary_collocate": null, "pronunciation": "jiù biàn", "ipa": "tɕiou̯˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "你去超市，就便帮我买瓶水。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去银行取钱，就便交了电费。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班回家时，就便去菜市场买了菜。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去邮局寄信，就便取了包裹。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你出门的时候，就便把垃圾带下去。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去图书馆还书，就便借了两本新书。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回老家看妈妈，就便见了几个老同学。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去办公室，就便给我拿一下文件。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去学校接孩子，就便买点水果。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去药店买药，就便给奶奶带了一盒茶。", "target_word": "就便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做一件事时顺着再做另一件事，省得多跑一趟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93401, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "就便", "is_correct": true, "explanation": "正确答案。就便（jiù biàn）是副词，意思是顺便。"}, {"text": "旧边", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）只差声调，意思是旧的边缘。"}, {"text": "旧片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），声调相同，意思是旧电影。"}, {"text": "九遍", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是九次。"}, {"text": "巨变", "is_correct": false, "explanation": "jù 与 jiù 少了介音 i，声调相同，意思是巨大的变化。"}, {"text": "旧店", "is_correct": false, "explanation": "diàn 与 biàn 声母不同（d 与 b），意思是旧商店。"}], "explanations": {"就便": "正确答案。就便（jiù biàn）是副词，意思是顺便。", "旧边": "biān（第一声）与 biàn（第四声）只差声调，意思是旧的边缘。", "旧片": "piàn 与 biàn 声母不同（p 与 b），声调相同，意思是旧电影。", "九遍": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是九次。", "巨变": "jù 与 jiù 少了介音 i，声调相同，意思是巨大的变化。", "旧店": "diàn 与 biàn 声母不同（d 与 b），意思是旧商店。"}, "sentence_index": null, "correct_answer": "就便"}, "level_3": {"options": [{"text": "就便", "is_correct": true, "explanation": "正确。就便表示去超市的同时顺带帮忙买水，符合句意。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：已经表示动作已经完成，与表示请求的“你去……帮我买”相冲突。"}, {"text": "从来", "is_correct": false, "explanation": "语义：从来表示一贯如此、从未发生，与一次性的请求不相容。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：刚刚表示不久前发生，与句中祈使性的“去”和“帮我买”冲突。"}], "explanations": {"就便": "正确。就便表示去超市的同时顺带帮忙买水，符合句意。", "已经": "体貌：已经表示动作已经完成，与表示请求的“你去……帮我买”相冲突。", "从来": "语义：从来表示一贯如此、从未发生，与一次性的请求不相容。", "刚刚": "语义：刚刚表示不久前发生，与句中祈使性的“去”和“帮我买”冲突。"}, "sentence_index": 0, "correct_answer": "就便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天去邮局寄信，就便明天去银行。", "explanation": "这里把就便误当作〈然后〉，表示先后相继。就便只表示同一次出行中顺带做的事，不能连接昨天与明天这样不同时间的行动。"}, {"text": "我就便喜欢这座城市。", "explanation": "这里把就便误当作〈正好〉，表示恰巧如此。就便只表示顺带做一件事，“喜欢”是心理状态，不能顺带发生。"}, {"text": "他就便学习汉语和日语。", "explanation": "这里应该用〈同时〉。就便表示顺带做另一件事，要以主要活动为前提；两件事并列进行时用同时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就便", "is_correct": true, "explanation": "正确。就便表示回老家时顺带见老同学，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "语义：从来表示从未发生，与“见了几个老同学”的一次性事件冲突。"}, {"text": "一直", "is_correct": false, "explanation": "体貌：一直表示持续，与表示完成的“见了”及一次性的事件不符。"}, {"text": "始终", "is_correct": false, "explanation": "体貌：始终表示持续不断，与一次性的“见了几个”不符。"}], "explanations": {"就便": "正确。就便表示回老家时顺带见老同学，符合句意。", "从来": "语义：从来表示从未发生，与“见了几个老同学”的一次性事件冲突。", "一直": "体貌：一直表示持续，与表示完成的“见了”及一次性的事件不符。", "始终": "体貌：始终表示持续不断，与一次性的“见了几个”不符。"}, "sentence_index": 6, "correct_answer": "就便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没去药店，就便给奶奶带了一盒茶。", "explanation": "这里把就便误当作〈另外〉，表示与前面无关地再做一件事。就便要以已经在做的一次出行为前提，“没去药店”使前提不成立。"}, {"text": "他就便从北京赶来看奶奶。", "explanation": "这里应该用〈特地〉。就便表示顺路做事，专程从北京赶来不是顺路。"}, {"text": "他去药店买药，就便往相反的方向去了火车站。", "explanation": "这里把就便误当作〈专程〉，表示专门为此跑一趟。就便要求顺路，药店与火车站方向相反，不能算顺路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下楼买报纸，就便了取快递。", "corrected_sentence": "我下楼买报纸，就便取了快递。", "error_description": "错误：“了”不能放在“就便”与动词之间，应紧跟在动词“取”之后。正确说法是“……，就便取了快递”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我路过书店，就便一本杂志。", "corrected_sentence": "我路过书店，就便买了一本杂志。", "error_description": "错误：就便是副词，不能直接带宾语“一本杂志”，后面必须有动词。正确说法是“……，就便买了一本杂志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
