INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93403, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "二话是别的话，另外的意见。", "primary_collocate": null, "pronunciation": "èr huà", "ipa": "ɚ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "经理一开口，大家都没有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他二话不说，打开门就跑了出去。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说去哪儿，我绝对没二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老人摔倒，他二话不说跑过去扶。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法好，我没有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她二话不说，把饭做好了。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥二话不说，借给我一千块钱。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这个安排，他一点二话也没有。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说好的事，我们不会再有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一听有人生病，医生二话不说就出发了。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别的话、另外的意见，常说没有二话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二话", "is_correct": true, "explanation": "正确：“没有二话”指大家都不提不同意见，与“经理一开口”相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：“大家都没有书”与“经理一开口”的语境不合，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”与上下文无关，句子语义不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“没有”后接“脚步”不构成可以接受的搭配。"}], "explanations": {"二话": "正确：“没有二话”指大家都不提不同意见，与“经理一开口”相符。", "书": "语义：“大家都没有书”与“经理一开口”的语境不合，句意不通。", "汽车": "语义：“汽车”与上下文无关，句子语义不通。", "脚步": "搭配：“没有”后接“脚步”不构成可以接受的搭配。"}, "sentence_index": 0, "correct_answer": "二话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司发了一份二话。", "explanation": "这里应该用〈通知〉。二话指别的话或不同意见，不指文件，发文件要用通知。"}, {"text": "他买了两张二话，去看比赛。", "explanation": "这里应该用〈门票〉。二话不能用“张”计量，买票要用门票。"}, {"text": "这个二话很好用。", "explanation": "这里应该用〈版本〉。二话不指软件或产品，描述软件版本要用版本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二话", "is_correct": true, "explanation": "正确：“二话不说”表示毫不推辞，与“借给我一千块钱”相符。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：“杯子”不能用于“不说”的结构，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“说”不能以“钥匙”为对象。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”与借钱的语境无关，句子语义不通。"}], "explanations": {"二话": "正确：“二话不说”表示毫不推辞，与“借给我一千块钱”相符。", "杯子": "语义：“杯子”不能用于“不说”的结构，句意不通。", "钥匙": "搭配：“说”不能以“钥匙”为对象。", "椅子": "语义：“椅子”与借钱的语境无关，句子语义不通。"}, "sentence_index": 6, "correct_answer": "二话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跟我打了个二话。", "explanation": "这里应该用〈招呼〉。二话不与“打”搭配，打招呼要用招呼。"}, {"text": "她讲的二话很有趣。", "explanation": "这里应该用〈笑话〉。二话指别的话或不同意见，不指有趣的故事，讲有趣的故事要用笑话。"}, {"text": "这道题的二话很简单。", "explanation": "这里应该用〈答案〉。二话指别的话或不同意见，不指题目的解法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她二话说，就去开了门。", "corrected_sentence": "她二话不说，就去开了门。", "error_description": "错误：固定说法是“二话不说”，漏掉了“不”，“二话说”不成立。正确：“她二话不说，就去开了门。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份安排他一点二话也不有。", "corrected_sentence": "这份安排他一点二话也没有。", "error_description": "错误：“有”的否定应为“没有”，不能说“也不有”。正确：“这份安排他一点二话也没有。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
