INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别的话；不同的意见（多用于“没有二话”“二话不说”）。", "primary_collocate": null, "pronunciation": "èr huà", "ipa": "ɚ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "他二话不说，就把钱给了我。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说干就干，没有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友有困难，我二话不说就去帮忙。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让他去，他二话没说就走了。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你开口，我绝没有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都同意，没有人有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他接过行李，二话不说就上楼了。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的决定，学生们没有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你要搬家，我二话不说来帮你。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事就这么定了，谁也不许有二话。", "target_word": "二话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别的话、不同意见，多用于没有二话、二话不说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二话", "is_correct": true, "explanation": "正确：“二话不说”是固定说法，表示毫不推辞，与“就把钱给了我”相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不能作“不说”的对象，“二话不说”的意思不成立。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“不说”的对象只能是话语或意见，不能是“脚步”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以说或不说的内容，句子语义不通。"}], "explanations": {"二话": "正确：“二话不说”是固定说法，表示毫不推辞，与“就把钱给了我”相符。", "书": "语义：“书”不能作“不说”的对象，“二话不说”的意思不成立。", "脚步": "搭配：“不说”的对象只能是话语或意见，不能是“脚步”。", "天气": "语义：“天气”不是可以说或不说的内容，句子语义不通。"}, "sentence_index": 0, "correct_answer": "二话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份二话写得很清楚。", "explanation": "这里应该用〈说明〉。二话指别的话或不同意见，不指说明文字。"}, {"text": "他跟我打了个二话。", "explanation": "这里应该用〈招呼〉。二话不与“打”搭配，打招呼要用招呼。"}, {"text": "她讲的二话总是那么有趣。", "explanation": "这里应该用〈笑话〉。二话指别的话或不同意见，不指有趣的故事，讲有趣的故事要用笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二话", "is_correct": true, "explanation": "正确：“二话不说”表示毫不犹豫，与“接过行李就上楼”相符。"}, {"text": "手表", "is_correct": false, "explanation": "语义：“手表”不是可以说或不说的内容，句子语义不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“说”不能以“钥匙”为对象。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”不能用于“不说”的结构，句意不通。"}], "explanations": {"二话": "正确：“二话不说”表示毫不犹豫，与“接过行李就上楼”相符。", "手表": "语义：“手表”不是可以说或不说的内容，句子语义不通。", "钥匙": "搭配：“说”不能以“钥匙”为对象。", "椅子": "语义：“椅子”不能用于“不说”的结构，句意不通。"}, "sentence_index": 6, "correct_answer": "二话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的二话很简单。", "explanation": "这里应该用〈答案〉。二话指别的话或不同意见，不指题目的解法。"}, {"text": "这张二话很详细。", "explanation": "这里应该用〈地图〉。二话不指可以用“张”计量的实物，描述地图要用地图。"}, {"text": "这个版本的二话很好用。", "explanation": "这里应该用〈软件〉。二话指别的话或不同意见，不指软件，“这个版本的软件很好用”中要用软件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她二话说就答应了。", "corrected_sentence": "她二话不说就答应了。", "error_description": "错误：“二话”后漏了“不”。固定格式是“二话不说”，表示毫不推辞。正确：“她二话不说就答应了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事大家都不有二话。", "corrected_sentence": "这件事大家都没有二话。", "error_description": "错误：“有”的否定应为“没有”，不能说“不有”。正确：“这件事大家都没有二话。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93405, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "年末", "is_correct": true, "explanation": "反义：“年初”指一年开始的时候，“年末”指一年将尽的时候，两者相对。"}, {"text": "周末", "is_correct": false, "explanation": "无反义关系：“周末”指一周的最后几天，与“年初”不构成反义。"}, {"text": "月末", "is_correct": false, "explanation": "无反义关系：“月末”指一个月的末尾，与“年初”不构成反义。"}, {"text": "清晨", "is_correct": false, "explanation": "无反义关系：“清晨”指一天的开始时段，与“年初”不构成反义。"}], "correct_answer": "年末", "explanations": {"年末": "反义：“年初”指一年开始的时候，“年末”指一年将尽的时候，两者相对。", "周末": "无反义关系：“周末”指一周的最后几天，与“年初”不构成反义。", "月末": "无反义关系：“月末”指一个月的末尾，与“年初”不构成反义。", "清晨": "无反义关系：“清晨”指一天的开始时段，与“年初”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93405, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "年末", "is_correct": true, "explanation": "反义：“年初”指一年的开始，“年末”指一年的结束，两者相对。"}, {"text": "中午", "is_correct": false, "explanation": "无反义关系：“中午”指一天的中间时段，与“年初”不构成反义。"}, {"text": "午夜", "is_correct": false, "explanation": "无反义关系：“午夜”指夜间十二点前后，与“年初”不构成反义。"}, {"text": "傍晚", "is_correct": false, "explanation": "无反义关系：“傍晚”指日落前后，与“年初”不构成反义。"}], "correct_answer": "年末", "explanations": {"年末": "反义：“年初”指一年的开始，“年末”指一年的结束，两者相对。", "中午": "无反义关系：“中午”指一天的中间时段，与“年初”不构成反义。", "午夜": "无反义关系：“午夜”指夜间十二点前后，与“年初”不构成反义。", "傍晚": "无反义关系：“傍晚”指日落前后，与“年初”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93405, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年初是一年刚开始的时候。", "primary_collocate": null, "pronunciation": "nián chū", "ipa": "njɛn˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "年初我搬到了北京。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年初开始学汉语。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年年初天气特别冷。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年初公司招了五个新人。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们年初就订好了机票。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年年初我去过上海。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年初的时候，大家都很忙。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年初买了一辆新车。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年初定的计划，年底完成了。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从年初到现在，我瘦了五公斤。", "target_word": "年初", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一年刚开始的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年初", "is_correct": true, "explanation": "正确：“年初”指一年刚开始的时候，与“搬到了”的已完成语气相合。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与表示已完成的“搬到了”矛盾。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来的一年，与已完成的“搬到了”冲突。"}, {"text": "将来", "is_correct": false, "explanation": "搭配：“将来”指未来，与表示已完成的“了”不搭配。"}], "explanations": {"年初": "正确：“年初”指一年刚开始的时候，与“搬到了”的已完成语气相合。", "明天": "语义：“明天”指将来，与表示已完成的“搬到了”矛盾。", "明年": "语义：“明年”指将来的一年，与已完成的“搬到了”冲突。", "将来": "搭配：“将来”指未来，与表示已完成的“了”不搭配。"}, "sentence_index": 0, "correct_answer": "年初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祝大家年初快乐！", "explanation": "这里应该用〈新年〉。节日祝福语说“新年快乐”，“年初”只指时段，不能用于祝福。"}, {"text": "年初的时候，我们已经统计完了今年全年的业绩。", "explanation": "这里应该用〈年末〉。统计全年业绩要等到年末，年初时今年的全年数据还不存在。"}, {"text": "年初的时候，他已经把今年的年终奖发完了。", "explanation": "这里应该用〈年末〉。年终奖要到年末才发放，年初时今年的年终奖还没有发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年初", "is_correct": true, "explanation": "正确：“年初”是一年的开始，与“大家都很忙”的描述相合。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”是午间小睡，与“大家都很忙”矛盾。"}, {"text": "闲暇", "is_correct": false, "explanation": "语义：“闲暇”指空闲的时间，与“大家都很忙”矛盾。"}, {"text": "午休", "is_correct": false, "explanation": "搭配：“午休”是中午的休息时段，与“的时候，大家都很忙”搭配不当。"}], "explanations": {"年初": "正确：“年初”是一年的开始，与“大家都很忙”的描述相合。", "午睡": "语义：“午睡”是午间小睡，与“大家都很忙”矛盾。", "闲暇": "语义：“闲暇”指空闲的时间，与“大家都很忙”矛盾。", "午休": "搭配：“午休”是中午的休息时段，与“的时候，大家都很忙”搭配不当。"}, "sentence_index": 6, "correct_answer": "年初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的年初我要去上海出差。", "explanation": "这里应该用〈月初〉。“年初”指一年的开始，不能用来指一个月的开始。"}, {"text": "这学期的年初要交学费。", "explanation": "这里应该用〈学期初〉。“年初”指一年的开始，不能用来指一个学期的开始。"}, {"text": "我们每周的年初都开会。", "explanation": "这里应该用〈周一〉。“年初”指一年的开始，每周开会应说“每周一”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们年初的决定搬家。", "corrected_sentence": "我们年初决定搬家。", "error_description": "助词错误：“年初”作状语修饰动词时不加“的”，“年初的决定搬家”结构不通。错误形式是“我们年初的决定搬家”，正确形式是“我们年初决定搬家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "从年初在现在，公司的业绩一直很好。", "corrected_sentence": "从年初到现在，公司的业绩一直很好。", "error_description": "介词错误：“从…到…”表示时间范围，应用“到”而不是“在”。错误形式是“从年初在现在”，正确形式是“从年初到现在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
