INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93410, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "询问某个动作发生了多少次，通常预期次数不多。", "primary_collocate": null, "pronunciation": "jǐ cì", "ipa": "tɕi˨˩˦ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "你去过几次中国？", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字你写了几次？", "target_word": "几次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个星期来几次？", "target_word": "几次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们一个月见几次面？", "target_word": "几次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题老师讲过几次？", "target_word": "几次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话你打了几次？", "target_word": "几次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天吃几次药？", "target_word": "几次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你一年回几次家？", "target_word": "几次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你学了几次才学会？", "target_word": "几次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影你看过几次？", "target_word": "几次", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "第几次", "label": "复合"}, {"form": "幾次", "label": "繁体"}], "register": "口语", "sense_fingerprint": "询问次数：问做了多少次，预期数量不大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6126fc-082d-4972-80f0-b37b1dacae83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几次", "is_correct": true, "explanation": "正确：“去过几次中国”是在询问去的次数，与句意相合。"}, {"text": "几年", "is_correct": false, "explanation": "语义：这句问的是次数，“几年”问的是年数，与句意冲突。"}, {"text": "几天", "is_correct": false, "explanation": "语义：这句问的是次数，“几天”问的是天数，与句意冲突。"}, {"text": "几个", "is_correct": false, "explanation": "搭配：“去过”后面的次数要用“次”，“中国”是地名，不能用“个”来计数。"}], "explanations": {"几次": "正确：“去过几次中国”是在询问去的次数，与句意相合。", "几年": "语义：这句问的是次数，“几年”问的是年数，与句意冲突。", "几天": "语义：这句问的是次数，“几天”问的是天数，与句意冲突。", "几个": "搭配：“去过”后面的次数要用“次”，“中国”是地名，不能用“个”来计数。"}, "sentence_index": 0, "correct_answer": "几次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你们一个月见几次面，一共见了一百次？", "explanation": "这里应该用〈很多次〉。“几次”问的是不多的次数，与“一百次”的大数矛盾。"}, {"text": "你今年几次了？", "explanation": "这里应该用〈几岁〉。“几次”问的是次数，问年龄要用“几岁”。"}, {"text": "你们班有几次同学？", "explanation": "这里应该用〈几个〉。“次”是计量动作的量词，不能用来数人，数人应说几个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几次", "is_correct": true, "explanation": "正确：“吃几次药”是在问每天服药的次数，与“每天”相合。"}, {"text": "几周", "is_correct": false, "explanation": "语义：“每天”指每日，“几周”是较长的时段，与句意冲突。"}, {"text": "几岁", "is_correct": false, "explanation": "语义：“几岁”问年龄，不能放在“吃……药”中间，与句意冲突。"}, {"text": "几小时", "is_correct": false, "explanation": "语义：“几小时”是时长，问的是服药的次数，与句意冲突。"}], "explanations": {"几次": "正确：“吃几次药”是在问每天服药的次数，与“每天”相合。", "几周": "语义：“每天”指每日，“几周”是较长的时段，与句意冲突。", "几岁": "语义：“几岁”问年龄，不能放在“吃……药”中间，与句意冲突。", "几小时": "语义：“几小时”是时长，问的是服药的次数，与句意冲突。"}, "sentence_index": 6, "correct_answer": "几次"}, "level_6": {"correct_sentence_index": 6, "wrong_sentences": [{"text": "她今年几次了？", "explanation": "这里应该用〈几岁〉。“几次”问的是次数，问年龄要用“几岁”。"}, {"text": "他每天吃几次个药？", "explanation": "这里应该用〈几次〉，后面不加“个”。“几次”本身就是数量，后面不能再接量词“个”，应说“吃几次药”。"}, {"text": "他每天吃几次药，一天吃了一千次？", "explanation": "这里应该用〈很多次〉。“几次”问的是预期不多的次数，与“一千次”的大数矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你平时去了过几次医院？", "corrected_sentence": "你平时去过几次医院？", "error_description": "错误在于“了”和“过”的叠用。“去过”已表示经历，不能再加“了”，应说“你平时去过几次医院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她今年去了几次个医院？", "corrected_sentence": "她今年去了几次医院？", "error_description": "错误在于量词的堆叠。“几次”已经表示次数，后面不能再接量词“个”，应说“去了几次医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
