INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93413, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物是人盖起来的房子和大楼。", "primary_collocate": null, "pronunciation": "jiàn zhù wù", "ipa": "tɕjɛn˥˩ ʈʂu˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "这条街上有很多高大的建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座建筑物是新盖的。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的建筑物都很漂亮。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的建筑物越来越高。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，请不要靠近旧建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校最高的建筑物是图书馆。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些建筑物是五十年前盖的。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上能看见城里的建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老建筑物里没有电梯。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天画一座建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "建築物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人盖起来的房子、大楼等建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建筑物", "is_correct": true, "explanation": "正确。“建筑物”指人盖起来的大型房屋，与“这条街上有很多高大的”搭配。"}, {"text": "山峰", "is_correct": false, "explanation": "语义：山峰在山上，不会出现在街上，与句中的“这条街上”冲突。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“高大”形容有形的实体，不能修饰语言。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“高大”不能修饰问题，说“很多高大的问题”不通。"}], "explanations": {"建筑物": "正确。“建筑物”指人盖起来的大型房屋，与“这条街上有很多高大的”搭配。", "山峰": "语义：山峰在山上，不会出现在街上，与句中的“这条街上”冲突。", "语言": "搭配：“高大”形容有形的实体，不能修饰语言。", "问题": "搭配：“高大”不能修饰问题，说“很多高大的问题”不通。"}, "sentence_index": 0, "correct_answer": "建筑物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一只建筑物。", "explanation": "这里应该用〈座〉。建筑物是大型房屋，量词用座；“只”多用于动物，不能用来数建筑物。"}, {"text": "建筑物是一门艺术。", "explanation": "这里应该用〈建筑〉。作为艺术门类要说“建筑”；建筑物指已建成的房屋、桥梁等实体，不能当作艺术门类。"}, {"text": "我大学学的是建筑物。", "explanation": "这里应该用〈建筑〉。学科、专业说“建筑”，建筑物指具体的房屋、桥梁等实体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建筑物", "is_correct": true, "explanation": "正确。“盖”的对象是房屋、大楼一类的建筑，与“五十年前盖的”相合。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“盖”用于房屋、楼房等建筑，不能说“盖玩具”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是创作出来的，不是盖起来的，与“五十年前盖的”冲突。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木是栽种或生长出来的，不是盖起来的，与“盖的”冲突。"}], "explanations": {"建筑物": "正确。“盖”的对象是房屋、大楼一类的建筑，与“五十年前盖的”相合。", "玩具": "搭配：“盖”用于房屋、楼房等建筑，不能说“盖玩具”。", "歌曲": "语义：歌曲是创作出来的，不是盖起来的，与“五十年前盖的”冲突。", "树木": "语义：树木是栽种或生长出来的，不是盖起来的，与“盖的”冲突。"}, "sentence_index": 6, "correct_answer": "建筑物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个有趣的建筑物。", "explanation": "这里应该用〈人物〉。“人物”可指有名的人或作品中的角色；建筑物是房屋、桥梁等，不能指人。"}, {"text": "我买了一把建筑物。", "explanation": "这里应该用〈座〉。建筑物的量词是座；“把”多用于有柄或可手持的器物，不能用来数建筑物。"}, {"text": "他每天读一本建筑物。", "explanation": "这里应该用〈书〉。读的是书、报纸等文字材料，建筑物不能读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上有一只高大的建筑物。", "corrected_sentence": "街上有一座高大的建筑物。", "error_description": "错误：量词“只”用于动物，建筑物应该用量词“座”。正确说法是“一座高大的建筑物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条建筑物是几年前才装修的。", "corrected_sentence": "那座建筑物是几年前才装修的。", "error_description": "错误：建筑物的量词用“座”，不用“条”（“条”用于细长的东西）。正确说法是“那座建筑物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
