INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人工建造的房屋、桥梁、塔等物体的统称。", "primary_collocate": null, "pronunciation": "jiàn zhù wù", "ipa": "tɕjɛn˥˩ ʈʂu˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "房子、桥和塔都是建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的塔是一种有名的建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是城里最老的建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的建筑物有桥，也有亭子。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客来这里看古老的建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建筑物的种类很多。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要保护这些历史建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城是世界有名的建筑物。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园里的建筑物不能随便爬。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢拍各种建筑物的照片。", "target_word": "建筑物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "建築物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "房屋、桥梁、塔等各类人工建造物的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建筑物", "is_correct": true, "explanation": "正确。“是……的”后的类别指人工建造的房屋、桥梁、塔等。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物是生长出来的，不是人工建造的，与“房子、桥和塔”的类别不合。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“房子、桥和塔”与“工具”不属于同一类，说“都是工具”不成立。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物供人吃，房子、桥和塔不属于食物。"}], "explanations": {"建筑物": "正确。“是……的”后的类别指人工建造的房屋、桥梁、塔等。", "植物": "语义：植物是生长出来的，不是人工建造的，与“房子、桥和塔”的类别不合。", "工具": "搭配：“房子、桥和塔”与“工具”不属于同一类，说“都是工具”不成立。", "食物": "语义：食物供人吃，房子、桥和塔不属于食物。"}, "sentence_index": 0, "correct_answer": "建筑物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公园里有一棵建筑物，很高。", "explanation": "这里应该用〈座〉。“棵”用于树木，建筑物的量词是座。"}, {"text": "这片田野里有一束建筑物。", "explanation": "这里应该用〈座〉。“束”用于成把的花草等，不能用来数建筑物。"}, {"text": "他是我们班一位有名的建筑物。", "explanation": "这里应该用〈人物〉。“人物”可指有名的人；建筑物是房屋、桥梁等实体，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建筑物", "is_correct": true, "explanation": "正确。“保护”的对象是历史遗存，如古建筑，与“历史”相合。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是需要保护的历史遗存，与“历史”和“保护”都冲突。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是需要保护的历史遗存，与“历史”和“保护”都冲突。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是人造的历史遗存，与“历史”和“保护”都冲突。"}], "explanations": {"建筑物": "正确。“保护”的对象是历史遗存，如古建筑，与“历史”相合。", "垃圾": "语义：垃圾不是需要保护的历史遗存，与“历史”和“保护”都冲突。", "汽油": "语义：汽油是燃料，不是需要保护的历史遗存，与“历史”和“保护”都冲突。", "月亮": "语义：月亮是天体，不是人造的历史遗存，与“历史”和“保护”都冲突。"}, "sentence_index": 6, "correct_answer": "建筑物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家门口有一条建筑物。", "explanation": "这里应该用〈座〉。建筑物的量词是座，“条”用于细长的东西。"}, {"text": "建筑物是一门科学。", "explanation": "这里应该用〈建筑学〉。作为学科要说“建筑学”；建筑物指房屋、桥梁等实体，不能当作学科。"}, {"text": "他是一名建筑物工人。", "explanation": "这里应该用〈建筑工人〉。修饰工人要说“建筑”，建筑物指房屋、桥梁等实体，不能用来修饰工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座塔是一条很有名的建筑物。", "corrected_sentence": "这座塔是一座很有名的建筑物。", "error_description": "错误：建筑物的量词用“座”，不用“条”。正确说法是“一座很有名的建筑物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家附近有一座古老的建筑物们。", "corrected_sentence": "我家附近有一座古老的建筑物。", "error_description": "错误：“建筑物”是非生命名词，后面不能加复数后缀“们”。正确说法是“一座古老的建筑物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
