INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93415, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "兑换是用一种钱换成另一种钱。", "primary_collocate": null, "pronunciation": "duì huàn", "ipa": "twei̯˥˩ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "我要把人民币兑换成港币。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行能兑换二十多种外币。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈昨天兑换了两千日元。", "target_word": "兑换", "complexity_tier": "T3", "furigana": "mā ma zuó tiān duì huàn le liǎng qiān rì yuán", "sentence_source": "generated"}, {"text": "去泰国旅游前，我兑换了一些泰铢。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兑换外币要带护照。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天一美元能兑换七块人民币。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有兑换过欧元，不知道怎么办。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在银行排队兑换美元。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想兑换一些日元，可以吗？", "target_word": "兑换", "complexity_tier": "T3", "furigana": "wǒ xiǎng duì huàn yì xiē rì yuán kě yǐ ma", "sentence_source": "generated"}, {"text": "汇率低的时候，我不想兑换英镑。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兑换了", "label": "完成体"}, {"form": "兑换过", "label": "经历体"}, {"form": "兌換", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把一种钱换成另一种钱；人民币、美元等货币互换", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兑换", "is_correct": true, "explanation": "兑换：把人民币换成港币，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清洁房间，与货币互换无关。"}, {"text": "复习", "is_correct": false, "explanation": "语义：“复习”指学习功课，不能表示换成另一种货币。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”不带宾语，不能说“把人民币唱歌成港币”。"}], "explanations": {"兑换": "兑换：把人民币换成港币，符合句意。", "打扫": "语义：“打扫”指清洁房间，与货币互换无关。", "复习": "语义：“复习”指学习功课，不能表示换成另一种货币。", "唱歌": "搭配：“唱歌”不带宾语，不能说“把人民币唱歌成港币”。"}, "sentence_index": 0, "correct_answer": "兑换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把旧椅子兑换成了新的。", "explanation": "这里应该用〈换〉。兑换只用于一种钱换成另一种钱，不用于换家具。"}, {"text": "我和朋友兑换了电话号码。", "explanation": "这里应该用〈交换〉。兑换不用于交换电话号码这类信息。"}, {"text": "我向同学兑换了一支笔。", "explanation": "这里应该用〈借〉。兑换是换成另一种钱，不表示借东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兑换", "is_correct": true, "explanation": "兑换过：没有兑换过欧元，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清洁，与欧元无关。"}, {"text": "锻炼", "is_correct": false, "explanation": "语义：“锻炼”指运动健身，不能以货币作宾语。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”不带宾语，不能说“洗澡过欧元”。"}], "explanations": {"兑换": "兑换过：没有兑换过欧元，符合句意。", "打扫": "语义：“打扫”指清洁，与欧元无关。", "锻炼": "语义：“锻炼”指运动健身，不能以货币作宾语。", "洗澡": "搭配：“洗澡”不带宾语，不能说“洗澡过欧元”。"}, "sentence_index": 6, "correct_answer": "兑换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈兑换给我一条围巾。", "explanation": "这里应该用〈送〉。兑换不用于赠送物品。"}, {"text": "他从柜台兑换了一张表格。", "explanation": "这里应该用〈拿〉。兑换只用于把一种钱换成另一种钱，不用于拿表格。"}, {"text": "师傅兑换好了自行车。", "explanation": "这里应该用〈修〉。兑换不用于修理物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想这些港币兑换成人民币。", "corrected_sentence": "我想把这些港币兑换成人民币。", "error_description": "错误在“把”字的漏用。处置对象“这些港币”前要用“把”，应说“把这些港币兑换成人民币”，不能说“这些港币兑换成人民币”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没兑换了日元，不太懂汇率。", "corrected_sentence": "我还没兑换过日元，不太懂汇率。", "error_description": "错误在动态助词。表示还没有经历过某事时用“没……过”，不说“没……了”，应说“还没兑换过日元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
