INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93416, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用一种货币或票证换取另一种。", "primary_collocate": null, "pronunciation": "duì huàn", "ipa": "twei̯˥˩ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "我想把一千元人民币兑换成美元。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问在哪儿可以兑换外币？", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行今天兑换日元的汇率很高。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场兑换了五百欧元。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张礼券可以兑换一杯咖啡。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "积分满一百分就能兑换小礼物。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国以前，我去银行兑换过美元。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着优惠券来兑换礼物。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅客在酒店兑换当地货币。", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问你要兑换多少钱？", "target_word": "兑换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兑换了", "label": "完成体"}, {"form": "兑换过", "label": "经历体"}, {"form": "兌換", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用一种货币或票证换取另一种；外币、礼券、积分等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兑换", "is_correct": true, "explanation": "兑换：用人民币换成美元，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清洁，不表示把一种货币换成另一种。"}, {"text": "复习", "is_correct": false, "explanation": "语义：“复习”指学习功课，与货币无关。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不带宾语，不能与“成美元”搭配。"}], "explanations": {"兑换": "兑换：用人民币换成美元，符合句意。", "打扫": "语义：“打扫”指清洁，不表示把一种货币换成另一种。", "复习": "语义：“复习”指学习功课，与货币无关。", "游泳": "搭配：“游泳”不带宾语，不能与“成美元”搭配。"}, "sentence_index": 0, "correct_answer": "兑换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于兑换了自己的承诺。", "explanation": "这里应该用〈兑现〉。兑换指用货币或票证换成另一种，兑现指实现承诺，不能说兑换承诺。"}, {"text": "同学们在课堂上兑换了名片。", "explanation": "这里应该用〈交换〉。兑换不用于人与人之间交换物品。"}, {"text": "他在聚会上兑换了一个新朋友。", "explanation": "这里应该用〈结交〉。兑换不用于交朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兑换", "is_correct": true, "explanation": "兑换过：去银行换过美元，符合“出国以前”的句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与去银行办理货币业务无关。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”不带宾语，不能说“洗澡过美元”。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与银行货币业务无关。"}], "explanations": {"兑换": "兑换过：去银行换过美元，符合“出国以前”的句意。", "唱歌": "语义：“唱歌”与去银行办理货币业务无关。", "洗澡": "搭配：“洗澡”不带宾语，不能说“洗澡过美元”。", "跳舞": "语义：“跳舞”与银行货币业务无关。"}, "sentence_index": 6, "correct_answer": "兑换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天兑换了一封信。", "explanation": "这里应该用〈收到〉。兑换表示用货币或票证换取，不表示接收。"}, {"text": "他把自行车兑换成了一顿饭。", "explanation": "这里应该用〈换〉。兑换只用于货币或票证，不用于物物交换。"}, {"text": "他把包裹兑换给了妈妈。", "explanation": "这里应该用〈寄〉。兑换不用于寄送物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我要这些美元兑换成日元。", "corrected_sentence": "我要把这些美元兑换成日元。", "error_description": "错误在“把”字的漏用。处置对象“这些美元”前要用“把”，应说“把这些美元兑换成日元”，不能说“这些美元兑换成日元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没兑换了英镑，不太清楚手续。", "corrected_sentence": "我从来没兑换过英镑，不太清楚手续。", "error_description": "错误在动态助词。否定经历要用“没……过”，不能用“了”，应说“没兑换过英镑”，不说“没兑换了英镑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
