INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93417, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打造是用心把东西做出来，做得很好。", "primary_collocate": null, "pronunciation": "dǎ zào", "ipa": "ta˨˩ tsau˥˩", "syllable_count": 2, "sentences": [{"text": "她用心打造了一间小书房。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸为我打造了一张小书桌。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想打造一家舒服的咖啡店。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了三年打造这个公园。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团队想打造最好的游戏。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把家打造得很温暖。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要打造一个让孩子开心的地方。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位厨师打造了一道新菜。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐正在打造自己的小公司。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起打造了一个漂亮的校园。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打造了", "label": "体标"}, {"form": "打造着", "label": "体标"}, {"form": "打造过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用心把东西或地方做出来并做得很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93417, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打造", "is_correct": true, "explanation": "正确答案：打造，指用心做出东西并做得很好。"}, {"text": "打到", "is_correct": false, "explanation": "dǎ dào 与 dǎ zào 只有第二个音节声母不同（d 与 z），意思是击中、够到。"}, {"text": "打枣", "is_correct": false, "explanation": "dǎ zǎo 只有第二个音节的声调不同（第三声），意思是把枣从树上打下来。"}, {"text": "大灶", "is_correct": false, "explanation": "dà zào 第一个音节为第四声（dà），与 dǎ（第三声）声调不同，意思是大灶台。"}], "explanations": {"打造": "正确答案：打造，指用心做出东西并做得很好。", "打到": "dǎ dào 与 dǎ zào 只有第二个音节声母不同（d 与 z），意思是击中、够到。", "打枣": "dǎ zǎo 只有第二个音节的声调不同（第三声），意思是把枣从树上打下来。", "大灶": "dà zào 第一个音节为第四声（dà），与 dǎ（第三声）声调不同，意思是大灶台。"}, "sentence_index": null, "correct_answer": "打造"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：「扔」是丢弃，与「用心」做东西的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语不能是房间，「吃了一间小书房」不成立。"}, {"text": "打造", "is_correct": true, "explanation": "正确：「打造」表示用心做出东西，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能以「书房」为宾语，「唱了一间小书房」不成立。"}], "explanations": {"扔": "语义：「扔」是丢弃，与「用心」做东西的语境相反。", "吃": "搭配：「吃」的宾语不能是房间，「吃了一间小书房」不成立。", "打造": "正确：「打造」表示用心做出东西，与句意相符。", "唱": "搭配：「唱」不能以「书房」为宾语，「唱了一间小书房」不成立。"}, "sentence_index": 0, "correct_answer": "打造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨打造了一条河。", "explanation": "这里应该用〈冲出〉。河是雨水冲出来的，属于自然形成，打造指人精心做出东西，不能用于自然现象。"}, {"text": "他的话打造了误会。", "explanation": "这里应该用〈引起〉。打造是做出好的东西，误会这类负面结果要用引起。"}, {"text": "他在会议上打造了混乱。", "explanation": "这里应该用〈制造〉。打造指精心做出好的东西，混乱这类负面结果要用制造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93417, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打造", "is_correct": true, "explanation": "正确答案：打造，指用心做出东西并做得很好。"}, {"text": "打闹", "is_correct": false, "explanation": "dǎ nào 第二个音节声母不同（n 与 z），意思是嬉闹、打闹。"}, {"text": "大早", "is_correct": false, "explanation": "dà zǎo 两个音节的声调都与 dǎ zào 不同，意思是大清早。"}, {"text": "打药", "is_correct": false, "explanation": "dǎ yào 第二个音节声母不同（y 与 z），意思是喷洒农药。"}], "explanations": {"打造": "正确答案：打造，指用心做出东西并做得很好。", "打闹": "dǎ nào 第二个音节声母不同（n 与 z），意思是嬉闹、打闹。", "大早": "dà zǎo 两个音节的声调都与 dǎ zào 不同，意思是大清早。", "打药": "dǎ yào 第二个音节声母不同（y 与 z），意思是喷洒农药。"}, "sentence_index": null, "correct_answer": "打造"}, "level_3": {"options": [{"text": "毁", "is_correct": false, "explanation": "语义：「毁」是破坏，与「让孩子开心」的目的相反。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」是拆除，不能用来形容为孩子营造快乐的地方。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：「咬」不能以「地方」为宾语，句子不成立。"}, {"text": "打造", "is_correct": true, "explanation": "正确：「打造」表示用心做出一个地方，与句意相符。"}], "explanations": {"毁": "语义：「毁」是破坏，与「让孩子开心」的目的相反。", "拆": "语义：「拆」是拆除，不能用来形容为孩子营造快乐的地方。", "咬": "搭配：「咬」不能以「地方」为宾语，句子不成立。", "打造": "正确：「打造」表示用心做出一个地方，与句意相符。"}, "sentence_index": 6, "correct_answer": "打造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打造了一杯热水。", "explanation": "这里应该用〈倒〉。打造指精心做出东西，倒水要用倒。"}, {"text": "他打造了一声叹息。", "explanation": "这里应该用〈发出〉。打造指用心做出东西或地方，叹息这类声音要用发出。"}, {"text": "她打造了一个鸡蛋。", "explanation": "这里应该用〈煎〉。打造指做出器物，煎鸡蛋要用煎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐把阳台打造很漂亮。", "corrected_sentence": "姐姐把阳台打造得很漂亮。", "error_description": "错误：缺少补语标记「得」。正确：「打造得很漂亮」，表示程度的补语要用「得」连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把这栋老楼打造得书店。", "corrected_sentence": "我们要把这栋老楼打造成书店。", "error_description": "错误：补语「成」误写为「得」。正确：「打造成书店」，「成」表示变为某种事物，「得」只用于表示程度或情态，不能表示变为。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
