INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93418, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制造；经过精心设计和加工而创造出来。", "primary_collocate": null, "pronunciation": "dǎ zào", "ipa": "ta˨˩ tsau˥˩", "syllable_count": 2, "sentences": [{"text": "工人用铁打造了一把刀。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想亲手打造一张桌子。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司打造了一款新手机。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅打造的银手镯非常漂亮。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要打造一条新船。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用心打造自己的小店。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老城想打造成旅游城市。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在打造一个新品牌。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位师傅打造过很多把好剑。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅把铁一点一点打造成刀。", "target_word": "打造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打造了", "label": "体标"}, {"form": "打造着", "label": "体标"}, {"form": "打造过", "label": "体标"}], "register": "中性", "sense_fingerprint": "精心设计加工，制造出东西或品牌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打造", "is_correct": true, "explanation": "正确答案：打造，指精心加工、制造出东西。"}, {"text": "打到", "is_correct": false, "explanation": "dǎ dào 与 dǎ zào 只有第二个音节声母不同（d 与 z），意思是击中、够到。"}, {"text": "大灶", "is_correct": false, "explanation": "dà zào 第一个音节为第四声（dà），与 dǎ（第三声）声调不同，意思是大灶台。"}, {"text": "打闹", "is_correct": false, "explanation": "dǎ nào 第二个音节声母不同（n 与 z），意思是嬉闹、打闹。"}, {"text": "大早", "is_correct": false, "explanation": "dà zǎo 两个音节的声调都与 dǎ zào 不同，意思是大清早。"}], "explanations": {"打造": "正确答案：打造，指精心加工、制造出东西。", "打到": "dǎ dào 与 dǎ zào 只有第二个音节声母不同（d 与 z），意思是击中、够到。", "大灶": "dà zào 第一个音节为第四声（dà），与 dǎ（第三声）声调不同，意思是大灶台。", "打闹": "dǎ nào 第二个音节声母不同（n 与 z），意思是嬉闹、打闹。", "大早": "dà zǎo 两个音节的声调都与 dǎ zào 不同，意思是大清早。"}, "sentence_index": null, "correct_answer": "打造"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "搭配：「写」的宾语应是文字，不能说「写一把刀」。"}, {"text": "打造", "is_correct": true, "explanation": "正确：「打造」表示用铁加工制成刀，与句意相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：「卖」指出售，与句中用铁制作刀具的过程不符。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：「砍」的宾语是可以被砍的东西，刀是制成品，不能说「砍了一把刀」。"}], "explanations": {"写": "搭配：「写」的宾语应是文字，不能说「写一把刀」。", "打造": "正确：「打造」表示用铁加工制成刀，与句意相符。", "卖": "语义：「卖」指出售，与句中用铁制作刀具的过程不符。", "砍": "搭配：「砍」的宾语是可以被砍的东西，刀是制成品，不能说「砍了一把刀」。"}, "sentence_index": 0, "correct_answer": "打造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工地打造了很多噪音。", "explanation": "这里应该用〈制造〉。打造指精心加工、做出好的东西，噪音这类负面结果要用制造。"}, {"text": "他每天打造一次咳嗽。", "explanation": "这里应该用〈咳〉。咳嗽是身体的反应，不是人精心做出的东西，打造不能这样用。"}, {"text": "他打造好了我的作业。", "explanation": "这里应该用〈做〉。打造指精心做出器物，做作业要用做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93418, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打造", "is_correct": true, "explanation": "正确答案：打造，指精心加工、制造出东西。"}, {"text": "打药", "is_correct": false, "explanation": "dǎ yào 第二个音节声母不同（y 与 z），意思是喷洒农药。"}, {"text": "打枣", "is_correct": false, "explanation": "dǎ zǎo 只有第二个音节的声调不同（第三声），意思是把枣从树上打下来。"}, {"text": "大枣", "is_correct": false, "explanation": "dà zǎo 两个音节的声调都与 dǎ zào 不同，意思是枣子。"}], "explanations": {"打造": "正确答案：打造，指精心加工、制造出东西。", "打药": "dǎ yào 第二个音节声母不同（y 与 z），意思是喷洒农药。", "打枣": "dǎ zǎo 只有第二个音节的声调不同（第三声），意思是把枣从树上打下来。", "大枣": "dà zǎo 两个音节的声调都与 dǎ zào 不同，意思是枣子。"}, "sentence_index": null, "correct_answer": "打造"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能与「成……城市」构成变为的结构，「吃成旅游城市」不成立。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」是拆除，与「想……成旅游城市」的发展方向相反。"}, {"text": "打造", "is_correct": true, "explanation": "正确：「打造成」表示经过精心建设变为某种样子，与句意相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的宾语不能是城市，「喝成」不能表示变为城市。"}], "explanations": {"吃": "搭配：「吃」不能与「成……城市」构成变为的结构，「吃成旅游城市」不成立。", "拆": "语义：「拆」是拆除，与「想……成旅游城市」的发展方向相反。", "打造": "正确：「打造成」表示经过精心建设变为某种样子，与句意相符。", "喝": "搭配：「喝」的宾语不能是城市，「喝成」不能表示变为城市。"}, "sentence_index": 6, "correct_answer": "打造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈打造了一锅粥。", "explanation": "这里应该用〈煮〉。打造指精心加工做出东西，做饭、煮粥要用煮。"}, {"text": "他打造了一个错误。", "explanation": "这里应该用〈犯〉。打造是做出好东西，犯错误要用犯。"}, {"text": "他打造了一个笑话。", "explanation": "这里应该用〈讲〉。打造指做出器物，讲笑话要用讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年打造了过一把银剑。", "corrected_sentence": "他去年打造过一把银剑。", "error_description": "错误：「打造」后同时用了「了」和「过」。正确：「打造过」。「过」表示曾经有过这种经历，不能与「了」并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店要把旧仓库打造得咖啡馆。", "corrected_sentence": "这家店要把旧仓库打造成咖啡馆。", "error_description": "错误：补语误用「得」代替「成」。正确：「打造成咖啡馆」，「成」表示变为某种事物，「得」只接表示程度或情态的补语，不能表示变为。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
