INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93419, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内裤是穿在里面的小裤子。", "primary_collocate": null, "pronunciation": "nèi kù", "ipa": "nei˥˩ kʰu˥˩", "syllable_count": 2, "sentences": [{"text": "他每天早上都换一条干净的内裤。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在商店给弟弟买了三条内裤。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新买的内裤放进了抽屉里。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把内裤洗干净了，挂在外面。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时别忘了带几条内裤。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条内裤是白色的，很舒服。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的内裤上有一只小熊。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内裤太小了，穿着不舒服。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天出汗多，内裤要天天换。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子自己穿好了内裤和裤子。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "三角内裤", "label": "复合"}, {"form": "內褲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "穿在里面的小裤子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内裤", "is_correct": true, "explanation": "内裤是贴身穿在里面的小裤子，每天早上换的正是这类贴身衣物。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是贴身衣物，每天早上换书包不合常理。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不会每天早上更换，与“每天早上都换”矛盾。"}, {"text": "大米", "is_correct": false, "explanation": "搭配：量词“条”不用于大米，“换一条干净的大米”不成立。"}], "explanations": {"内裤": "内裤是贴身穿在里面的小裤子，每天早上换的正是这类贴身衣物。", "书包": "语义：书包不是贴身衣物，每天早上换书包不合常理。", "窗帘": "语义：窗帘不会每天早上更换，与“每天早上都换”矛盾。", "大米": "搭配：量词“条”不用于大米，“换一条干净的大米”不成立。"}, "sentence_index": 0, "correct_answer": "内裤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，他把内裤穿在外面挡雨。", "explanation": "这里应该用〈雨衣〉。内裤是贴身穿在里面的小裤子，不能穿在外面挡雨。"}, {"text": "她穿着一条漂亮的内裤去参加婚礼。", "explanation": "这里应该用〈裙子〉。内裤是贴身穿在里面的，不能当外穿的裙子。"}, {"text": "他穿着一条白内裤去开会，很精神。", "explanation": "这里应该用〈衬衫〉。内裤是贴身衣物，不能当外衣穿到会议上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内裤", "is_correct": true, "explanation": "内裤可以印有图案，“他的内裤上有一只小熊”自然合理。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有表面，不能说“上有一只小熊”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听到的东西，不能在上面画图案。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“上有一只小熊”一般说物品的表面，不说眼睛上有小熊。"}], "explanations": {"内裤": "内裤可以印有图案，“他的内裤上有一只小熊”自然合理。", "空气": "语义：空气没有表面，不能说“上有一只小熊”。", "声音": "语义：声音是听到的东西，不能在上面画图案。", "眼睛": "搭配：“上有一只小熊”一般说物品的表面，不说眼睛上有小熊。"}, "sentence_index": 6, "correct_answer": "内裤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在商店买了一只内裤，很软。", "explanation": "这里应该用〈条〉。“只”指动物或成对物品中的一个（如一只鞋），内裤不用“只”，要用“条”。"}, {"text": "妈妈给我织了一顶内裤，很暖和。", "explanation": "这里应该用〈条〉。“顶”用于帽子等物品，内裤不用“顶”。"}, {"text": "抽屉里放着一根内裤，我找了很久。", "explanation": "这里应该用〈条〉。“根”用于细长的东西，内裤要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天给弟弟买了两只内裤。", "corrected_sentence": "我昨天给弟弟买了两条内裤。", "error_description": "量词错误：“内裤”应使用量词“条”，不能用“只”。应改为“两条内裤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他换上了一双新内裤。", "corrected_sentence": "他换上了一条新内裤。", "error_description": "量词错误：「内裤」是成条的贴身衣物，量词应用“条”，不能用“双”（“双”指成对的东西）。应改为“一条新内裤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
