INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "贴身穿在里面的短裤。", "primary_collocate": null, "pronunciation": "nèi kù", "ipa": "nei˥˩ kʰu˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸给我买了两条内裤，都是纯棉的。", "target_word": "内裤", "complexity_tier": "T3", "furigana": "bàba gěi wǒ mǎi le liǎng tiáo nèikù, dōu shì chúnmián de.", "sentence_source": "generated"}, {"text": "运动时他喜欢穿软一点的内裤。", "target_word": "内裤", "complexity_tier": "T3", "furigana": "yùndòng shí tā xǐhuan chuān ruǎn yìdiǎn de nèikù.", "sentence_source": "generated"}, {"text": "内裤要贴身穿，所以要选软的。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的内裤放在衣柜最下面。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把内裤和袜子放在一个袋子里。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内裤脏了就要马上换。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的内裤很便宜，一条十块。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他洗澡后换了一条新内裤。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天他在内裤外面穿了秋裤。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种内裤又软又薄，我很喜欢。", "target_word": "内裤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "平角内裤", "label": "复合"}, {"form": "內褲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "贴身穿的短裤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内裤", "is_correct": true, "explanation": "内裤是贴身穿的短裤，爸爸买来的两条内裤是纯棉的，语境吻合。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是织物，不能说是纯棉的。"}, {"text": "蛇", "is_correct": false, "explanation": "语义：蛇不是织物，“都是纯棉的”无法用于蛇。"}, {"text": "河", "is_correct": false, "explanation": "搭配：“纯棉的”修饰织物，不说河是纯棉的。"}], "explanations": {"内裤": "内裤是贴身穿的短裤，爸爸买来的两条内裤是纯棉的，语境吻合。", "鱼": "语义：鱼不是织物，不能说是纯棉的。", "蛇": "语义：蛇不是织物，“都是纯棉的”无法用于蛇。", "河": "搭配：“纯棉的”修饰织物，不说河是纯棉的。"}, "sentence_index": 0, "correct_answer": "内裤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天冷了，他戴上内裤出门。", "explanation": "这里应该用〈帽子〉。内裤是贴身穿的短裤，不能戴在头上御寒。"}, {"text": "她穿着一条漂亮的内裤去参加生日派对。", "explanation": "这里应该用〈裙子〉。内裤是贴身衣物，不能当外穿的裙子。"}, {"text": "他穿着一条内裤去开会，很正式。", "explanation": "这里应该用〈西装〉。内裤是贴身穿在里面的，不能当外衣穿去开会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内裤", "is_correct": true, "explanation": "内裤是一件便宜的贴身衣物，“一条十块”说的正是它的价钱。"}, {"text": "钻石", "is_correct": false, "explanation": "量词：钻石以“颗”计，不用“条”，“一条十块”不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不可能只要十块钱，与“很便宜，一条十块”不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子的价钱不可能是一条十块，这种说法在语境中不成立。"}], "explanations": {"内裤": "内裤是一件便宜的贴身衣物，“一条十块”说的正是它的价钱。", "钻石": "量词：钻石以“颗”计，不用“条”，“一条十块”不成立。", "汽车": "语义：汽车不可能只要十块钱，与“很便宜，一条十块”不符。", "房子": "语义：房子的价钱不可能是一条十块，这种说法在语境中不成立。"}, "sentence_index": 6, "correct_answer": "内裤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她从袋子里拿出一双内裤，很薄。", "explanation": "这里应该用〈条〉。“双”指成对的东西，如鞋子、手套，内裤不成对，应用“条”。"}, {"text": "我的抽屉里放着一块内裤。", "explanation": "这里应该用〈条〉。“块”用于块状的东西，内裤要用“条”。"}, {"text": "妈妈给我买了一只内裤。", "explanation": "这里应该用〈条〉。“只”指动物或成对物品中的一个（如一只袜子），内裤不用“只”，要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟穿上了一根新内裤。", "corrected_sentence": "我弟弟穿上了一条新内裤。", "error_description": "量词错误：“内裤”应使用量词“条”，“根”用于细长的东西，不能用于内裤。应改为“一条新内裤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了一条软得内裤，很舒服。", "corrected_sentence": "她买了一条软内裤，很舒服。", "error_description": "结构错误：形容词“软”作定语修饰“内裤”时不能带“得”，应说“软内裤”，不说“软得内裤”。应改为“一条软内裤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
