INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日记是每天把自己做的事和想的事写下来的本子。", "primary_collocate": null, "pronunciation": "rì jì", "ipa": "ʐ̩˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上有一本旧日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的日记有一把小锁。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一本红色的日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把日记放在书包里。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本日记是朋友送我的。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的日记已经写满了。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的日记拿给老师看。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的日记在床下面。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶留着一本五十年前的日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店给姐姐挑了一本日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "篇", "label": "量词"}, {"form": "日记本", "label": "复合"}, {"form": "日記", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来每天写自己所做所想的本子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93421, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日记", "is_correct": true, "explanation": "正确答案：日记，指每天记录做的事和想的事的本子。"}, {"text": "日历", "is_correct": false, "explanation": "rì lì 与 rì jì 只有第二个音节声母不同（l 与 j），意思是日历。"}, {"text": "日益", "is_correct": false, "explanation": "rì yì 与 rì jì 只有第二个音节声母不同（y 与 j），意思是一天比一天。"}, {"text": "日系", "is_correct": false, "explanation": "rì xì 与 rì jì 只有第二个音节声母不同（x 与 j），意思是日本风格。"}, {"text": "易记", "is_correct": false, "explanation": "yì jì 第一个音节声母不同（y 与 r），意思是容易记住。"}], "explanations": {"日记": "正确答案：日记，指每天记录做的事和想的事的本子。", "日历": "rì lì 与 rì jì 只有第二个音节声母不同（l 与 j），意思是日历。", "日益": "rì yì 与 rì jì 只有第二个音节声母不同（y 与 j），意思是一天比一天。", "日系": "rì xì 与 rì jì 只有第二个音节声母不同（x 与 j），意思是日本风格。", "易记": "yì jì 第一个音节声母不同（y 与 r），意思是容易记住。"}, "sentence_index": null, "correct_answer": "日记"}, "level_3": {"options": [{"text": "笔", "is_correct": false, "explanation": "搭配：量词「本」不能用于「笔」，「一本旧笔」不成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「本」指书册，石头不是可以用「本」计量的书册，句意不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：「太阳」不是书册，「一本旧太阳」不成立。"}, {"text": "日记", "is_correct": true, "explanation": "正确：「一本旧日记」指放在桌上的旧本子，与句意相符。"}], "explanations": {"笔": "搭配：量词「本」不能用于「笔」，「一本旧笔」不成立。", "石头": "语义：「本」指书册，石头不是可以用「本」计量的书册，句意不通。", "太阳": "语义：「太阳」不是书册，「一本旧太阳」不成立。", "日记": "正确：「一本旧日记」指放在桌上的旧本子，与句意相符。"}, "sentence_index": 0, "correct_answer": "日记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在日记里查单词。", "explanation": "这里应该用〈字典〉。查单词要用字典，日记是记录个人经历和感想的本子。"}, {"text": "他每天早上用日记刷牙。", "explanation": "这里应该用〈牙刷〉。刷牙要用牙刷，日记是写字的本子。"}, {"text": "下雨了，他撑着日记出门。", "explanation": "这里应该用〈雨伞〉。下雨撑的是雨伞，日记是写字的本子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影子", "is_correct": false, "explanation": "语义：影子是光照形成的暗影，无法「拿给老师看」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能拿给老师看。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「拿」的宾语不能是身高，「拿给老师看」不成立。"}, {"text": "日记", "is_correct": true, "explanation": "正确：「把你的日记拿给老师看」符合句意，日记可以拿给老师看。"}], "explanations": {"影子": "语义：影子是光照形成的暗影，无法「拿给老师看」。", "天气": "语义：天气是自然现象，不能拿给老师看。", "身高": "搭配：「拿」的宾语不能是身高，「拿给老师看」不成立。", "日记": "正确：「把你的日记拿给老师看」符合句意，日记可以拿给老师看。"}, "sentence_index": 6, "correct_answer": "日记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在日记里付了一笔钱。", "explanation": "这里应该用〈支票〉。付钱要用现金或支票，日记不能作为付款凭证。"}, {"text": "他用日记切了一块面包。", "explanation": "这里应该用〈刀〉。切面包要用刀，日记是写字的本子。"}, {"text": "医生开了一份日记。", "explanation": "这里应该用〈药方〉。医生开的是药方，日记不是医生开的凭证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她书架上放着一封新日记。", "corrected_sentence": "她书架上放着一本新日记。", "error_description": "错误：「日记」的量词用错了。正确：「一本新日记」，「封」用于信件，不能用于日记。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
