INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "每天记录经历、感想的文字或本子。", "primary_collocate": null, "pronunciation": "rì jì", "ipa": "ʐ̩˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "我每天晚上写日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的日记里写了很多心事。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇日记写得很好。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天忘了写日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把今天的事写进了日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的日记我还留着。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们每周写一篇日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在日记中写下自己的想法。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不让别人看他的日记。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在日记里记下了这次旅行。", "target_word": "日记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}, {"form": "本", "label": "量词"}, {"form": "日记本", "label": "复合"}, {"form": "日記", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每天记录经历和感想的文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va