INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日记", "is_correct": true, "explanation": "正确答案：日记，指每天记录经历和感想的文字或本子。"}, {"text": "日历", "is_correct": false, "explanation": "rì lì 与 rì jì 只有第二个音节声母不同（l 与 j），意思是日历。"}, {"text": "日益", "is_correct": false, "explanation": "rì yì 与 rì jì 只有第二个音节声母不同（y 与 j），意思是一天比一天。"}, {"text": "日系", "is_correct": false, "explanation": "rì xì 与 rì jì 只有第二个音节声母不同（x 与 j），意思是日本风格。"}], "explanations": {"日记": "正确答案：日记，指每天记录经历和感想的文字或本子。", "日历": "rì lì 与 rì jì 只有第二个音节声母不同（l 与 j），意思是日历。", "日益": "rì yì 与 rì jì 只有第二个音节声母不同（y 与 j），意思是一天比一天。", "日系": "rì xì 与 rì jì 只有第二个音节声母不同（x 与 j），意思是日本风格。"}, "sentence_index": null, "correct_answer": "日记"}, "level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "搭配：「写」的宾语是文字，「写饭」不成立。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：「写」不能以「房子」为宾语，「写房子」不成立。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：「太阳」不是可以书写的内容，句意不通。"}, {"text": "日记", "is_correct": true, "explanation": "正确：「写日记」是常见搭配，与「每天晚上」的习惯相符。"}], "explanations": {"饭": "搭配：「写」的宾语是文字，「写饭」不成立。", "房子": "搭配：「写」不能以「房子」为宾语，「写房子」不成立。", "太阳": "语义：「太阳」不是可以书写的内容，句意不通。", "日记": "正确：「写日记」是常见搭配，与「每天晚上」的习惯相符。"}, "sentence_index": 0, "correct_answer": "日记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天把日记做成一道菜。", "explanation": "这里应该用〈食谱〉。日记是记录经历和感想的本子，不能变成菜品，做菜要照着食谱。"}, {"text": "店主在日记上盖了公章。", "explanation": "这里应该用〈文件〉。盖公章用于正式文件，日记是个人记录，不能盖公章。"}, {"text": "天冷了，我把日记穿在身上。", "explanation": "这里应该用〈衣服〉。穿在身上的是衣服，日记是记录经历和感想的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信", "is_correct": false, "explanation": "搭配：量词「篇」用于文章，信要用「封」，不能说「一篇信」。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：歌曲用量词「首」，「篇」不能用于歌曲。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用来「写」，「写一篇石头」不成立。"}, {"text": "日记", "is_correct": true, "explanation": "正确：「写一篇日记」符合量词和动词的搭配，与句意相符。"}], "explanations": {"信": "搭配：量词「篇」用于文章，信要用「封」，不能说「一篇信」。", "歌曲": "搭配：歌曲用量词「首」，「篇」不能用于歌曲。", "石头": "语义：石头不能用来「写」，「写一篇石头」不成立。", "日记": "正确：「写一篇日记」符合量词和动词的搭配，与句意相符。"}, "sentence_index": 6, "correct_answer": "日记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司签了一份日记。", "explanation": "这里应该用〈合同〉。签合同是双方达成协议，日记是个人记录，不能签。"}, {"text": "店员开了一份日记。", "explanation": "这里应该用〈收据〉。店员开的是收据，日记是个人记录，不能开。"}, {"text": "警察做了一份日记。", "explanation": "这里应该用〈笔录〉。警察做的是笔录，日记是个人写的本子，不能这样做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她昨天写了一首日记。", "corrected_sentence": "她昨天写了一篇日记。", "error_description": "错误：「日记」的量词用错了。正确：「一篇日记」，「首」用于诗歌、歌曲，不能用于日记。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坚持每天把写日记。", "corrected_sentence": "他坚持每天写日记。", "error_description": "错误：「把」字用错。「把」后应先出现宾语再接动词，「把写日记」中「把」后直接是动词，不成立。正确：「坚持每天写日记」，去掉「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
