INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93423, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全才是样样都会，什么都做得好的人。", "primary_collocate": null, "pronunciation": "quán cái", "ipa": "tɕʰɥɛn³⁵ tsʰai³⁵", "syllable_count": 2, "sentences": [{"text": "他是个全才，唱歌、画画、写作都很好。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王是我们班的全才，什么都会。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说她是公司里的全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想做全才，要学很多东西。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会修车，也会做饭，真是个全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教语文，也教音乐，是个全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是全才，但是数学很好。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时是村里有名的全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一位全才来做这个工作。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想成为一个全才，所以什么都学。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "全才：样样都会、样样做得好的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6f10e89-3216-45ca-a1f0-6c5d9749bac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全才", "is_correct": true, "explanation": "“全才”指样样都会的人，与“唱歌、画画、写作都很好”相合。"}, {"text": "瓶子", "is_correct": false, "explanation": "语义：“瓶子”是器物，不能指人，句子说的是人的才能。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”是用具，不指人，与“唱歌、画画、写作都很好”的描述矛盾。"}, {"text": "全科", "is_correct": false, "explanation": "搭配：“全科”多指全科医生或学科，不指一个人的多方面才能。"}], "explanations": {"全才": "“全才”指样样都会的人，与“唱歌、画画、写作都很好”相合。", "瓶子": "语义：“瓶子”是器物，不能指人，句子说的是人的才能。", "工具": "语义：“工具”是用具，不指人，与“唱歌、画画、写作都很好”的描述矛盾。", "全科": "搭配：“全科”多指全科医生或学科，不指一个人的多方面才能。"}, "sentence_index": 0, "correct_answer": "全才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一只全才，什么都会。", "explanation": "这里应该用〈个〉或〈位〉。“只”多用于动物，指人的“全才”应用〈个〉或〈位〉。"}, {"text": "他是一位全才，只会修车。", "explanation": "这里应该用〈专才〉。全才指样样都会，只会修车的人应称〈专才〉，此处说法自相矛盾。"}, {"text": "他是一张全才，什么都会。", "explanation": "这里应该用〈个〉或〈位〉。“张”用于平面的东西，不能用来数“全才”这样的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全才", "is_correct": true, "explanation": "“全才”指样样都会的人，与“他不是……，但是数学很好”的让步语气相合。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，不能用来否定一个人的身份，句意不通。"}, {"text": "全员", "is_correct": false, "explanation": "搭配：“全员”指全体成员，不用来指一个人，与“他”搭配不当。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能用来描述一个人，句意不通。"}], "explanations": {"全才": "“全才”指样样都会的人，与“他不是……，但是数学很好”的让步语气相合。", "数学": "语义：“数学”是学科，不能用来否定一个人的身份，句意不通。", "全员": "搭配：“全员”指全体成员，不用来指一个人，与“他”搭配不当。", "天气": "语义：“天气”是自然现象，不能用来描述一个人，句意不通。"}, "sentence_index": 6, "correct_answer": "全才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一块全才，什么都会。", "explanation": "这里应该用〈个〉或〈位〉。“块”用于块状的东西，不能用来数指人的“全才”。"}, {"text": "他是个全才，只懂合同，别的一概不会。", "explanation": "这里应该用〈专才〉。全才指样样都会，只懂合同、别的一概不会的人只能算〈专才〉，此处与“全才”的意思矛盾。"}, {"text": "他是一头全才，什么都会。", "explanation": "这里应该用〈个〉或〈位〉。“头”多用于牲畜，不能用来数指人的“全才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个很全才，会唱歌，也会画画。", "corrected_sentence": "他是个全才，会唱歌，也会画画。", "error_description": "“很”不能修饰名词“全才”，应直接说“是个全才”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是件全才，会写文章，也会做饭。", "corrected_sentence": "他是个全才，会写文章，也会做饭。", "error_description": "“件”用于物品，不能用来数指人的“全才”，应改为量词“个”或“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
