INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "各方面都有才能的人。", "primary_collocate": null, "pronunciation": "quán cái", "ipa": "tɕʰɥɛn³⁵ tsʰai³⁵", "syllable_count": 2, "sentences": [{"text": "这个孩子是个全才，学习和运动都很好。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她既会唱歌，又会做饭，还懂电脑，是个全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想找一位懂技术、会管理的全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们家，哥哥是真正的全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小学习好又会弹琴，大家叫他全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做一个全才很不容易，要花很多时间。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队里的他既能进攻又能防守，是个全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生又会看病又会做研究，是全才。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全才不一定每样都最好，但样样都会。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的全才常常得到老师的表扬。", "target_word": "全才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "全才：在各个方面都有才能的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6f10e89-3216-45ca-a1f0-6c5d9749bac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全才", "is_correct": true, "explanation": "“全才”指各方面都有才能的人，与“学习和运动都很好”相合。"}, {"text": "木头", "is_correct": false, "explanation": "语义：“木头”指木料，也可比喻呆笨的人，与“学习和运动都很好”矛盾。"}, {"text": "全景", "is_correct": false, "explanation": "语义：“全景”指整体的景象，不指人，与“学习和运动都很好”的描述不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能指孩子。"}], "explanations": {"全才": "“全才”指各方面都有才能的人，与“学习和运动都很好”相合。", "木头": "语义：“木头”指木料，也可比喻呆笨的人，与“学习和运动都很好”矛盾。", "全景": "语义：“全景”指整体的景象，不指人，与“学习和运动都很好”的描述不符。", "桌子": "语义：“桌子”是家具，不能指孩子。"}, "sentence_index": 0, "correct_answer": "全才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一条全才，什么都会。", "explanation": "这里应该用〈个〉或〈位〉。“条”用于细长的东西，不能用来数指人的“全才”。"}, {"text": "他是个全才，只擅长修车。", "explanation": "这里应该用〈专才〉。全才指各方面都有才能，只擅长修车的人应称〈专才〉。"}, {"text": "他是一包全才，什么都会。", "explanation": "这里应该用〈个〉或〈位〉。“包”用于包装起来的东西，不能用来数指人的“全才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全才", "is_correct": true, "explanation": "“全才”指多方面都能胜任的人，与“既能进攻又能防守”相合。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：“裁判”是执法人员，不参加比赛，与“既能进攻又能防守”矛盾。"}, {"text": "全场", "is_correct": false, "explanation": "搭配：“全场”指整个场地或全体观众，不能用来指一名球员。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“观众”是看比赛的人，不参加进攻和防守，句意不通。"}], "explanations": {"全才": "“全才”指多方面都能胜任的人，与“既能进攻又能防守”相合。", "裁判": "语义：“裁判”是执法人员，不参加比赛，与“既能进攻又能防守”矛盾。", "全场": "搭配：“全场”指整个场地或全体观众，不能用来指一名球员。", "观众": "语义：“观众”是看比赛的人，不参加进攻和防守，句意不通。"}, "sentence_index": 6, "correct_answer": "全才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一幅全才，唱歌画画都很好。", "explanation": "这里应该用〈个〉或〈位〉。“幅”用于字画，不能用来数指人的“全才”。"}, {"text": "他是个全才，只懂法律。", "explanation": "这里应该用〈专才〉。全才指各方面都有才能，只懂一个领域的人应称〈专才〉。"}, {"text": "他是一首全才，什么都会。", "explanation": "这里应该用〈个〉或〈位〉。“首”用于诗歌歌曲，不能用来数指人的“全才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个很全才，会学习，也会运动。", "corrected_sentence": "他是个全才，会学习，也会运动。", "error_description": "“很”不能修饰名词“全才”，应去掉“很”，直接说“是个全才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是件全才，会画画，也会唱歌。", "corrected_sentence": "他是个全才，会画画，也会唱歌。", "error_description": "“件”用于物品，不能用来数指人的“全才”，应改为量词“个”或“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbb2a803-8e2a-4276-8838-946f8913bb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93425, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "“继续”与“暂停”是反义词，指接着做下去，与“先暂停”相对。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见，与“暂停”没有反义关系。"}, {"text": "安排", "is_correct": false, "explanation": "“安排”指筹划部署，与“暂停”没有反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指动身上路，与“暂停”没有反义关系。"}], "correct_answer": "继续", "explanations": {"继续": "“继续”与“暂停”是反义词，指接着做下去，与“先暂停”相对。", "讨论": "“讨论”指交换意见，与“暂停”没有反义关系。", "安排": "“安排”指筹划部署，与“暂停”没有反义关系。", "出发": "“出发”指动身上路，与“暂停”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93425, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "“继续”与“暂停”是反义词，指接着进行，与“游戏暂停后”相对。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏的东西，与“暂停”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走走，与“暂停”没有反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "“收拾”指整理物品，与“暂停”没有反义关系。"}], "correct_answer": "继续", "explanations": {"继续": "“继续”与“暂停”是反义词，指接着进行，与“游戏暂停后”相对。", "修理": "“修理”指修复损坏的东西，与“暂停”没有反义关系。", "散步": "“散步”指随意走走，与“暂停”没有反义关系。", "收拾": "“收拾”指整理物品，与“暂停”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93425, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "暂停是先停下来，过一会儿再继续。", "primary_collocate": null, "pronunciation": "zàn tíng", "ipa": "tsan˥˩ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "比赛暂停了，大家去喝水。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请暂停一下，我接个电话。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影暂停了，我去倒杯水。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让大家先暂停一下，休息十分钟。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，比赛先暂停一下，等雨小了接着进行。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他按了一下键，把音乐暂停了。", "target_word": "暂停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频暂停着，我去开个门。", "target_word": "暂停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太累时，可以暂停一会儿。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先暂停讨论，吃完饭再说。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏暂停后，他赶快回了条短信。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "暂停了", "label": "完成体标"}, {"form": "暂停过", "label": "经历体标"}, {"form": "暂停键", "label": "复合词"}, {"form": "暫停", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事中途先停一下，马上或稍后接着做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e00da9fe-c9f4-4fde-8aa7-2a7d288258f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93425, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暂停", "is_correct": true, "explanation": "暂停（zàn tíng）指中途先停下，是听到的目标词。"}, {"text": "暂定", "is_correct": false, "explanation": "dìng（第四声）与 tíng 声母不同（d 与 t），声调也不同，意思是暂时确定。"}, {"text": "赞同", "is_correct": false, "explanation": "tóng（第二声）与 tíng 韵尾不同（ong 与 ing），意思是表示同意。"}, {"text": "展厅", "is_correct": false, "explanation": "zhǎn tīng 与 zàn tíng 声母（zh 与 z）和声调都不同，意思是展览用的大厅。"}, {"text": "暂行", "is_correct": false, "explanation": "xíng 与 tíng 声母不同（x 与 t），意思是暂时施行。"}], "explanations": {"暂停": "暂停（zàn tíng）指中途先停下，是听到的目标词。", "暂定": "dìng（第四声）与 tíng 声母不同（d 与 t），声调也不同，意思是暂时确定。", "赞同": "tóng（第二声）与 tíng 韵尾不同（ong 与 ing），意思是表示同意。", "展厅": "zhǎn tīng 与 zàn tíng 声母（zh 与 z）和声调都不同，意思是展览用的大厅。", "暂行": "xíng 与 tíng 声母不同（x 与 t），意思是暂时施行。"}, "sentence_index": null, "correct_answer": "暂停"}, "level_3": {"options": [{"text": "暂停", "is_correct": true, "explanation": "“暂停”表示中途先停下，与“大家去喝水”的休息情境相符。"}, {"text": "继续", "is_correct": false, "explanation": "语义：“继续”表示接着做，与“大家去喝水”的中途休息相矛盾。"}, {"text": "开始", "is_correct": false, "explanation": "语义：“开始”表示刚起步，与“大家去喝水”的中途休息不合。"}, {"text": "启动", "is_correct": false, "explanation": "搭配：“启动”多用于机器、程序，不用于比赛。"}], "explanations": {"暂停": "“暂停”表示中途先停下，与“大家去喝水”的休息情境相符。", "继续": "语义：“继续”表示接着做，与“大家去喝水”的中途休息相矛盾。", "开始": "语义：“开始”表示刚起步，与“大家去喝水”的中途休息不合。", "启动": "搭配：“启动”多用于机器、程序，不用于比赛。"}, "sentence_index": 0, "correct_answer": "暂停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他暂停了吸烟，从此再也不碰香烟。", "explanation": "这里应该用〈停止〉。暂停说明之后还会恢复，“从此再也不碰”表示彻底停下，要用停止。"}, {"text": "这次展览已经暂停，以后永远不再举办了。", "explanation": "这里应该用〈取消〉。暂停表示之后还会恢复，与“永远不再举办”矛盾，要用取消。"}, {"text": "他在床上暂停了一整天。", "explanation": "这里应该用〈休息〉。暂停指中途停下正在进行的事，之后接着做；在床上待一整天要用休息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暂停", "is_correct": true, "explanation": "“暂停”表示视频停住，与“我去开个门”相符。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：“结束”是一次完成的动作，不能用“着”表示持续的状态，“视频结束着”不说。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指把内容去掉，不能和“着”表示持续状态，与“我去开个门”的短暂离开不符。"}, {"text": "退出", "is_correct": false, "explanation": "搭配：“退出”多指离开程序或场所，不用于描述视频的状态。"}], "explanations": {"暂停": "“暂停”表示视频停住，与“我去开个门”相符。", "结束": "搭配：“结束”是一次完成的动作，不能用“着”表示持续的状态，“视频结束着”不说。", "删除": "语义：“删除”指把内容去掉，不能和“着”表示持续状态，与“我去开个门”的短暂离开不符。", "退出": "搭配：“退出”多指离开程序或场所，不用于描述视频的状态。"}, "sentence_index": 6, "correct_answer": "暂停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂暂停了，以后再也不开工了。", "explanation": "这里应该用〈倒闭〉。暂停指暂时停止、之后会恢复；“以后再也不开工”说的是彻底停业，要用倒闭。"}, {"text": "两国暂停了所有合作，以后永远不再往来。", "explanation": "这里应该用〈终止〉。暂停说明之后还会恢复，“永远不再往来”是彻底结束，要用终止。"}, {"text": "他们的婚约已经暂停，各自去过新生活了。", "explanation": "这里应该用〈解除〉。暂停指暂时停止，不能用来指婚约这种关系的彻底结束。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说到这里，暂停起来，等大家安静。", "corrected_sentence": "他说到这里，暂停下来，等大家安静。", "error_description": "“暂停”后面的趋向补语应说“下来”，表示停止下来；“起来”表示开始，这里不能用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你先暂停一下了，我去接杯水。", "corrected_sentence": "你先暂停一下，我去接杯水。", "error_description": "祈使句“你先……”表示请对方先停下，“暂停一下”后不加“了”，应说“你先暂停一下”，不能说“你先暂停一下了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "“继续”与“暂停”是反义词，指业务接着进行，与“学校暂停了活动”相对。"}, {"text": "投诉", "is_correct": false, "explanation": "“投诉”指向有关部门反映问题，与“暂停”没有反义关系。"}, {"text": "批准", "is_correct": false, "explanation": "“批准”指同意、认可，与“暂停”没有反义关系。"}, {"text": "更新", "is_correct": false, "explanation": "“更新”指换成新的，与“暂停”没有反义关系。"}], "correct_answer": "继续", "explanations": {"继续": "“继续”与“暂停”是反义词，指业务接着进行，与“学校暂停了活动”相对。", "投诉": "“投诉”指向有关部门反映问题，与“暂停”没有反义关系。", "批准": "“批准”指同意、认可，与“暂停”没有反义关系。", "更新": "“更新”指换成新的，与“暂停”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "“继续”与“暂停”是反义词，这条路“继续通行”与“暂停通行”相对。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏的东西，与“暂停”没有反义关系。"}, {"text": "装饰", "is_correct": false, "explanation": "“装饰”指美化布置，与“暂停”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“暂停”没有反义关系。"}], "correct_answer": "继续", "explanations": {"继续": "“继续”与“暂停”是反义词，这条路“继续通行”与“暂停通行”相对。", "修理": "“修理”指修复损坏的东西，与“暂停”没有反义关系。", "装饰": "“装饰”指美化布置，与“暂停”没有反义关系。", "搬运": "“搬运”指把东西从一处移到另一处，与“暂停”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "临时停止，之后还可能继续。", "primary_collocate": null, "pronunciation": "zàn tíng", "ipa": "tsan˥˩ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "因为大雾，航班暂停起飞。", "target_word": "暂停", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店暂停营业，下周才开门。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司因为修路，暂停了送货服务。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校暂停了所有的户外活动。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁暂停运行，请改坐公共汽车。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "由于天气不好，演出暂停了一周。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院暂停接收新病人，等通知再说。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站正在维修，注册功能暂停使用。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们暂停了合作，准备明年再谈。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路暂停通行，三天后才开放。", "target_word": "暂停", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "暂停了", "label": "完成体标"}, {"form": "暂停过", "label": "经历体标"}, {"form": "暂停键", "label": "复合词"}, {"form": "暫停", "label": "繁体"}], "register": "中性", "sense_fingerprint": "业务、活动、服务因故临时停止，以后可能恢复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e00da9fe-c9f4-4fde-8aa7-2a7d288258f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暂停", "is_correct": true, "explanation": "暂停（zàn tíng）指临时停止，是听到的目标词。"}, {"text": "暂定", "is_correct": false, "explanation": "dìng（第四声）与 tíng 声母不同（d 与 t），声调也不同，意思是暂时确定。"}, {"text": "赞同", "is_correct": false, "explanation": "tóng（第二声）与 tíng 韵尾不同（ong 与 ing），意思是表示同意。"}, {"text": "展厅", "is_correct": false, "explanation": "zhǎn tīng 与 zàn tíng 声母（zh 与 z）和声调都不同，意思是展览用的大厅。"}, {"text": "暂行", "is_correct": false, "explanation": "xíng 与 tíng 声母不同（x 与 t），意思是暂时施行。"}], "explanations": {"暂停": "暂停（zàn tíng）指临时停止，是听到的目标词。", "暂定": "dìng（第四声）与 tíng 声母不同（d 与 t），声调也不同，意思是暂时确定。", "赞同": "tóng（第二声）与 tíng 韵尾不同（ong 与 ing），意思是表示同意。", "展厅": "zhǎn tīng 与 zàn tíng 声母（zh 与 z）和声调都不同，意思是展览用的大厅。", "暂行": "xíng 与 tíng 声母不同（x 与 t），意思是暂时施行。"}, "sentence_index": null, "correct_answer": "暂停"}, "level_3": {"options": [{"text": "暂停", "is_correct": true, "explanation": "“暂停”表示临时停止，与“因为大雾”的停飞原因相符。"}, {"text": "继续", "is_correct": false, "explanation": "语义：“继续”表示接着进行，与“因为大雾”的停飞原因相反。"}, {"text": "允许", "is_correct": false, "explanation": "语义：“允许”表示同意，与“因为大雾”的停飞原因不合。"}, {"text": "开放", "is_correct": false, "explanation": "搭配与语义：“开放”指对外提供服务，不能说“航班开放起飞”，与大雾停飞的情境相反。"}], "explanations": {"暂停": "“暂停”表示临时停止，与“因为大雾”的停飞原因相符。", "继续": "语义：“继续”表示接着进行，与“因为大雾”的停飞原因相反。", "允许": "语义：“允许”表示同意，与“因为大雾”的停飞原因不合。", "开放": "搭配与语义：“开放”指对外提供服务，不能说“航班开放起飞”，与大雾停飞的情境相反。"}, "sentence_index": 0, "correct_answer": "暂停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市暂停营业，以后再也不开门了。", "explanation": "这里应该用〈倒闭〉。暂停指暂时停止、之后会恢复；“以后再也不开门”说的是彻底停业，要用倒闭。"}, {"text": "博物馆已经暂停，欢迎大家来参观。", "explanation": "这里应该用〈开放〉。暂停是停止服务，与“欢迎大家来参观”矛盾。"}, {"text": "这次活动已经暂停，以后不会再办了。", "explanation": "这里应该用〈取消〉。暂停表示之后还会恢复，与“不会再办”矛盾，要用取消。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暂停", "is_correct": true, "explanation": "“暂停”表示暂时停止接收，与“等通知再说”相符。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”的对象是人，不能说“表扬接收新病人”。"}, {"text": "公布", "is_correct": false, "explanation": "搭配：“公布”指对外发布消息，不能用作“医院……接收新病人”的谓语，与“等通知再说”也不合。"}, {"text": "启动", "is_correct": false, "explanation": "搭配：“启动”多用于程序或项目，不用于医院接收病人。"}], "explanations": {"暂停": "“暂停”表示暂时停止接收，与“等通知再说”相符。", "表扬": "搭配：“表扬”的对象是人，不能说“表扬接收新病人”。", "公布": "搭配：“公布”指对外发布消息，不能用作“医院……接收新病人”的谓语，与“等通知再说”也不合。", "启动": "搭配：“启动”多用于程序或项目，不用于医院接收病人。"}, "sentence_index": 6, "correct_answer": "暂停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件服务已经暂停，用户以后再也不能登录了。", "explanation": "这里应该用〈终止〉。暂停说明之后还会恢复，“以后再也不能登录”是彻底结束，要用终止。"}, {"text": "这条线路已经暂停，每天都有车。", "explanation": "这里应该用〈开通〉。暂停指停止服务，与“每天都有车”矛盾。"}, {"text": "这家新店今天终于暂停了，大家都很高兴。", "explanation": "这里应该用〈开业〉。暂停指停止营业，不用来说新店开张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为台风，渡轮暂停了运营了两天。", "corrected_sentence": "因为台风，渡轮暂停运营了两天。", "error_description": "“暂停”后多加了一个“了”：“运营”后已有“了”，动词之间不能重复用“了”；应说“暂停运营了两天”，不能说“暂停了运营了两天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店很暂停营业，等装修好再开。", "corrected_sentence": "这家店暂停营业，等装修好再开。", "error_description": "“很”一般不修饰“暂停营业”这类动作动词（可说“很喜欢”，不说“很暂停”），应去掉“很”，说“这家店暂停营业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
