INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全程是从头到尾的整段路。", "primary_collocate": null, "pronunciation": "quán chéng", "ipa": "tɕʰyɛn˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这次比赛全程十公里。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全程坐地铁要一个小时。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开车走了全程的一半。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他全程都骑着自行车。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全程高速，路上很快。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从家到公司，全程不到五公里。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全程走路，我累坏了。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路全程都有路灯。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车全程要走八个小时。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用两天走完了全程。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全程票", "label": "复合"}], "register": "中性", "sense_fingerprint": "从起点到终点的整段路程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93427, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全程", "is_correct": true, "explanation": "全程 quán chéng：从起点到终点的整段路程，即本题目标词。"}, {"text": "全称", "is_correct": false, "explanation": "全称 quán chēng 与全程 quán chéng 只差第二音节的声调（chēng 为第一声，chéng 为第二声），意思是完整的名称。"}, {"text": "全长", "is_correct": false, "explanation": "全长 quán cháng 与全程 quán chéng 第二音节只差元音（cháng 为 a，chéng 为 e），意思是整体的长度。"}, {"text": "前程", "is_correct": false, "explanation": "前程 qián chéng 与全程 quán chéng 第一音节只差介音（qián 为 i，quán 为 u），意思是前途。"}, {"text": "传承", "is_correct": false, "explanation": "传承 chuán chéng 与全程 quán chéng 第一音节声母不同（ch 与 q），意思是传递继承。"}], "explanations": {"全程": "全程 quán chéng：从起点到终点的整段路程，即本题目标词。", "全称": "全称 quán chēng 与全程 quán chéng 只差第二音节的声调（chēng 为第一声，chéng 为第二声），意思是完整的名称。", "全长": "全长 quán cháng 与全程 quán chéng 第二音节只差元音（cháng 为 a，chéng 为 e），意思是整体的长度。", "前程": "前程 qián chéng 与全程 quán chéng 第一音节只差介音（qián 为 i，quán 为 u），意思是前途。", "传承": "传承 chuán chéng 与全程 quán chéng 第一音节声母不同（ch 与 q），意思是传递继承。"}, "sentence_index": null, "correct_answer": "全程"}, "level_3": {"options": [{"text": "全程", "is_correct": true, "explanation": "全程：从头到尾的整段路，可以说“全程十公里”，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不用公里计量，“这次比赛时间十公里”不成立。"}, {"text": "选手", "is_correct": false, "explanation": "语义：选手是人，不能用长度来计量，“选手十公里”说不通。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是人，不能用公里衡量，句中的空位不能填入它。"}], "explanations": {"全程": "全程：从头到尾的整段路，可以说“全程十公里”，符合句意。", "时间": "搭配：“时间”不用公里计量，“这次比赛时间十公里”不成立。", "选手": "语义：选手是人，不能用长度来计量，“选手十公里”说不通。", "观众": "语义：观众是人，不能用公里衡量，句中的空位不能填入它。"}, "sentence_index": 0, "correct_answer": "全程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们骑车走了一把全程。", "explanation": "这里应该去掉〈一把〉，说“走了全程”。全程前不加“一把”，“把”只用于有把手的器物。"}, {"text": "这座全程很长。", "explanation": "这里应该用〈这段路〉。“座”用于山、楼等大型固定物体，“全程”也不受“这座”修饰。"}, {"text": "这个房间全程有二十平方米。", "explanation": "这里应该用〈面积〉。全程指路程或过程，不能用来计量房间的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全程", "is_correct": true, "explanation": "全程：整段路程，此处作状语修饰“走路”，表示从头到尾。"}, {"text": "车辆", "is_correct": false, "explanation": "语义：车辆不能步行，“车辆走路”说不通。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”不能作“走路”的修饰语，搭配不当。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车不能步行，“火车走路，我累坏了”句意不通。"}], "explanations": {"全程": "全程：整段路程，此处作状语修饰“走路”，表示从头到尾。", "车辆": "语义：车辆不能步行，“车辆走路”说不通。", "速度": "搭配：“速度”不能作“走路”的修饰语，搭配不当。", "火车": "语义：火车不能步行，“火车走路，我累坏了”句意不通。"}, "sentence_index": 6, "correct_answer": "全程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全程的同学都来了。", "explanation": "这里应该用〈全班〉。全程指路程或过程，不能用来指班级的全体同学。"}, {"text": "全程城市都在下雪。", "explanation": "这里应该用〈整个〉。全程指路程或过程，不能用来形容“城市”。"}, {"text": "全程人民都很关心这场比赛。", "explanation": "这里应该用〈全国〉。全程不指地域范围，不能修饰“人民”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走了完全程，一共八公里。", "corrected_sentence": "我们走完了全程，一共八公里。", "error_description": "错误形式“走了完全程”，正确形式“走完了全程”。“完”是结果补语，必须紧跟动词“走”，不能放在“了”和“全程”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的全程走路，累坏了。", "corrected_sentence": "我全程走路，累坏了。", "error_description": "多加了“的”。“全程”作状语修饰“走路”时不加“的”；加“的”后“我的全程”变成名词短语，无法修饰“走路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
