INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整个过程，即从开始到结束的全部经过。", "primary_collocate": null, "pronunciation": "quán chéng", "ipa": "tɕʰyɛn˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师全程都在笑。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术全程很顺利。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我全程没有说话。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他全程陪着我看病。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试全程有人看着。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议全程只有二十分钟。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛全程我都很紧张。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事全程有记录。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子全程没有哭。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游全程笑着给我们讲故事。", "target_word": "全程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全程票", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情从开始到结束的整个过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93428, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全程", "is_correct": true, "explanation": "全程 quán chéng：从开始到结束的整个过程，即本题目标词。"}, {"text": "全称", "is_correct": false, "explanation": "全称 quán chēng 与全程 quán chéng 只差第二音节的声调（chēng 为第一声，chéng 为第二声），意思是完整的名称。"}, {"text": "全长", "is_correct": false, "explanation": "全长 quán cháng 与全程 quán chéng 第二音节只差元音（cháng 为 a，chéng 为 e），意思是整体的长度。"}, {"text": "前程", "is_correct": false, "explanation": "前程 qián chéng 与全程 quán chéng 第一音节只差介音（qián 为 i，quán 为 u），意思是前途。"}, {"text": "传承", "is_correct": false, "explanation": "传承 chuán chéng 与全程 quán chéng 第一音节声母不同（ch 与 q），意思是传递继承。"}], "explanations": {"全程": "全程 quán chéng：从开始到结束的整个过程，即本题目标词。", "全称": "全称 quán chēng 与全程 quán chéng 只差第二音节的声调（chēng 为第一声，chéng 为第二声），意思是完整的名称。", "全长": "全长 quán cháng 与全程 quán chéng 第二音节只差元音（cháng 为 a，chéng 为 e），意思是整体的长度。", "前程": "前程 qián chéng 与全程 quán chéng 第一音节只差介音（qián 为 i，quán 为 u），意思是前途。", "传承": "传承 chuán chéng 与全程 quán chéng 第一音节声母不同（ch 与 q），意思是传递继承。"}, "sentence_index": null, "correct_answer": "全程"}, "level_3": {"options": [{"text": "全程", "is_correct": true, "explanation": "全程：从开始到结束的整个过程，此处作状语修饰“笑”，与句意相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是会笑的主体，“作业都在笑”说不通。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是物件，不会笑，句子不成立。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“高度”是量度，不能与“都在笑”搭配，搭配不当。"}], "explanations": {"全程": "全程：从开始到结束的整个过程，此处作状语修饰“笑”，与句意相符。", "作业": "语义：作业不是会笑的主体，“作业都在笑”说不通。", "电话": "语义：电话是物件，不会笑，句子不成立。", "高度": "搭配：“高度”是量度，不能与“都在笑”搭配，搭配不当。"}, "sentence_index": 0, "correct_answer": "全程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把全程很顺利。", "explanation": "这里应该去掉〈这把〉，说“全程很顺利”。“把”用于有柄的器物，不能修饰过程。"}, {"text": "我们经历了一本全程，很难忘。", "explanation": "这里应该去掉〈一本〉，说“经历了全过程”。“本”用于书籍，不能修饰事件的过程。"}, {"text": "他全程很高，打篮球很厉害。", "explanation": "这里应该用〈个子〉。全程指路程或过程，不能用来形容人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全程", "is_correct": true, "explanation": "全程：从开始到结束的整个过程，此处作状语，与“我都很紧张”相符。"}, {"text": "比赛服", "is_correct": false, "explanation": "语义：比赛服是衣物，不能构成“我都很紧张”的范围，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能作“比赛”之后的时间或范围，搭配不当。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，无法作为“我都很紧张”的前提，句子不成立。"}], "explanations": {"全程": "全程：从开始到结束的整个过程，此处作状语，与“我都很紧张”相符。", "比赛服": "语义：比赛服是衣物，不能构成“我都很紧张”的范围，句意不通。", "味道": "搭配：“味道”不能作“比赛”之后的时间或范围，搭配不当。", "蛋糕": "语义：蛋糕是食物，无法作为“我都很紧张”的前提，句子不成立。"}, "sentence_index": 6, "correct_answer": "全程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书全程有三百页。", "explanation": "这里应该用〈全书〉。全程指路程或过程，不能用来指整本书的页数。"}, {"text": "全程的学生都放假了。", "explanation": "这里应该用〈全国〉。全程不表示地域范围，不能修饰“学生”。"}, {"text": "全程的老师都来参加了。", "explanation": "这里应该用〈全校〉。全程不表示学校这一范围，不能修饰“老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的全程陪着我做手术。", "corrected_sentence": "妈妈全程陪着我做手术。", "error_description": "错误形式“妈妈的全程陪着我做手术”，多加了“的”。正确形式“妈妈全程陪着我做手术”，“全程”应直接作状语修饰“陪着”。加“的”后“妈妈的全程”变成名词短语，不能作“陪”的主语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场手术全程的录像了。", "corrected_sentence": "这场手术全程录像了。", "error_description": "错误形式“这场手术全程的录像了”，多加了“的”。正确形式“这场手术全程录像了”，“全程”作状语修饰动词“录像”，不能加“的”。加“的”后“全程的录像”变成名词短语，无法再接动词“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
