INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93429, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "有一点是有一些，但不太多。", "primary_collocate": null, "pronunciation": "yǒu yì diǎn", "ipa": "joʊ˨˩ i˥˩ tjɛn˨˩", "syllable_count": 3, "sentences": [{"text": "我现在有一点时间。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有一点牛奶。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里有一点钱，可以先用。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一点想法，想和你说说。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一点水，小心。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有一点时间吗？", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子里有一点茶，你喝吧。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做过这个工作，有一点经验。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里只有一点米饭。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我包里有一点零钱，够坐车。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有一点儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "有一点+名词：表示拥有或存在少量的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有过", "is_correct": false, "explanation": "体貌：“过”表示曾经有过，与表示当下的“现在”冲突，不能说“我现在有过时间”"}, {"text": "有一个", "is_correct": false, "explanation": "搭配：量词“个”不能用来计量“时间”，“一个时间”不成立"}, {"text": "有一点", "is_correct": true, "explanation": "“有一点”表示有少量的时间，符合“我现在”的语境"}, {"text": "有一片", "is_correct": false, "explanation": "搭配：量词“片”用于叶子、面积等，不能修饰“时间”"}], "explanations": {"有过": "体貌：“过”表示曾经有过，与表示当下的“现在”冲突，不能说“我现在有过时间”", "有一个": "搭配：量词“个”不能用来计量“时间”，“一个时间”不成立", "有一点": "“有一点”表示有少量的时间，符合“我现在”的语境", "有一片": "搭配：量词“片”用于叶子、面积等，不能修饰“时间”"}, "sentence_index": 0, "correct_answer": "有一点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湖里有一点鱼，多得数不清。", "explanation": "这里应该用〈很多〉。“有一点”表示数量少，与“多得数不清”的大量相矛盾"}, {"text": "我家里有一点书，三个书架都放满了。", "explanation": "这里应该用〈很多〉。“有一点”表示数量少，与“三个书架都放满了”的大量相矛盾"}, {"text": "我们班有一点同学今天请假了。", "explanation": "这里应该用〈有几个〉。“有一点”不能修饰可数的人，说人数少要用〈有几个〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有", "is_correct": false, "explanation": "语义：“没有”否定了存在，与“你喝吧”的邀请相矛盾"}, {"text": "要", "is_correct": false, "explanation": "配价：“要”需要有意愿的主语，“杯子里要茶”不成立"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：“倒掉”表示把茶倒出去，与“你喝吧”相矛盾"}, {"text": "有一点", "is_correct": true, "explanation": "“有一点”表示杯子里有少量的茶，符合“你喝吧”的语境"}], "explanations": {"没有": "语义：“没有”否定了存在，与“你喝吧”的邀请相矛盾", "要": "配价：“要”需要有意愿的主语，“杯子里要茶”不成立", "倒掉": "语义：“倒掉”表示把茶倒出去，与“你喝吧”相矛盾", "有一点": "“有一点”表示杯子里有少量的茶，符合“你喝吧”的语境"}, "sentence_index": 6, "correct_answer": "有一点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库里有一点粮食，够全城人吃一年。", "explanation": "这里应该用〈有很多〉。“有一点”表示数量少，与“够全城人吃一年”所需的大量粮食相矛盾"}, {"text": "我口袋里有一点零钱，正好够买下整个超市。", "explanation": "这里应该用〈不少〉。“有一点”表示数量少，与“正好够买下整个超市”所需的钱数相矛盾"}, {"text": "油桶里有一点三升油，够做两天饭。", "explanation": "“有一点”表示少量、不确定的数量，不能和具体数字“三升”连用；说具体数量要直接说“有三升油”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "锅里还有一点个汤，你再喝点吧。", "corrected_sentence": "锅里还有一点汤，你再喝点吧。", "error_description": "量词错误：“一点”本身已是数量词，后面不能再加量词“个”。应去掉“个”，改为“有一点汤”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "瓶子里还有有一点酱油，够做这道菜。", "corrected_sentence": "瓶子里还有一点酱油，够做这道菜。", "error_description": "重复错误：“有一点”是一个整体，“有”不能重复。应去掉多余的“有”，改为“有一点酱油”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
