INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93430, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "略微；稍微。表示程度较轻。", "primary_collocate": null, "pronunciation": "yǒu yì diǎn", "ipa": "joʊ˨˩ i˥˩ tjɛn˨˩", "syllable_count": 3, "sentences": [{"text": "今天有一点冷。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服有一点贵。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一点饿，想先吃饭。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜有一点咸。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天有一点不高兴。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，我有一点紧张。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路有一点远，我们坐车吧。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话有一点快，我没听懂。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一点累，想休息一下。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有一点热，把窗打开吧。", "target_word": "有一点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有点", "label": "简式"}, {"form": "有一点儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "有一点+形容词/心理动词：程度轻，常表示不太满意的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很多", "is_correct": false, "explanation": "语义：“很多”表示数量多，不能用来修饰“冷”这样的状态"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”表示总计，不能修饰形容词“冷”"}, {"text": "有一点", "is_correct": true, "explanation": "“有一点”表示程度轻，修饰形容词“冷”，符合语境"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指不久以前，与“今天”这个整天的时间范围不合"}], "explanations": {"很多": "语义：“很多”表示数量多，不能用来修饰“冷”这样的状态", "一共": "搭配：“一共”表示总计，不能修饰形容词“冷”", "有一点": "“有一点”表示程度轻，修饰形容词“冷”，符合语境", "刚才": "语义：“刚才”指不久以前，与“今天”这个整天的时间范围不合"}, "sentence_index": 0, "correct_answer": "有一点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湖水有一点深，深得能淹没三层楼。", "explanation": "这里应该用〈非常〉。“有一点”程度轻，不能与“深得能淹没三层楼”这样的极端程度连用"}, {"text": "这是我吃过最好吃的菜，有一点好吃。", "explanation": "这里应该用〈很〉。“有一点”程度轻，与“吃过最好吃的菜”的极高评价相矛盾"}, {"text": "这个故事有一点悲伤，读完哭得一塌糊涂。", "explanation": "这里应该用〈特别〉。“有一点”程度轻，不能与“哭得一塌糊涂”所表示的强烈情绪连用"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定范围，不能修饰表示程度的“远”，句子意思不通"}, {"text": "在", "is_correct": false, "explanation": "语法：“在”不能直接修饰形容词“远”，“在远”不成立，句子不通"}, {"text": "有一点", "is_correct": true, "explanation": "“有一点”表示程度轻，修饰形容词“远”，符合“我们坐车吧”的语境"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中并没有转折的语境"}], "explanations": {"只": "语义：“只”表示限定范围，不能修饰表示程度的“远”，句子意思不通", "在": "语法：“在”不能直接修饰形容词“远”，“在远”不成立，句子不通", "有一点": "“有一点”表示程度轻，修饰形容词“远”，符合“我们坐车吧”的语境", "却": "语义：“却”表示转折，句中并没有转折的语境"}, "sentence_index": 6, "correct_answer": "有一点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子有一点三米长，正好用来晾衣服。", "explanation": "“有一点”表示程度轻、不具体，不能和精确的“三米”连用；说具体长度要直接说“三米长”"}, {"text": "这个人有一点已婚。", "explanation": "“已婚”表示有或没有的状态，没有程度之分，不能用“有一点”表示程度轻"}, {"text": "他有一点通过考试。", "explanation": "“有一点”只用于修饰形容词或心理动词，不能修饰“通过考试”这样已经完成的动作"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这碗汤有一点很烫，你慢点喝。", "corrected_sentence": "这碗汤有一点烫，你慢点喝。", "error_description": "程度词重复：“有一点”与“很”都表示程度，不能同时修饰“烫”。应去掉“很”，改为“这碗汤有一点烫”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件大衣有一点非常长，你换一件吧。", "corrected_sentence": "这件大衣有一点长，你换一件吧。", "error_description": "程度词冲突：“有一点”表示程度轻，“非常”表示程度高，两者不能同时修饰“长”。应去掉“非常”，改为“这件大衣有一点长”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
