INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93431, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "刑法是规定做了坏事要怎样受罚的法律。", "primary_collocate": null, "pronunciation": "xíng fǎ", "ipa": "ɕiŋ˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "刑法规定偷东西要受罚。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习刑法。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天给我们讲了刑法。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是讲刑法的。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做坏事的人要按刑法受罚。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对刑法很感兴趣。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑法告诉人们哪些事不能做。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都应该知道一点刑法。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过很多关于刑法的书。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑法不允许打人。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}], "register": "中性", "sense_fingerprint": "刑法：规定做坏事要受什么惩罚的法律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
